INSERT INTO `qms_document_blocks` VALUES ('00cc66d5-cfec-4906-a12d-2d61fa8a9ea5','00000000-0000-0000-0000-000000000001','0298e975-ff58-4c04-b700-8e0cf4cd55d0','9f92ea6a-b554-401a-b1b5-c76269f78919',NULL,'procedure:xztc_cx_34_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司全体人员。\n',130,'现用文件/程序文件/程序文件2022/34-2022内部监控管理程序.doc#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('01e587f6-a79c-411e-b230-af8ae7d828ee','00000000-0000-0000-0000-000000000001','1e1e9194-f520-4a67-91ab-d313500615c8','e12e3730-cc7a-4ade-8704-2460e6762097',NULL,'procedure:xztc_cx_02_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《不符合检测工作管理程序》 XZTC/CX-15-2022\n\n《记录控制程序》 XZTC/CX-19-2022\n\n《内务与安全管理程序》 XZTC/CX-33-2022\n',160,'现用文件/程序文件/程序文件2022/02-2022设施与环境条件控制和维护程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('029ec1c5-2d34-43b7-8c1e-c04f770d96e8','00000000-0000-0000-0000-000000000001','575be231-b422-4860-84b2-bcd28c6a6d7f','296ce497-e0aa-4f43-a7f0-0b59a7e6e6f8',NULL,'procedure:xztc_cx_15_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 相关责任部门：负责对不符合检测工作采取纠正措施。\n\n3.2检测部经理\n\n3.2.1协助技术负责人对技术方面的不符合工作做出评价；\n\n3.2.2组织开展对技术活动方面的不符合工作整改。\n\n3.2 监督员：负责对不符合的纠正措施的有效性验证。\n\n3.3.1负责对不符合工作的日常监督；\n\n3.3.2负责一般不符合工作的识别、评价，并跟踪验证不符合工作的处置结果。\n\n3.3 技术负责人：负责对不符合检测工作的严重性进行评价，并对严重不符合提出处理意见和批准检测工作的恢复。\n\n3.4其它责任人员\n\n3.4.1 报告签发人负责对检测报告证书的检查；\n\n3.4.2 内审员负责内审过程中不符合的识别、评价；\n\n3.4.3 各责任岗位人员负责对不符合工作采取措施，确保其有效性；\n\n3.4.4本公司所有员工都有责任和权力向技术/质量负责人直至公司总经理报告任何不符合并提出纠正/纠正措施的建议。\n',140,'现用文件/程序文件/程序文件2022/15-2022不符合检测工作管理程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('0327869b-47f8-4333-a7e5-033aa31bd85a','00000000-0000-0000-0000-000000000001','69032715-7174-46fa-b564-18c838e80d23','1b4fd63c-d774-4713-8a57-1bcc9ea019f3',NULL,'procedure:xztc_cx_30_2022:element:validity_of_results','','要素落实：结果有效性保证','control_requirement','### 要素落实：结果有效性保证\n\n- 程序文件：XZTC/CX-30-2022 检测结果质量控制及能力验证程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('041617b9-7d9c-4af9-97ce-6805e89453b7','00000000-0000-0000-0000-000000000001','9f720d1f-600b-423a-8082-f8987b0594cf','3a8d9ea2-2b78-4dc0-a1e8-164f02246028',NULL,'procedure:xztc_cx_06_2022:source:scope','','范围','scope','### 范围\n\n客户机密信息主要包括：\n\n2.1 客户提供的样品及其技术资料；\n\n2.2 客户的专利权；\n\n2.3 对客户送检样品检测结果的所有权；\n\n2.4 对参加实验室间比对的结果的保密。\n',130,'现用文件/程序文件/程序文件2022/06-2022保护客户机密信息程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('04208b30-030e-4429-87f7-4973829658be','00000000-0000-0000-0000-000000000001','810f7acb-fe9d-4025-a66c-0891768b873b','5901e814-4bc7-4220-898e-422827d22b6d',NULL,'procedure:xztc_cx_11_2022:source:purpose','','目的','purpose','### 目的\n\n为防止外部支持服务和所采购的供应品的质量对检测结果造成影响，特编制本程序。\n',120,'现用文件/程序文件/程序文件2022/11-2022外部支持服务和供应品管理程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('04bddf6a-e662-4556-9de0-c4bcf1a328d9','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:8_1','8.1','管理体系文件','section','## 8.1 管理体系文件\n\n8.1.1 管理体系的建立\n\n8.1.1.1 本公司最高管理者为实验室主任，实验室主任主持建立与本公司业务、检测活动范围、工作内容相适应的管理体系，制定本公司的质量方针和总体目标，并配置相应的资源，使管理体系实施运行，并不断寻求改进，以便保持管理体系的有效性。\n\n8.1.1.2 质量方针和总体目标应体现实验室的能力、公正性和一致运作。总体目标应在管理评审时加以评审。\n\n8.1.1.3 质量负责人依据《检验检测机构资质认定评审准则》（2023年版）标准的要求和本公司的质量方针，组织有关各方和人员建立文件化的管理体系。\n\n8.1.1.4 本公司管理体系建立方式\n\n依据CNAS-CL01:2018第8.1条和GB/T 27025-2019第8.1条，实验室可选择下列两种方式之一建立管理体系：\n\n方式A：管理体系满足CNAS-CL01:2018（IDT. GB/T 27025-2019）第4章至第8章的要求，本管理体系文件直接体现上述各条款的要求，且满足CNAS-CL01-G001:2024的应用要求；\n\n方式B：按照ISO 9001要求建立和维护管理体系，并能证明该管理体系支持并符合CNAS-CL01:2018第4章至第8章的要求。\n\n本公司选择并采用方式A建立管理体系，理由如下：\n\n方式A更直接体现检测实验室管理体系的特殊要求，管理文件结构与CNAS-CL01:2018条款一一对应，便于评审和审核时逐条核查；\n\n方式A的管理文件可直接引用CNAS-CL01:2018和GB/T 27025-2019的条款要求，无需额外的符合性映射工作；\n\n本公司建立和运行的质量手册、程序文件、作业指导书、记录表格四层文件体系，已完整覆盖CNAS-CL01:2018第4章至第8章的全部要求；\n\n本公司同时满足《检验检测机构资质认定评审准则》（2023年版）的要求，管理体系与评审准则条款的对应关系详见附录15《质量手册条款对照表》。\n\n8.1.2 管理体系的文件构成\n\n本公司管理体系文件的构成分为四层，包括质量手册、程序文件、作业指导书、质量和技术记录，确保检测结果达到要求的质量程度。各层文件共同构成完整的管理体系，相互支持，协调运行。\n\n第一层：《质量手册》（XZTC/SC）——是本公司管理体系运行的纲领性文件，阐述本公司质量方针、目标和管理体系各要素的要求，描述管理体系结构和文件架构，直接对应CNAS-CL01:2018第4章至第8章的条款要求。\n\n第二层：《程序文件》（XZTC/CX）——是《质量手册》的支持性文件，共计35个程序，对管理体系运行中各项重要的质量和技术活动的流程、职责分工和操作要求进行详细描述，详见附录14《程序文件目录》。\n\n第三层：《作业指导书》 ——是各种管理工作和检测工作的操作文件，规定了各项检测活动的具体操作步骤、方法、仪器操作规程等技术性文件。\n\n第四层：质量记录和技术记录——是管理体系各项活动的客观证据。质量记录包括内审记录、管理评审记录、纠正措施记录等；技术记录包括检测原始记录、设备检定校准记录、样品流转记录、人员培训记录等，检验检测原始记录和报告保存期限不少于6年。\n',820,'现用文件/质量手册（第四版）.docx#8.1','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('0538b44c-27bb-469e-b89b-140ada3c460b','00000000-0000-0000-0000-000000000001','4b1065a9-98af-473e-b8a2-3d777155a7be','52408b83-0022-4fbd-b6d1-25730e7ff996',NULL,'procedure:xztc_cx_13_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 负责内部沟通渠道及氛围的形成与促进；\n\n3.2 质量负责人应：\n\n3.2.1 负责内部沟通中各部门的协调工作，以及信息资料的管理；\n\n3.3 技术负责人及各部门负责人应：\n\n3.3.1 负责本部门的内部沟通过程中有关问题的传递、分析、处理及反馈。\n\n程序\n\n4.1 例会\n\n每月至少召开一次工作会议，以分析、协调、解决问题，提出改进意见，使公司的安全、质量、检测及管理等工作顺利展开。\n\n4.2 日常信息反馈\n\n各部门应建立信息收集、传递、处理、统计、反馈制度，建立信息记录。\n\n4.3 重要临时动态信息反馈\n\n4.3.1 信息发送传递\n\n对涉及安全、质量、检测技术和装备等方面需要解决和落实的重要问题，在不能够立即解决时，相关人员应书面写明，递交本部门负责人和质量负责人。\n\n4.3.2 信息接受处理\n\n各部门负责人接到有关信息后，必须落实专人进行处理，并填写处理意见，有关部门将问题解决后，填写处理结果。如问题需要协调解决时，由质量负责人向实验室主任汇报，协调处理。\n\n4.3.3 信息回单\n\n质量负责人将处理结果的信息反馈回信息发送人。\n\n4.4 信息反馈\n\n办公室负责用户信息、科技信息、综合信息的接收、传递、反馈工作。\n',140,'现用文件/程序文件/程序文件2022/13-2022内部沟通程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('061f9568-be01-4f79-a34e-4d1cd312bd4e','00000000-0000-0000-0000-000000000001','a01641c9-dbde-4e87-ba79-dd149c4349ba','b90e5408-7e6d-4451-bd0a-fdeccf040627',NULL,'procedure:xztc_cx_31_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 技术负责人应：\n\n3.1.1 负责检测工作的监督和控制；\n\n3.2 实验室主任应：\n\n3.2.1 负责批准年度日常监督计划；\n\n3.3 监督员应：\n\n3.3.1 负责日常的监督检查工作；\n\n3.3.2 对检测员的检测过程进行监督；\n\n3.3.3 对新进在培员工进行监督；\n\n3.3.4 对技术人员及关键支持人员进行监督。\n\n3.4 所有工作人员应：\n\n3.4.1 接受监督员的监督工作，确认监督记录并负责纠正监督中发现的问题。\n',140,'现用文件/程序文件/程序文件2022/31-2022检测工作的监督程序.docx#职责','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('083f493b-c9f1-42af-8fb9-0a0d456ea065','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_1','7.1','要求、标书和合同评审','section','## 7.1 要求、标书和合同评审\n\n本公司对来自客户的检测要求给予高度重视，制定了《客户要求、标书、合同评审程序》，以满足客户对各项要求得到实现，合同评审内容将确保以下几项：\n\n7.1.1 对客户要求，均应在合同或协议中明确作出规定，并形成文件，使双方对其规定的内容达到统一认识，文件中规定的内容应清楚明确，便于双方及检测人员的理解。\n\n7.1.2 通过合同评审明确本公司是否具备能够满足合同要求的人员、检测方法、环境设施、检测设备等资源。\n\n7.1.3 选择适当的、能满足客户要求的有效的检测方法。\n\n7.1.4 本公司的合同分为常规检测合同、特殊要求检测合同、新项目检测合同等，《客户要求、标书、合同评审程序》规定了各种合同的不同处理方法，当客户要求与合同（协议）存在异议时，本公司将与客户沟通协商，以便达成共识，使每份合同都能被本公司和客户接受。\n\n7.1.5 为保证合同的有效性，本公司对每份合同应采取不同的方式进行评审，合同评审的情况以及在执行合同期间，就客户的要求或工作结果与客户进行的讨论均应给予记录，并对记录保存。\n\n7.1.6 本公司在执行合同时，如出现任何偏离均应及时以书面形式通知客户。\n\n7.1.7 无论什么原因，如合同/协议执行过程中，任何一方提出对合同修改的需求，则应按相应的评审程序，对其修改部分再次评审，并通知与合同修改内容有关的所有人员。\n\n7.1.8 所有的合同/协议评审记录（包括修改部分及合同执行过程中与客户要求的讨论记录等）均应保存。\n\n7.1.9 本公司暂不涉及分包业务，若后期需要则会根据实际情况实施分包，分包须经客户同意，分包给满足要求的分包方。\n\n7.1.10 支持性文件\n\n《文件控制程序》 XZTC/CX-08-2018\n\n《客户要求、标书、合同评审程序》 XZTC/CX-09-2018\n\n《记录控制程序》 XZTC/CX-19-2018\n',710,'现用文件/质量手册（第四版）.docx#7.1','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('093c3b54-a656-4924-80dc-171fe0b4a7b7','00000000-0000-0000-0000-000000000001','afb48a72-ca24-408e-86d1-685bc252a4a9','f5bfe2a1-1db8-49ca-8b36-6c8c9378a7fc',NULL,'procedure:xztc_cx_23_2022:element:methods','','要素落实：方法选择、验证和确认','control_requirement','### 要素落实：方法选择、验证和确认\n\n- 程序文件：XZTC/CX-23-2022 允许方法偏离控制程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('097389eb-8b63-4d5e-bc4e-4dd3f999025b','00000000-0000-0000-0000-000000000001','c6a9947a-3e7f-4a66-b3d2-383348f9be03','534421f2-4307-4f6c-9df2-108bd6be4607',NULL,'procedure:xztc_cx_21_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《文件控制程序》 XZTC/CX-08-2022\n\n《不符合检测工作管理程序》 XZTC/CX-15-2022\n\n《实施纠正措施程序》 XZTC/CX-16-2022\n',160,'现用文件/程序文件/程序文件2022/21-2022管理评审程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('0bd89263-d28f-4a7e-9ea9-d176db705f69','00000000-0000-0000-0000-000000000001','1e1e9194-f520-4a67-91ab-d313500615c8','e12e3730-cc7a-4ade-8704-2460e6762097',NULL,'procedure:xztc_cx_02_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 设施和环境条件要求的确定\n\n4.1.1 本公司确保检测活动所需的设施和环境条件要求的实现，防止其对检测的结果产生不良影响，以保证结果的准确有效。\n\n4.1.2 技术负责人根据开展的检测项目及相关的规范、方法的要求，组织有关检测人员确定所需的设施和环境条件要求，并制定相应的技术要求，明确其控制要求，报实验室主任批准实施。不同的项目要求可能涉及：温度、湿度、照明、电力供应、振动等因素。\n\n4.2 配置及监控\n\n4.2.1 本公司设施和环境条件配置必须满足以下要求：\n\n4.2.1.1 保证动力电和照明用电的供给；\n\n4.2.1.2 对温度、湿度、振动、电源电压等要求严格控制；\n\n4.2.1.3 当与本公司相邻的区域发生对分析不利的影响时，应采取有效的隔离措\n\n施；\n\n4.2.1.4 对于有害废气物应单独存放。\n\n4.2.1.5应配备相应的安全设施及装备；\n\n4.2.1.6 满足认可准则及评审准则中对设施和环境条件中相关要求；\n\n4.2.2 设施和环境条件的配置、改造与维修\n\n4.2.2.1 检测人员根据检测活动的需要，提出对设施和环境条件的配置、改造或维修要求，形成文件，报技术负责人。\n\n4.2.2.2 技术负责人在必要时要组织相关人员对其要求的合理性进行评价审核。\n\n4.2.2.3 检测部管理和落实环境设施的维修、改造并负责日常维护、维修。\n\n4.2.2.4 新建或改建设施应按技术要求进行鉴定，合格后方可进入正常运作。\n\n4.2.3 设施和环境条件的控制、管理\n\n4.2.3.1 检测部合理分配空间，并进行必要的标识。\n\n4.2.3.2 特殊环境设施要求的管理办法，应形成制度。\n\n4.2.3.3 对环境设施条件有明确要求的所有相关法律法规、方法、程序、标准应汇总列入控制清单。\n\n4.2.3.4 相关的标准规范、方法及作业文件已明确的环境、条件的特殊要求（温度17-35℃，湿度＜60%，环境色调为白至中性灰色），该场所应配置相应的监控设施检测，操作者应按规定及时调整、处置，并记录其控制情况（见：《检测环境监控记录表》）。\n\n4.2.3.5 检测部负责对设施的配置和环境条件的提供和使用实施管理。\n\n4.2.3.6 技术负责人组织检测员定期检查设施和环境的运作、监控和记录情况。发现不符合，按《不符合检测工作管理程序》执行。\n\n4.2.3.7 当环境条件危及到检测结果时，检测人员应停止工作，报告不符合，对已检测的数据要注明无效，并采取措施保证检验结果的有效性，待环境条件恢复正常后再继续进行工作。\n\n4.2.3.8 各项检测活动都在固定场所内进行，对非固定场所检测时，应对工作场所环境和设施检查确定，要求现场具有可以保证检测结果有效性和准确性的环境条件并予以记录，必要时应在作业指导书中对环境设施附加具体的控制条件。\n\n4.2.3.9 对影响检测质量的区域的进入和使用加以控制，检测部负责组织制订有设施与环境条件控制和维护程序\n\n关管理规定，报技术负责人审批后执行，对进入控制区域的人员严格限\n\n制。实验区与办公区要保持有良好的隔离，并贴有“实验受控区”或等\n\n同标识，无关人员未经批准不随意进入实验区域，尤其是有特殊环境要求的区域应有警示，并严格限制人员的进出，以免影响环境的稳定性和 检测工作的安全。非本公司工作人员进入本公司时，应得到实验室主任的批准，并在本公司工作人员陪同下进行参观，任何人不得将未经批准的非本公司人员带入本公司参观。\n\n4.2.3.10对检测过程中产生的有害废弃物按《内务与安全管理程序》的相关规定处理。\n',150,'现用文件/程序文件/程序文件2022/02-2022设施与环境条件控制和维护程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('0bfd49e7-2a0e-4d2f-9ccf-06fe4596fb68','00000000-0000-0000-0000-000000000001','44ff5408-e03d-4859-9cd4-926a8f69fda5','948d2434-2b53-47e6-adab-cf2ee95dfc3c',NULL,'procedure:xztc_cx_09_2022:overview','','客户要求、标书、合同评审程序','section','# XZTC/CX-09-2022 客户要求、标书、合同评审程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/09-2022客户要求、标书、合同评审程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/09-2022客户要求、标书、合同评审程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('0c72a322-094a-41e1-938d-d71b9ef78a84','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_9','7.9','投诉','section','## 7.9 投诉\n\n7.9.1 受理和处理好客户的投诉与申诉是提高本公司信誉和服务质量的重要环节，也是对管理体系进行持续改进的重要依据，因此制定《处理投诉程序》，对来自客户的投诉适时作出安排并妥善处理，本公司质量目标要求客户投诉必须100%处理。\n\n7.9.2 本公司将通过各种渠道，利用与客户接触的机会收集客户的各类投诉信息，耐心接待来访投诉客户，并详细做好记录，同时受理投诉信函、投诉电话，经阅读、分类、整理成相应记录以供核实，并保留各种投诉记录。\n\n7.9.3 本公司将针对投诉信息及时开展调查，分析查找原因，提出处理方案，当投诉涉及本公司服务时间、服务态度、服务收费、检测数据时，应针对采取相应的整改措施，加强对人员的职业道德行为的培训；当客户的投诉涉及本公司的质量方针、管理体系时，应及时对本公司的管理体系及相关领域的工作进行审核。\n\n7.9.4 如客户的投诉经调查确实由本公司造成的，责任部门要仔细进行原因分析，查找导致问题产生的根本原因，并采取切实可行的整改措施，同时由本公司给客户造成的损失承担相应的经济赔偿责任。\n\n7.9.5 责任部门在采取整改措施后，质量负责人应组织对其效果进行评估与验证，只有证明问题存在的原因已完成消除后，质量负责人才能回复客户，得到客户的认可。\n\n7.9.6 投诉的处理将及时有效，按其投诉造成的不符合严重程度，制定适宜的纠正措施，使由于投诉造成的不良影响降至最低，具体可执行《不符合检测工作的控制管理程序》《实施纠正措施程序》，并保留针对投诉所开展的调查和纠正措施记录。\n\n7.9.7 支持性文件\n\n《处理投诉程序》 XZTC/CX-14-2018\n\n《不符合检测工作管理程序》 XZTC/CX-15-2018\n\n《实施纠正措施程序》 XZTC/CX-16-2018\n',790,'现用文件/质量手册（第四版）.docx#7.9','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('0c8c1190-8f30-4d67-9836-719078a7b979','00000000-0000-0000-0000-000000000001','a01641c9-dbde-4e87-ba79-dd149c4349ba','b90e5408-7e6d-4451-bd0a-fdeccf040627',NULL,'procedure:xztc_cx_31_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 在检测过程中日常需监督控制的影响质量的因素（环节）主要包括以下几项：\n\n4.1.1 检测人员（包括在培训人员）的检测活动；\n\n4.1.2 与检测相关的设施和环境条件；\n\n4.1.3 检测方法的选择及方法的确认；\n\n4.1.4 影响检测结果质量的仪器设备（包括辅助仪器）；\n\n4.1.5 测量的溯源性；\n\n4.1.6 样品的处置；\n\n4.2 监督员的确定\n\n技术负责人在确定监督人员时应从以下四个方面来选择监督人员：\n\n4.2.1 监督员的数量应足够，为确保监督工作的有效性，监督员应占专业检测人员数量的10%左右；\n\n4.2.2 监督员专业技术水平应足够：监督员应该具有丰富的检测工作经验，熟悉所监督对象有关的各检测项目的检测标准、检测工作程序、有能力评价检测结果；\n\n4.2.3 监督员的权利应足够：技术负责人授权监督员有权利对监督工作中发现的问题当场指出并责令立即改正。但不符合工作的处置发生困难时可直接报告技术负责人，可以扣发存在问题的检测报告，对纠正措施效果不满意时，可通过和有关人员沟通并提出整改建议等，\n\n4.2.4 监督员的工作岗位已经有利于监督工作的实施：监督员应工作在检测现场，以利于掌握最新动态，了解技术操作环节中的难点，及时发现过程控制中的问题并予以纠正，对连续的检测活动实施有效的质量监督。\n\n4.3 监测的控制措施\n\n4.3.1 每年初由监督员编制《年度日常监督计划表》，并由实验室主任批准，监督计划中必须对监督的项目，监督的频次做出明确的规定，通常情况下本公司监督员主要对与检测质量有重要影响的人、机、料、法、环、样品、结果报告等七个因素进行监督，监督频次一般每月对每个因素实施一次监督。\n\n4.3.2 监督员需按《人员培训程序》，对检测人员（包括在培人员）实施有效的监督和控制，监督员对检测人员的技术能力，有计划地进行监督，将监督中发现的问题填入《日常监督记录表》，上报给技术负责人。\n\n4.3.3 监督员需按《设施与环境条件控制和维护程序》，对检测人员在开展检测活动之前，是否充分考虑检测场所的设施和环境条件是否符合相关要求进行监督。\n\n4.3.4 检测员需按《检测方法的选择与确认程序》、《开展新项目评审程序》对检测人员在开展检测活动前，对是否选择适当的方法，需得到确认的方法是否已经确认，是否具备必须的作业指导书、标准、技术文件等进行监督，按具体要求执行。\n\n4.3.5 检测员需按《仪器设备管理程序》对检测人员在使用各类仪器设备时，是否应严格按规程、细则、规定及正确操作进行监督，包括对设备的正常维护和管理。\n\n物质期间核查程序》对个专业领域的记录、数据是否均应按要求溯源到国际单位制。对与检测有关的各类在用仪器设备、标准物质是否按要求校准并溯源，并在有效期内进行监督。仪器设备、标准物质的管理等具体执行。\n\n4.3.7 监督员需按《样品处置和管理程序》对样品的管理情况进行监督。\n\n4.3.8 根据要求检测工作可由两人或多人进行，检测人员应严格执行有关规范、作业指导书的要求，对检测结果负责。\n\n4.3.9 使用计算机或自动采集数据进行检测，则按《计算机软件及数据控制程序》执行。\n\n4.2.10监督员须按《结果报告管理程序》对检测报告的出具情况进行监督。\n\n4.4 对控制措施的监督\n\n4.4.1 技术负责人、质量负责人、监督员均有对控制措施执行情况的监督责任，及时发现问题，及时提出，及时解决，按《不符合检测工作管理程序》、《实施纠正措施程序》执行。\n\n4.4.2 监督员负责日常检测活动中的监督工作，除参与有组织的定期检查外，日常工作时，随时发现问题，随时做好监督记录，填写《日常监督记录表》并经部门负责人签字确认。\n\n4.4.3 监督员综合分析、评价日常监督状况，并向实验室经理报告工作，对各种监督资料、数据进行统计分析形成文件，提交管理评审。\n\n4.4.4 各种监督记录、文件、统计资料，均由资料管理员收集、整理、留存。\n',150,'现用文件/程序文件/程序文件2022/31-2022检测工作的监督程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('0c90305e-452f-4f40-b442-5bd64a2d9393','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:8_4','8.4','记录控制','section','## 8.4 记录控制\n\n8.4.1 总则\n\n8.4.1.1 记录是为完成的活动或达到的结果提供客观证据的活动过程，形成的文件也是质量活动的证明文件，记录可以表明质量要求得到满足的程序，同时也为管理体系要素运行的有效性和质量活动可追溯性提供客观证据，以实现管理体系的持续改进。本公司制定了《记录控制程序》，其中对记录的识别、收集、索引、存档、存放、维护等环节作出了明确的规定。\n\n本公司的记录分为质量记录和技术记录，质量记录包括来自内部审核和管理评审的报告及纠正和预防措施的记录。\n\n8.4.1.2 本公司所有的记录格式应规范化、信息足够，各岗位人员填写的记录应清晰明了，并有唯一性编号，便于管理，记录的保存应由资料管理员负责并保存在具有防止损害、变质、丢失等适宜的环境设施中。观察结果、数据和计算结果，必须在当时予以记录，并按特定任务分类识别。\n\n8.4.1.3 记录编制和审批：由质量负责人负责组织质量记录格式的编制和审批，技术负责人负责组织技术记录格式的编制和审批，确保记录中包含满足记录要求的足够信息。办公室负责记录的控制和内部审核、管理评审记录的保存，以及记录格式的备案和印制。\n\n8.4.1.4 记录的形式：可以纸张、电子媒介、硬盘拷贝、计算机检测管理软件等形式保存。\n\n8.4.1.5 保密要求：公司应对工作人员规定保密要求，对进入记录的存放场所进行控制，备份以电子形式存储的记录，对贮存在计算机中的记录采取设置密码等措施，防止非法侵入和修改。\n\n8.4.1.6 记录的更改：\n\n技术记录的更改，只能由原始记录人采用划改（不允许擦涂），同时在其右上方填写正确内容，对记录的所有改动应有改动人的签名或盖章；\n\n对以电子形式存储的记录，同样按上述措施要求进行更改（如加密、设置只读方式等）并及时备份，防止原始数据的丢失或改动，确保只有经授权的人员才能查阅、修改。\n\n8.4.1.7 保存期限\n\n各类记录根据其重要性规定适当的保存期限进行保存管理，记录保存期限应符合合同义务，本公司的检验检测原始记录和报告至少保存6年。如果法律法规、专业领域认可或认证要求文件或客户规定了更长的保存期要求，本公司应满足这些要求。\n\n人员或设备记录应随同人员工作期间或设备使用时限全程保留，在人员调离或设备停止使用后，人员或设备技术记录应再保存6年。\n\n技术记录，无论是电子记录还是纸面记录，应包括从样品的接收到出具检测报告过程中观察到的信息和原始数据，并全程确保样品与检测报告的对应性。\n\n8.4.1.8 支持性文件\n\n《记录控制程序》 XZTC/CX-19-2018\n',850,'现用文件/质量手册（第四版）.docx#8.4','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('0cb8071b-ce40-4cf6-9212-42d0e154ba83','00000000-0000-0000-0000-000000000001','9866c11d-bd92-49cd-a2a8-5908ea97646c','c48af7a3-80ae-40cd-8ca9-68597c00b1f4',NULL,'procedure:xztc_cx_33_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司的内务、安全管理工作的各环节、部门。\n',130,'现用文件/程序文件/程序文件2022/33-2022内务与安全管理程序.docx#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('0e111e14-3cf5-4509-8dba-0e2e1c929de1','00000000-0000-0000-0000-000000000001','f9f936aa-4e68-449e-a6bc-814098b9b434','f6b1b203-1e7a-48e5-953a-c9de0ae2969d',NULL,'procedure:xztc_cx_07_02_2022:source:scope','','范围','scope','### 范围\n\n本程序适用于本公司所有工作人员。\n',130,'现用文件/程序文件/程序文件2022/07-02-2022防止商业贿赂程序.doc#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('0f73bcbc-9fbb-4876-9007-16dfc5f1ba9d','00000000-0000-0000-0000-000000000001','f9f936aa-4e68-449e-a6bc-814098b9b434','f6b1b203-1e7a-48e5-953a-c9de0ae2969d',NULL,'procedure:xztc_cx_07_02_2022:source:purpose','','目的','purpose','### 目的\n\n为保证我公司出具的检验检测数据公正、客观，抵制任何内部和外部的可能影响到检验检测工作的商业、财务和其它方面的压力、影响、利益诱惑等，防止商业贿赂，特制定本程序。\n',120,'现用文件/程序文件/程序文件2022/07-02-2022防止商业贿赂程序.doc#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('11e84e42-745a-4c73-a40e-54a5268292d3','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_3','7.3','抽样','section','## 7.3 抽样\n\n7.3.1 总则\n\n抽样是检测工作的前道工序，正确的、科学的、合理的抽样方法可确保抽样的真实性和代表性，提高检测工作的准确性和有效性，减少检测风险。策划和控制抽样过程，保证抽样的科学性、代表性、随机性、可追溯性。在珠宝检测过程中，一般不进行抽样工作，对客户所送检的样品都要全部进行检测，若需要抽样时，实施对抽样过程必须控制的因素，对抽样计划的制定，抽样采用的统计方法，抽样实施，抽样记录和允许偏离的处置等作出明确规定。\n\n7.3.2 抽样计划和抽样方案\n\n按有关检测标准、规范或合同中对抽样的项目、地点、位置、时间、频次、方法、样本数量和判定准则的规定执行。如果专业标准或规范中没有关于抽样的具体规定，则要根据适当的统计方法制定抽样计划和抽样方案（如根据国家抽样标准），并满足客户及相关方的要求。当客户对文件规定的抽样程序有偏离、添加或删节的要求时，业务部在《检测委托合同》签订时（或抽样过程中）记录这些要求和相关的抽样资料，并记入包含检测结果的所有文件中，同时告知相关人员。\n\n7.3.3当客户对文件规定的抽样程序有偏离、添加或删节的要求时，需详细记录这些要求和相关的抽样资料，并被纳入包含检测结果的所有文件中，同时告知相关人员。\n\n7.3.4当抽样作为检测工作的一部分时，记录与抽样有关的资料和操作，这些记录需包括：所用的抽样方法、抽样日期和时间、样品名称、抽样人签字、所用设备名称和型号、抽样项目、地点、位置、环境或运输条件（如果相关）、样品数量、判定准则、样品外观描述、必要时标明抽样地点位置示意图等，还可以通过相片、录像等显示。\n\n7.3.5 本公司不从事送检产品的抽样活动，本公司在检测报告中明确声明检测结果仅对来样负责。\n\n7.3.6 支持性文件\n\n《抽样控制程序》 XZTC/CX-35-2018\n',730,'现用文件/质量手册（第四版）.docx#7.3','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('1431723b-3473-4a4a-bfe4-a71e2f140284','00000000-0000-0000-0000-000000000001','810f7acb-fe9d-4025-a66c-0891768b873b','5901e814-4bc7-4220-898e-422827d22b6d',NULL,'procedure:xztc_cx_11_2022:source:records','','记录','record_requirement','### 记录\n\n《供应商评价表》 XZTC/BG-11-01\n\n《合格供应商名册》 XZTC/BG-11-02\n\n《采购计划验收表》 XZTC/BG-11-03\n\n《仪器设备购置申报表》 XZTC/BG-11-04\n\n《购入仪器设备验收记录》 XZTC/BG-11-05\n',170,'现用文件/程序文件/程序文件2022/11-2022外部支持服务和供应品管理程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('14b3ce3b-c1d6-419f-be24-7e505ccea975','00000000-0000-0000-0000-000000000001','76ffd146-ed11-4da9-a42a-c1ef8787db95','a64ffdaa-5ea0-412e-b076-f9c0c9283c85',NULL,'procedure:xztc_cx_29_2022:source:records','','记录','record_requirement','### 记录\n\n《报告更改申请表》 XZTC/BG-29-01\n\n《报告抽查情况记录表》 XZTC/BG-29-02\n\n《报告发放登记表》 XZTC/BG-29-03\n',170,'现用文件/程序文件/程序文件2022/29-2022结果报告管理程序.docx#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('1767627f-a045-4280-b6d2-c45ff41eda2d','00000000-0000-0000-0000-000000000001','69032715-7174-46fa-b564-18c838e80d23','1b4fd63c-d774-4713-8a57-1bcc9ea019f3',NULL,'procedure:xztc_cx_30_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《不符合检测工作管理程序》 XZTC/CX-15-2022\n\n《实施纠正措施程序》 XZTC/CX-16-2022\n\n《实施预防措施程序》 XZTC/CX-17-2022\n',160,'现用文件/程序文件/程序文件2022/30-2022检测结果质量控制及能力验证程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('1770a9d3-75ec-4d6f-86ee-80e09be1a95c','00000000-0000-0000-0000-000000000001','0298e975-ff58-4c04-b700-8e0cf4cd55d0','9f92ea6a-b554-401a-b1b5-c76269f78919',NULL,'procedure:xztc_cx_34_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 监控管理制度\n\n4.1.1 为确保监控设备的安全, 由办公室负责对监控设备, 软件系统进行维护和管理，填写《监控维护管理记录表》。\n\n4.1.2 应认真履行各项监控室管理职责, 每月月初按照规定对监控设备进行检查和维护,及时发现，及时报告,解决硬件系统出现的故障,保障系统的正常运行。\n\n4.1.3 应及时查看监控设备是否正常运行, 确保监控数据完整无误，不得无故中断监控。\n\n4.1.4 严格遵守\n\n,,未经允许,不得私自拷贝,下载和外借；严禁任何人在监控计算机上使用未经检测允许的介质(软盘,光盘等) , 严禁在监控计算机上做与监控无关的事情。\n\n4.1.5 实验室主任要经常督促检查本制度执行情况,做好情况记录,切实履行管\n\n理职责, 发现异常情况必须及时汇报。保证监控设备安全有序，不得无故中断监控，删除监控资料。\n\n4.2 图像信息保存、使用登记制度\n\n4.2.1 日常监控实行24小时制，监控系统图像实行自动保存，图像保存时间不少于30天。每周对监控系统图像进行查看，及时发现问题。\n\n4.2.2 外来人员需要查看监控图像需实验室主任批准，填写《监控信息图像查看记录表》,对调取时间、调取用途等事项进行登记，由检测室主任陪同查询。内部人员查看监控图像，填写《监控信息图像查看记录表》,对调取时间、调取用途等事项进行登记，由实验室主任批准，检测室主任陪同查询。\n\n4.3 安全\n\n4.3.1 监控计算机要设置密码，严禁将计算机密码告知无关人员。\n\n4.3.2 未经相关领导批准，任何人员不得将公司的监控数据、软件及资料复制给其他单位或个人。\n\n4.3.3 未经许可，任何人员不得使用操作监控计算机系统及相关设备。\n\n4.3.4 对涉及公司秘密、\n\n的监控图像信息予以保密。\n\n4.3.5 任何人不得擅自复制、查询或者向公安机关以外的其他单位和个人提供、传播监控图像信息。\n\n4.3.6 任何人不得擅自删除、修改监控系统的运行程序和记录。\n\n4.3.7 任何人不得擅自改变\n\n图像信息系统的用途和摄像设备的位置。\n\n4.3.8 任何人不得干扰、妨碍监控系统的正常运行。\n\n4.4 监控区域要求\n\n4.4.1 已经覆盖监控的区域作相关标识。\n\n4.4.2 重点受控区与为检测区与收样区\n\n4.4.2.1 收样区：两个或两个以上摄像头，进行多角度监控，需清晰拍摄到送样人的面部特征及所送样品的内容及数量。样品员的收样过程要在摄像头下完成，避免造成不必要的纠纷。\n\n4.4.2.2 检测区：检测室监控应具备两个或两个以上监控摄像头，进行多角度监控，以保障可以完整的拍摄检测人员的工作状况，当样品出现丢失时查看监控，能够及时找回样品。\n',150,'现用文件/程序文件/程序文件2022/34-2022内部监控管理程序.doc#工作程序','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('17e01e7b-57cb-4bfe-85e4-d49f26efee6b','00000000-0000-0000-0000-000000000001','575be231-b422-4860-84b2-bcd28c6a6d7f','296ce497-e0aa-4f43-a7f0-0b59a7e6e6f8',NULL,'procedure:xztc_cx_15_2022:source:records','','记录','record_requirement','### 记录\n\n《不符合项处置通知表》 XZTC/BG-15-01\n\n《实施纠正措施记录表》 XZTC/BG-16-01\n\n《实施预防措施记录表》 XZTC/BG-17-01\n',170,'现用文件/程序文件/程序文件2022/15-2022不符合检测工作管理程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('17efcc0f-80ed-475b-91af-bf70801b6f4a','00000000-0000-0000-0000-000000000001','9f720d1f-600b-423a-8082-f8987b0594cf','3a8d9ea2-2b78-4dc0-a1e8-164f02246028',NULL,'procedure:xztc_cx_06_2022:source:purpose','','目的','purpose','### 目的\n\n为了保护客户机密信息和所有权不被泄露，维护本公司的公正性地位和良好信誉，特制定本程序。\n',120,'现用文件/程序文件/程序文件2022/06-2022保护客户机密信息程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('18bed4b4-1396-41cf-a58a-93e38186dfca','00000000-0000-0000-0000-000000000001','1e1e9194-f520-4a67-91ab-d313500615c8','e12e3730-cc7a-4ade-8704-2460e6762097',NULL,'procedure:xztc_cx_02_2022:source:records','','记录','record_requirement','### 记录\n\n《检测环境监控记录表》 XZTC/BG-02-01\n',170,'现用文件/程序文件/程序文件2022/02-2022设施与环境条件控制和维护程序.docx#记录','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('19e257cc-4ed2-4773-949d-99eac0b6384b','00000000-0000-0000-0000-000000000001','b3f4c46e-f363-44f3-86f5-4d207df828ef','a3a3bc75-4867-43ee-af53-ba1e1745ecbe',NULL,'procedure:xztc_cx_26_2022:source:records','','记录','record_requirement','### 记录\n\n《计算机软件登记表》 XZTC/BG-26-01\n\n《计算机内容变更申请表》 XZTC/BG-26-02\n',170,'现用文件/程序文件/程序文件2022/26-2022计算机文件及数据控制程序.docx#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('1a13cf09-975d-478a-b85e-b66463208da5','00000000-0000-0000-0000-000000000001','cda70d11-6fd2-45dc-88ec-6b6b88267f6a','8fd66b6b-cf04-4f03-b795-e5e7a61f9695',NULL,'procedure:xztc_cx_25_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《客户要求、标书、合同评审程序》 XZTC/CX-09-2022\n\n《记录控制程序》 XZTC/CX-19-2022\n\n《设施与环境条件控制和维护程序》 XZTC/CX-02-2022\n\n《允许方法偏离控制程序》 XZTC/CX-23-2022\n\n《样品处置和管理程序》 XZTC/CX-28-2022\n\n《检测结果质量控制及能力验证程序》 XZTC/CX-30-2022\n',160,'现用文件/程序文件/程序文件2022/25-2022检测工作控制程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('1cfaa31d-8ff5-440f-a06e-a5f898dfcd6b','00000000-0000-0000-0000-000000000001','bd275009-ec1d-4a48-b6fc-39304fe0dee9','f488cefe-287f-47a2-b075-c5cd1cbcfa0b',NULL,'procedure:xztc_cx_17_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 持续改进\n\n4.1.1 本公司通过质量方针和目标的落实贯彻、内外部审核结果、客户投诉、信息反馈、数据分析、纠正和预防措施的实施及管理评审的结果，寻找体系持续改进的机会，持续改进管理体系的有效性。\n\n4.2 预防措施\n\n4.2.1 潜在不符合的识别\n\n4.2.1.1 潜在不符合的信息来源包括：市场调查、行业信息、政府文件、媒体报告、内审、外审、管理评审、质量趋势及客户和社会的要求和期望、实验室间比对或能力验证结果等方面各部门、岗位人员应就质量管理和技术运作各环节与相关的管理工作，收集、报告潜在不符合的有关信息。如检测部负责检测过程潜在的不符合的收集和报告，办公室负责客户反\n\n馈信息的收集和报告等。\n\n4.2.2 潜在不符合的原因分析、预防措施计划的制定\n\n4.2.2.1 责任部门、责任岗位或有关人员对已识别的潜在不符合进行原因分析，如人力资源、仪器设备、客户要求、方法和程序及数据分析，确定潜在不符合的原因和改进的机会（见《实施预防措施记录表》）。\n\n4.2.2.2 制定目的在于消除潜在不符合原因，防止不符合发生的预防措施计划。\n\n4.2.2.3 预防措施计划需经质量/技术负责人评价和批准，以确保其适宜有效性。质量负责人负责质量管理方面预防措施的评价、批准，技术负责人负责技术运作方面预防措施的评价、批准。\n\n4.2.3 预防措施计划的实施\n\n4.2.3.1 相应责任岗位人员负责落实确定的预防措施的实施。\n\n4.2.3.2 监督员进行预防措施实施的跟踪验证，并评价其有效性。若未达到要求，应重新分析原因，制定预防措施。\n\n4.3 预防措施若引起文件的更改，按《文件控制程序》执行。\n\n4.4 资料管理员保存预防措施的原因分析、制定、实施和验证的有关记录，并负责提交管理评审。\n',150,'现用文件/程序文件/程序文件2022/17-2022实施预防措施程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('1dc55d30-1414-4ef6-b348-96c809c6e763','00000000-0000-0000-0000-000000000001','44ff5408-e03d-4859-9cd4-926a8f69fda5','948d2434-2b53-47e6-adab-cf2ee95dfc3c',NULL,'procedure:xztc_cx_09_2022:source:purpose','','目的','purpose','### 目的\n\n为使合同的签定与评审活动得到控制，保证全面及时地完成合同规定的任务，增强公司的信誉，降低自身风险，特制定本程序。\n',120,'现用文件/程序文件/程序文件2022/09-2022客户要求、标书、合同评审程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('1eeb877c-a1a8-444a-946b-850cf445ada1','00000000-0000-0000-0000-000000000001','9866c11d-bd92-49cd-a2a8-5908ea97646c','c48af7a3-80ae-40cd-8ca9-68597c00b1f4',NULL,'procedure:xztc_cx_33_2022:source:records','','记录','record_requirement','### 记录\n\n《安全检查记录表》 XZTC/BG-33-01\n',170,'现用文件/程序文件/程序文件2022/33-2022内务与安全管理程序.docx#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('1f12a48d-6cdc-48b1-8c90-82df0051c04c','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:6_1','6.1','总则','section','## 6.1 总则\n\n本公司应获得管理和实施实验室活动所需的人员、设施、设备、系统及支持服务。\n',610,'现用文件/质量手册（第四版）.docx#6.1','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('211b012e-d45a-414d-a6cb-9ebb03293b39','00000000-0000-0000-0000-000000000001','3f002465-cdef-4e44-a37c-7aeaf5bd508d','f77b4435-116f-4c21-b9c3-c82afea7732d',NULL,'procedure:xztc_cx_08_2022:source:records','','记录','record_requirement','### 记录\n\n《内部受控文件登记表》 XZTC/BG-08-01\n\n《外来文件资料登记表》 XZTC/BG-08-02\n\n《文件发放回收登记表》 XZTC/BG-08-03\n\n《文件借阅登记表》 XZTC/BG-08-04\n\n《体系文件置换申请表》 XZTC/BG-08-05\n\n《体系文件更改审批表》 XZTC/BG-08-06\n\n《文件销毁记录表》 XZTC/BG-08-07\n\n《会议签到记录表》 XZTC/BG-08-08\n\n《检测原始记录表》 XZTC/BG-08-09\n\n附录1\n\n管理体系文件编号及标识规定\n\n1.管理体系文件编号规定\n\n1.1 质量手册编号规定\n\nXZTC/SC-□□□□\n\n| | | 颁布年号\n\n| | 质量手册\n\n| 新疆中和鉴珠宝玉石质量检测研究所（有限公司）（下同）\n\n1.2 程序文件编号规定\n\nXZTC/CX--□□--□□□□\n\n| | | 颁布年号\n\n| | 顺序号\n\n| 程序文件\n\n1.3 作业指导书编号规定\n\nXZTC/ZY--□--□□--□□□□\n\n| | | | 颁布年号\n\n| | | 顺序号\n\n| | 类别号\n\n| 作业指导书\n\n作业指导书类别代号：\n\n1-管理类作业指导书\n\n2-设备操作类作业指导书\n\n3-期间核查方法\n\n4-方法类作业指导书\n\n5-样品类作业指导书\n\n6-数值修约类作业指导书\n\n7-仪器设备自校规程\n\n1.4.1乌鲁木齐实验室记录表格编号规定\n\nXZTC/BG--□□--□□\n\n| | | 顺序号\n\n| | 程序文件顺序号\n\n| 记录表格\n\n1.4.2和田实验室记录表格编号规定\n\nXZTCH/BG--□□--□□\n\n| | | 顺序号\n\n| | 程序文件顺序号\n\n| 记录表格\n\n2. 管理体系文件标识规定\n\n2.1 本公司内部管理体系文件，在发放前应在文件封面盖“受控”标识章，并标注日期以及本公司的名称。\n\n受控章形式如下：\n\n受控2022-01-01新疆中和鉴珠宝玉石质量检测研究所（有限公司）\n\n2022-01-01\n\n2.2 外来文件经实验室主任识别确认后，须分发时，在封面盖“受控文件”并编发放编号。“非受控”文件不进行标识。\n\n2.3 文件识别应有唯一性标识，包括文件编码、发布日期、实施日期、页码、总页数、发布部门、受控状态等。\n\n3. 管理体系文件版本状态标识\n\n3.1 质量手册首次制订 版本：第一版，版次：01，当修订次数超过第10次时，版本升级为第二版本，版次01，依此类推；\n\n3.2 程序文件首次制订 版本：第一版，版次：01，当修订次数超过第10次时，版本升级为第二版本，版次01，依此类推；\n\n3.3 作业指导书首次制订 版本：第一版，版次：01，当修订次数超过第10次时，版本升级为第二版本，版次01，依此类推；\n\n3.4 记录格式首次制订为1/0版，第1次修订后为1/1版，此类推。\n\n外来文件不作版本状态标识，当有新版本文件发行时，旧版本文件按文件要求作废。\n',170,'现用文件/程序文件/程序文件2022/08-2022文件控制程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('21e0b178-6d67-4611-a0de-8f87b97332cd','00000000-0000-0000-0000-000000000001','0298e975-ff58-4c04-b700-8e0cf4cd55d0','9f92ea6a-b554-401a-b1b5-c76269f78919',NULL,'procedure:xztc_cx_34_2022:source:records','','记录','record_requirement','### 记录\n\n《监控维护管理记录表》 XZTC/BG-34-01\n\n《监控信息图像查看记录表》 XZTC/BG-34-02\n\n一 刀 戀 搀\n\n搌 樀 瀀 爀 蠀 言 阀 騀\n\n倀\n\n刀\n\n氀\n\n渀\n\n縀\n\n言\n\n頀\n\n騀\n\n鰀\n\n、。〃々〉》」』】〕〗！＂＇），．：；？］｀｜｝～￠\n\n〈《「『【〔〖（．［｛￡￥\n\n堓ﾔ肕堓ﾔ肕堓ﾔ肕堓ﾔ肕堓ﾔ肕￿\n',170,'现用文件/程序文件/程序文件2022/34-2022内部监控管理程序.doc#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('236a77b3-f84b-44ec-9b49-bad87aba9015','00000000-0000-0000-0000-000000000001','9f907214-fdff-400d-bd65-a376c631c875','619a08d7-264c-4a61-82aa-35e13cfa6e5d',NULL,'procedure:xztc_cx_07_2022:source:scope','','范围','scope','### 范围\n\n本公司检验能力的维护和行为规范的贯彻、执行与监督。\n',130,'现用文件/程序文件/程序文件2022/07-2022确保公正性程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('23cf0a2a-a2f9-4550-a49d-d0fc4455fa1d','00000000-0000-0000-0000-000000000001','18dcefaa-d28e-4886-a193-3ff3c9d06183',NULL,NULL,'external_basis:gb_t_27025_2019:overview','','检测和校准实验室能力的通用要求','section','# GB/T 27025-2019 检测和校准实验室能力的通用要求\n\n- 来源类型：external_standard\n- 版本：2019\n- 实施日期：2020-07-01\n- 查新状态：due\n- 查新日期：2026-07-19\n- 查新结论：本地正式依据文件缺失\n- 查新证据：参考/2025年最新版CMA和CNAS质量体系/05-GBT 27025-2019 检测和校准实验室能力的通用要求.pdf\n- 下次查新：2027-07-19\n- 归档文件：参考/2025年最新版CMA和CNAS质量体系/05-GBT 27025-2019 检测和校准实验室能力的通用要求.pdf\n- 正式条款数：0\n',100,'参考/2025年最新版CMA和CNAS质量体系/05-GBT 27025-2019 检测和校准实验室能力的通用要求.pdf','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('2434e1d8-0af4-4ecf-af57-297e9869d8ca','00000000-0000-0000-0000-000000000001','544b293a-5553-4bfe-baef-80b1c8d9e410','a343bfe0-5a01-4e73-8d80-9e2fe7ca3f22',NULL,'procedure:xztc_cx_24_2022:source:records','','记录','record_requirement','### 记录\n\n《开展新项目申请表》 XZTC/BG-24-01\n\n《开展新项目评审表》 XZTC/BG-24-02\n',170,'现用文件/程序文件/程序文件2022/24-2022开展新项目评审程序.docx#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('2572e9dc-3d9b-4f45-8ac8-724a98e5b521','00000000-0000-0000-0000-000000000001','9866c11d-bd92-49cd-a2a8-5908ea97646c','c48af7a3-80ae-40cd-8ca9-68597c00b1f4',NULL,'procedure:xztc_cx_33_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 办公室主任应：\n\n3.1.1 组织制订各项管理措施，负责本公司内务、安全管理工作。\n\n3.2 检测部应：\n\n3.2.1 负责检测室的内务、安全工作的管理，落实各项管理要求。\n',140,'现用文件/程序文件/程序文件2022/33-2022内务与安全管理程序.docx#职责','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('26913ab6-057c-4b9c-a243-23f221d835d3','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:4_2','4.2','保密性','section','## 4.2 保密性\n\n4.2.1 保护客户机密信息和所有权，包括保护电子存储和传输结果，这是本公司一贯执行的原则，并一直坚持贯彻始终。为防止出现意外的失密或失误，特制定《保护客户机密信息程序》进行控制。本公司建立了监督机制，以保证客户的要求得到满足，客户的利益不受损失。\n\n4.2.2 本公司对在实验室活动中获得或产生的信息承担管理责任。本公司应将准备公开的信息事先通知客户。除客户公开的信息，或本公司与客户有约定（例如：为回应投诉的目的），其他所有信息都被视为专属信息，应予保密。\n\n4.2.3 本公司依据法律要求或合同授权透露保密信息时，除法律禁止外，所提供的信息应通知相关客户或个人。\n\n4.2.4 从客户以外渠道（如投诉人、监管机构）获取有关客户的信息，应在客户和实验室间保密。除非信息的提供方同意，本公司应对信息提供方（来源）保密，且不应告知客户。\n\n4.2.5 人员，包括合同方、外部机构人员或代表公司的个人，应对在实施实验室活动过程中所获得或产生的所有信息保密，法律要求除外。\n\n4.2.6 记录应有适宜的贮存场所，防止丢失，公司应对工作人员规定保密要求，对进入记录的存放场所进行控制，备份以电子形式存储的记录，对贮存在计算机中的记录采取设置密码等措施，防止非法侵入和修改。\n\n4.3 公正性及保密性声明\n\n4.3.1 公正性声明\n\n新疆中和鉴珠宝玉石质量检测研究所（有限公司）是从事珠宝玉石及贵金属检测的机构。为了保护国家、客户及供应商的利益，本公司就检测工作的公正性做以下声明：\n\n1.本公司是具有检验检测资质的独立法人单位，在规定的范围内开展检验检测业务，检验检测工作不受任何行政机构和外来因素的干预，保证检验检测行为的公正性。\n\n2.本公司对所有客户都提供高质量的服务，不歧视任何有关方面，不谋取任何不正当的经济利益。\n\n3.本公司不监制、监销产品，未经客户同意不对新闻媒体公布检测结果。\n\n4.本公司严格遵守国家有关法律法规，依据现行有效的检验检测标准，选用先进的检验检测设备，保证检验检测方法的科学性。\n',420,'现用文件/质量手册（第四版）.docx#4.2','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('286be633-f481-484b-b303-5215ed832446','00000000-0000-0000-0000-000000000001','4573b997-12b2-4cd2-8689-6590c02ae7b7','f381721c-0f02-476f-b688-9bb0ebefb96e',NULL,'procedure:xztc_cx_27_2022:element:measurement_uncertainty','','要素落实：测量不确定度评定','control_requirement','### 要素落实：测量不确定度评定\n\n- 程序文件：XZTC/CX-27-2022 测量不确定度的评审控制程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('29775163-a8cf-409f-b03e-25001cb8e241','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:6_4','6.4','设备','section','## 6.4 设备\n\n6.4.1 本公司对使用的仪器设备（包括软件）实施控制管理，规范设备的配置、使用至报废的各环节管理，为此制定了对设备购置、验收、运输、存放、使用和有效维护计划的《仪器设备管理程序》，以确保所用设备的正常运转和检测结果的准确性和可靠性。\n\n6.4.2 仪器设备的配置\n\n6.4.2.1 根据检测的范围、项目所需的方法、工作量的需求及技术指标的要求，正确配置所需的仪器设备（包括量程范围、准确度、不确定度等的选择），以满足资源的要求。\n\n6.4.2.2 设备更新及购置，必要时应组织有关人员论证、设备的购置及组织验收，具体工作按《外部支持服务和供应品管理程序》和《仪器设备管理程序》规定实施。\n\n6.4.2.3 设备租赁：在特殊条件下，可向其他公司或科研机构租、借设备使用，确保其过程能力符合规定要求。\n\n6.4.3 仪器设备的标识\n\n6.4.3.1 设备唯一性标识：设备管理员负责建立仪器设备台账，统一编号、标识，设备的编号应具有唯一性，便于追溯和识别管理状态。\n\n6.4.3.2 设备状态标识：经检定/校准的仪器以三色标形式标明仪器设备的编号、检定/校准日期及有效期等，仪器设备的校准状态标识分别为“合格”“准用”“停用”三种，通常以“绿”“黄”“红”三种颜色表示。\n\n仪器设备的状态标识内容包括：\n\n仪器设备名称；\n\n仪器设备编号（自编号）；\n\n仪器设备状态（以绿、黄、红三色区分不同状态，详见《设备管理程序》）；\n\n检定或校准/核查日期；\n\n检定或校准/核查有效期；\n\n检定或校准/核查单位。\n\n6.4.4 仪器设备的使用管理\n\n6.4.4.1 对所有影响检测结果的仪器设备应按周期检定/校准，计划组织实施（包括新购入的仪器设备），确认符合要求后，方可投入使用。对经检定/校准所得的修正因子，应确保及时更新备份（详见《实现测量可溯源程序》）。禁止对仪器设备的随意调整（包括硬件和软件的保护）致使检测结果失效。\n\n6.4.4.2 对仪器设备使用的人员应经过培训，设备操作能力得到确认。对检测设备实施维护和操作应使用最新版本的作业指导书（包括说明书和使用手册等），并方便操作及相关人员使用。\n\n6.4.4.3 操作者在使用设备前，应对设备进行运行状态检查，以证实其能够满足规定标准要求。\n\n6.4.4.4 操作过程中发生过载或处置不当、出现可疑结果，或已显示出缺陷、超出规定限度时，应立即停止使用，及时标识、处置，防止误用。同时检查分析这些缺陷或偏离对以前检测质量的影响，执行《不符合检测工作的控制管理程序》，落实有关措施，经修复后的仪器设备须进行校准确认状态正常时，方可投入使用。\n\n6.4.4.5 按《期间核查管理程序》规定要求，对不太稳定、使用频率高、漂移性较大、能力验证结果有问题、对检测数据有疑问、单纯校准不能保证在有效期内正确可靠的设备进行期间核查，以保持设备给出结果的可信度。\n\n6.4.4.6 对脱离本公司直接控制租借出去的仪器设备实施控制管理，设备返还后，由有关人员对设备核查验收，以满足再次投入使用需求。\n\n6.4.5 仪器设备的维修\n\n6.4.5.1 设备的维修应由专业人员进行，维修后组织验收记录。\n\n6.4.5.2 设备的降级使用需经确认批准后方可使用。\n\n6.4.5.3 设备的报废由实验室主任批准。\n\n6.4.6 记录和档案\n\n仪器设备及其软件的各种记录、资料统一归档管理，并建立主要仪器设备的档案，详见《仪器设备管理程序》。较为重要或复杂的仪器设备和标准物质均建有档案，档案内容一般包括：\n\n设备名称、编号、型号、序号或唯一性标识；\n\n制造商提供的信息；\n\n接收、启用日期和验收记录；\n\n存放地点、保管人；\n\n说明书（如果有）；\n\n检定或校准证书、核查记录；\n\n维护计划和维护记录；\n\n损坏、故障、改装、维修记录。\n\n6.4.7 仪器设备的停用和报废\n\n6.4.7.1 当出现下列情况时应停止使用仪器设备：\n\n仪器设备出现故障或缺陷时；\n\n仪器设备过载或错误操作；\n\n显示结果可疑，仪器设备的停用必须按规定的程序进行，即停用—标识—隔离—修复（损坏时） —再检定或校准、核查—必要时消除影响（详见《仪器设备管理程序》）。\n\n6.4.7.2 当仪器设备不再适合使用时应报废处理，由实验室提出报废申请，经技术负责人审查技术内容，再经实验室主任批准，由办公室处置。\n\n6.4.8 仪器设备的借用\n\n本公司人员借用仪器设备须办理借用手续。外单位借用仪器设备必须经实验室主任批准，在归还时要检查其功能及校准状态是否正常。\n',640,'现用文件/质量手册（第四版）.docx#6.4','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('29f29e98-b1a1-40cc-a5f2-eae2df856df5','00000000-0000-0000-0000-000000000001','9a4a4b45-61c0-4fad-a8ff-ef554366ea0f','647474cd-a228-43a8-ade5-a9a43a4ebe48',NULL,'procedure:xztc_cx_14_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 质量负责人应：\n\n3.1.1 负责组织对投诉有调查，主持客户投诉处理工作，批准处置措施；\n\n3.2 办公室应：\n\n3.2.1 负责收集、汇总客户及其代表和其他外部的信息；\n\n3.2.2 负责与客户投诉的协调工作；\n\n3.3 其他部门应：\n\n3.3.1 负责协助办公室收集客户信息和其他外部信息，按本程序实施。\n',140,'现用文件/程序文件/程序文件2022/14-2022处理投诉程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('2aba6041-9a7a-41bb-9d43-45727c2901b4','00000000-0000-0000-0000-000000000001','9f907214-fdff-400d-bd65-a376c631c875','619a08d7-264c-4a61-82aa-35e13cfa6e5d',NULL,'procedure:xztc_cx_07_2022:element:impartiality','','要素落实：公正性','control_requirement','### 要素落实：公正性\n\n- 程序文件：XZTC/CX-07-2022 确保公正性程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('2ac91099-9edd-4f74-a27c-d10a8a2c99f9','00000000-0000-0000-0000-000000000001','76ffd146-ed11-4da9-a42a-c1ef8787db95','a64ffdaa-5ea0-412e-b076-f9c0c9283c85',NULL,'procedure:xztc_cx_29_2022:element:results_reporting','','要素落实：结果报告','control_requirement','### 要素落实：结果报告\n\n- 程序文件：XZTC/CX-29-2022 结果报告管理程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('2b9dab53-efe1-43ce-90a7-86fbb877938b','00000000-0000-0000-0000-000000000001','f0487552-998f-4890-94df-49779d41b185','48e77eb2-f569-435f-b92e-7a4a99351f71',NULL,'procedure:xztc_cx_20_2022:element:internal_audit','','要素落实：内部审核','control_requirement','### 要素落实：内部审核\n\n- 程序文件：XZTC/CX-20-2022 内部管理体系审核程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('2c594f89-57a9-449a-bd60-ae5c9ece3e20','00000000-0000-0000-0000-000000000001','9866c11d-bd92-49cd-a2a8-5908ea97646c','c48af7a3-80ae-40cd-8ca9-68597c00b1f4',NULL,'procedure:xztc_cx_33_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 内务卫生管理\n\n4.1.1 各部门应按要求保持本部门工作场所的环境卫生，落实责任，每周进行一次全面的打扫和清洁工作。\n\n4.1.2 检测人员在当日工作结束后，应及时清洁仪器设备和周边环境，整理检测用仪器设备、工具，按指定位置摆放，非检测用品一律不能堆放在受控区域内。\n\n4.1.3 对环境有特殊要求的场所，应严格按规定进行环境控制，操作者严格按规定操作。\n\n4.1.4 检测现场应整洁卫生、仪器工具存放整齐有序，标识清楚准确。\n\n4.1.5 不允许在公司进食、吸烟，不许在公司存放食品和饮品，不许在公司随地吐痰和乱扔纸屑等杂物。\n\n4.2 安全管理\n\n4.2.1 本公司人员要树立安全第一的思想，任何检测都要有安全防护措施，重大设备要有安全操作规程。\n\n4.2.2 公司应通风良好，安装必要的通风设备，有利于有毒、有害气体及时、有效排放。\n\n4.2.3水、电、气及防火、防盗等设施应定期检查维护，及时更新、更换，保证安全、可靠、有效。\n\n4.2.4 注意人身及设备的安全，做检测时要依据工作的特点配备相应的安全措施。\n\n4.2.5 检测前要进行全面的安全检查，运行中的仪器设备现场不能无人监守。每天下班时，应关好门窗，切断电源，关闭水、气等。各室检查门、窗、水、电、气等无误后方可离开，不得疏忽大意。定期检查安全工作，防患于未然。\n\n4.2.6 公司的消防器材应妥善保管，定期更换，不得随意挪用，并且要会熟悉使用。\n\n4.2.7 发生意外事故时，应迅速切断电源、火源，并立即采取有效而妥善的措施及时处理，并及时上报公司领导。\n\n4.3 本公司人员不得将各房间钥匙转借他人或随意复制。\n\n4.4 责任人发现存在事故隐患应及时采取紧急措施，同时报告实验室主任，以便及时采取措施防止和消除隐患。\n\n4.5 在进行新项目的开发和确认时，应该考虑安全问题，以便保证将来使用时不会产生安全隐患。\n\n4.6 检查与考核\n\n4.6.1 各部门负责人负责日常的检查。\n\n4.6.2 办公室每季度组织一次考核工作，并向全室通报检查考核结果。\n',150,'现用文件/程序文件/程序文件2022/33-2022内务与安全管理程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('2df88c80-f8e5-4999-898c-38804d803972','00000000-0000-0000-0000-000000000001','d1d75375-586e-4570-a58b-afb6e06daac5','82cfd29e-aa37-423c-af0a-375007e365f7',NULL,'procedure:xztc_cx_32_2022:source:purpose','','目的','purpose','### 目的\n\n为了能够在检测工作中持续进行风险识别风险评估和实施必要的控制措施。\n',120,'现用文件/程序文件/程序文件2022/32-2022风险评估控制程序.docx#目的','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('2e6edc6d-65a0-433d-9c8a-612473092608','00000000-0000-0000-0000-000000000001','c6a9947a-3e7f-4a66-b3d2-383348f9be03','534421f2-4307-4f6c-9df2-108bd6be4607',NULL,'procedure:xztc_cx_21_2022:overview','','管理评审程序','section','# XZTC/CX-21-2022 管理评审程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/21-2022管理评审程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/21-2022管理评审程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('2eabf410-b411-4eb4-8c64-285153c79cb6','00000000-0000-0000-0000-000000000001','afb48a72-ca24-408e-86d1-685bc252a4a9','f5bfe2a1-1db8-49ca-8b36-6c8c9378a7fc',NULL,'procedure:xztc_cx_23_2022:source:records','','记录','record_requirement','### 记录\n\n《允许方法偏离申报审批表》 XZTC/BG-23-01\n',170,'现用文件/程序文件/程序文件2022/23-2022允许方法偏离控制程序.docx#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('2efded62-d3a1-4b61-b844-986f45d00618','00000000-0000-0000-0000-000000000001','9f720d1f-600b-423a-8082-f8987b0594cf','3a8d9ea2-2b78-4dc0-a1e8-164f02246028',NULL,'procedure:xztc_cx_06_2022:overview','','保护客户机密信息程序','section','# XZTC/CX-06-2022 保护客户机密信息程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/06-2022保护客户机密信息程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/06-2022保护客户机密信息程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('2f0aa37b-d3fc-4783-91a1-02e516dcc395','00000000-0000-0000-0000-000000000001','c6a9947a-3e7f-4a66-b3d2-383348f9be03','534421f2-4307-4f6c-9df2-108bd6be4607',NULL,'procedure:xztc_cx_21_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 评审时机选择\n\n4.1.1 本公司管理评审活动实施周期间隔不超过12个月，一般情况下，每年至少一次，安排在内部审核之后进行。\n\n4.1.2 特殊情况下，如：组织机构发生重大变化、发生重大质量事故等，实验室主任可决定增加管理评审的频次。\n\n4.2 管理评审的输入\n\n管理评审涉及管理体系和检测活动改进的主要方面：\n\n4.2.1 方针、目标和管理体系文件的适用性、及方针目标的实现情况。\n\n4.2.2 内外部审核结果。\n\n4.2.3 客户的反馈，包括客户的期望、满意程度和需求及服务质量分析。\n\n4.2.4 比对验证结果，包括实验室间比对、能力验证和所有验证的结果分析。\n\n4.2.5 检测报告质量分析、检测结果质量保证中所有方法效果分析。\n\n4.2.6 投诉的接收和处置情况分析。\n\n4.2.7 预防和纠正措施实施及效果分析。\n\n4.2.8 以前评审采取措施的实施及有效性。\n\n4.2.9 内外环境和客户需求的变化、法规标准方法的变化、新技术和新设备的应用和发展。\n\n4.2.10 工作量和业务范围的变化。\n\n4.2.11 人员素质及培训情况。\n\n4.2.12 供应商控制情况。\n\n4.2.13 对改进的建议、发展规划的要求。\n\n4.2.14 对日常管理会议中有关议题的研究。\n\n4.3 评审计划\n\n4.3.1 质量负责人根据实验室主任指示，负责制定《管理评审计划表》并经实验室主任批准，明确评审时间、评审内容、参加人员和评审的具体输入要求。\n\n4.3.2 质量负责人负责在评审前两周将《管理评审计划表》分发到相关部门和岗位，并协调组织各相关部门、岗位提供评审所需的输入资料。\n\n4.4 评审的实施\n\n4.4.1 由实验室主任主持评审工作，确定主题报告人，报告人应简明地说明主要观点、结论及建议。\n\n4.4.2 各责任人员根据评审输入的背景材料、主题报告和本岗位的实际工作情况，对管理体系和检测活动现状进行评价。\n\n4.4.3 由实验室主任针对主要存在问题提出结论性意见，并做总结性发言。\n\n4.4.4 评审时间一般为一个工作日。\n\n4.6 评审的输出\n\n4.6.1管理评审的输出应包括：\n\na) 管理体系及其过程的有效性；\n\nb) 履行本准则要求相关的实验室活动的改进；\n\nc) 提供所需的资源；\n\nd) 所需的变更。\n\n4.6.2根据评审意见，由质量负责人编制《管理评审报告》经公司总经理批准，《管理评审报告》应对管理体系予以分析评价，应明确对管理体系和检测服务活动的有关改进措施具体实施要求。\n\n4.7 改进措施实施和监督\n\n4.7.1 质量负责人负责组织各相关部门、岗位落实管理评审提出的质量改进措施，由责任部门、岗位编制《管理评审验证记录表》，按《实施纠正措施程序》规定执行。\n\n4.7.2 质量负责人负责协调解决落实改进措施中的问题，确保各项改进措施在规定的时间内实施，负责改进措施实施的监督和跟踪验证。并向实验室主任报告。\n\n4.8文件和记录\n\n4.8.1 管理评审计划、输入资料、报告、验证记录等文件和记录由质量负责人整理保存。\n',150,'现用文件/程序文件/程序文件2022/21-2022管理评审程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('2f847174-0e75-4523-84f7-8bd15636f3da','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_5','7.5','技术记录','section','## 7.5 技术记录\n\n7.5.1 技术记录包括原始观察记录、导出数据、开展跟踪审核的足够信息、检测报告等，均按保存期限规定保存。\n\n7.5.2 记录中应包含足够的信息：合同评审与客户要求、样品识别和接收条件、样品的接收和测试日期、所用方法和任何偏离、所用仪器、环境条件、原始数据和全部计算记录、质量控制结果和相关核查等，这些信息应足以识别对不确定度的影响因素。记录应保证检测接近原始情况下可以做到复现。\n\n7.5.3 技术记录中应能清楚地识别检测人员以及校核人员的签字或标识。\n\n7.5.4 在检测活动中，对于观察结果、相关数据和计算，则应在活动过程中予以详细记录，同时按不同类别进行记录以便识别。\n\n7.5.5 当记录中出现错误时进行修改，每一修改可以追溯到前一个版本或原始观察结果。应保存原始的以及修改后的数据和文档，包括修改的日期、标识修改的内容和负责修改的人员。对以电子形式存储的记录，同样按上述措施要求进行更改，防止原始数据的丢失或改动。\n\n7.5.6 鉴于珠宝检测的特殊性，委托检验的检验报告和鉴定证书，可只保留电子或纸质的原始记录，不再保存报告或证书的副本。检验检测原始记录和报告保存期限不少于6年。\n\n7.5.7 支持性文件\n\n《记录控制程序》 XZTC/CX-19-2018\n',750,'现用文件/质量手册（第四版）.docx#7.5','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('2fade012-7850-45de-b81f-df60af865880','00000000-0000-0000-0000-000000000001','afb48a72-ca24-408e-86d1-685bc252a4a9','f5bfe2a1-1db8-49ca-8b36-6c8c9378a7fc',NULL,'procedure:xztc_cx_23_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 允许偏离的条件\n\n当出现以下几种情况时，可提出允许偏离的申请。\n\n4.1.1 对检测方法的偏离应在被文件规定、经评审、技术负责人批准、客户同意的情况下；\n\n4.1.2 当客户提出偏离要求时。\n\n4.2 允许偏离方法程序的申请和审批\n\n4.2.1 当出现上述条件4.1.1～4.1.2情况时，从事相关项目检测员，应填写《允许偏离申报审批表》，并同时提供必要的资料，交技术负责人审核；\n\n4.2.2 当客户对标准、规范规定的检测方法程序提出偏离要求时，样品管理员负责详细记录客户的偏离要求，并填写《允许偏离申报审批表》，交技术负责人审核；\n\n4.2.3 技术负责人根据申报的内容和相关资料，对其审核，确认需要实施本程序时，上报实验室主任批准（必要时，附处理措施建议）；\n\n4.2.4 技术负责人组织评审并进行审批，监督员根据以下原则实施监督管理：\n\n4.2.4.1 不得违反有关法律法规；\n\n4.2.4.2 不能违背本公司的质量方针；\n\n4.2.4.3 不能损害委托方或甲方的利益；\n\n4.2.4.4 不能影响本公司的公正性和检测数据的准确性；\n\n4.2.4.5 允许偏离后的检测工作应是可纠正的，可追溯的。\n\n4.2.5 技术负责人负责对允许偏离批准，由检测室执行；\n\n4.2.6 通过审批的允许偏离申请，由技术负责人向客户说明，并注明在相应委托书或合同上，由客户签字确认；\n\n4.2.7 当根据审批的允许偏离申请的内容，需进一步制定检测方案时，则允许偏离应在方案中注明。\n\n4.3 允许偏离方法程序的实施\n\n4.3.1 检测人员依据审批后的允许偏离方法程序开展检测工作时，应详细记录相关数据、信息，技术负责人负责其过程的控制。出具的检测报告应对允许偏离注以说明。\n\n4.3.2 监督员应对允许偏离方法程序的实施情况给予必要的监督，并做相应的记录及收集有关偏离后的影响数据。具体执行《检测工作的监督程序》。\n\n4.3.3 技术负责人负责对允许偏离方法程序实施后的结果做出是否满足预期效果的结论，填入《允许偏离申报审核表》中。\n\n4.3.4 当发现允许偏离方法程序实施失控或存在缺陷时，技术负责人应责成检测人员执行《实施纠正措施程序》，进行原因分格，制定相应的纠正措施，对相应文件作出修订、调整或补充。\n\n4.4 当检测条件恢复正常或客户要求停止偏离时，则原有的正在使用的允许偏离措施自动停止使用。\n\n4.5 所有与允许偏离有关的资料由检测部收集整理后交资料管理员存档。\n',150,'现用文件/程序文件/程序文件2022/23-2022允许方法偏离控制程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('2fc3ee4b-8e33-4033-8c4b-55fe1a392859','00000000-0000-0000-0000-000000000001','575be231-b422-4860-84b2-bcd28c6a6d7f','296ce497-e0aa-4f43-a7f0-0b59a7e6e6f8',NULL,'procedure:xztc_cx_15_2022:overview','','不符合检测工作管理程序','section','# XZTC/CX-15-2022 不符合检测工作管理程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/15-2022不符合检测工作管理程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/15-2022不符合检测工作管理程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('310a4a68-cc38-4d95-b515-25abe50daace','00000000-0000-0000-0000-000000000001','40055ae1-3a24-466a-b70a-78bb7c26362a','0cadf789-6c6b-4b36-a6fc-a797e4657a0f',NULL,'procedure:xztc_cx_19_2022:overview','','记录控制程序','section','# XZTC/CX-19-2022 记录控制程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/19-2022记录控制程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/19-2022记录控制程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('313608d9-298d-4aaf-8635-504b567faa34','00000000-0000-0000-0000-000000000001','cda70d11-6fd2-45dc-88ec-6b6b88267f6a','8fd66b6b-cf04-4f03-b795-e5e7a61f9695',NULL,'procedure:xztc_cx_25_2022:source:scope','','范围','scope','### 范围\n\n适用于实验室检测任务的承接至检测完成等全过程管理。\n',130,'现用文件/程序文件/程序文件2022/25-2022检测工作控制程序.docx#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('31fc3b37-b986-4d77-bf0b-5d8f8abe5aae','00000000-0000-0000-0000-000000000001','4b1065a9-98af-473e-b8a2-3d777155a7be','52408b83-0022-4fbd-b6d1-25730e7ff996',NULL,'procedure:xztc_cx_13_2022:source:purpose','','目的','purpose','### 目的\n\n通过沟通提高全体人员的参与意识，确保管理体系的有效性。\n',120,'现用文件/程序文件/程序文件2022/13-2022内部沟通程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('332f7f10-e237-4ae2-a1ed-2a996e797e72','00000000-0000-0000-0000-000000000001','4b1065a9-98af-473e-b8a2-3d777155a7be','52408b83-0022-4fbd-b6d1-25730e7ff996',NULL,'procedure:xztc_cx_13_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《检测工作的监督程序》 XZTC/CX-31-2022\n\n6.记录表格\n\n《会议签到记录表》 XZTC/BG-08-08\n',160,'现用文件/程序文件/程序文件2022/13-2022内部沟通程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('33316e15-c5a5-42b6-8282-f4869deb0998','00000000-0000-0000-0000-000000000001','d1d75375-586e-4570-a58b-afb6e06daac5','82cfd29e-aa37-423c-af0a-375007e365f7',NULL,'procedure:xztc_cx_32_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司所涉及的风险评估和风险控制领域。\n',130,'现用文件/程序文件/程序文件2022/32-2022风险评估控制程序.docx#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('34d9e288-63a2-4b0a-b500-bf20206057bd','00000000-0000-0000-0000-000000000001','bc8c7454-2b19-4837-aeb8-b3d9a1f13d25','30de644c-9b17-4536-86cf-18ad00d7b322',NULL,'procedure:xztc_cx_16_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 持续改进\n\n4.1.1 本公司通过质量方针和目标的落实贯彻、内外部审核结果、客户投诉、信息反馈、数据分析、纠正措施的实施及管理评审的结果，寻找体系持续改进的机会，持续改进管理体系的有效性。\n\n4.2 纠正措施\n\n4.2.1 纠正措施要求的确定\n\n4.2.1.1 纠正措施的采取根据不符合工作的控制、内/外部审核、管理评审、客\n\n户反馈、员工的观察、实验室间比对及能力验证等管理体系和技术运作\n\n中的问题来加以确定。\n\n4.2.2 不符合原因分析、纠正措施制定\n\n4.2.2.1 责任部门调查分析产生问题的原因。原因分析要从确定问题的根本原因开始，确定问题的根本原因需认真分析产生问题的所有环节，确定主要因素。原因可包括：客户的要求、样品及规格、方法和程序、人员的技能和培训、消耗品、仪器设备及校准等。\n\n4.2.2.2 确定问题的根本原因后，应针对其选择和制定消除问题和防止问题再发生的纠正措施，由责任部门填写《实施纠正措施记录表》。\n\n4.2.2.3 选择制定的纠正措施应切实有效，应与问题的影响程度和风险大小相适应，应综合考虑纠正措施的成本与效用。\n\n4.2.2.4 必要时，可对不同纠正措施方案进行比较、验证。\n\n4.2.2.5 质量管理方面不符合纠正措施由质量负责人评价和批准；技术运作方面不符合的纠正措施由技术负责人评价和批准。批准人应对其措施的需求和适用性给予评价。\n\n4.2.3 纠正措施的实施和验证\n\n4.2.3.1 责任部门、岗位人员负责纠正措施的实施，质量负责人/技术负责人组织监督员对纠正措施的实施效果验证，并评价其有效性。\n\n4.2.3.2 由纠正措施而导致任何变更应形成文件，此文件及时发布执行。\n\n4.2.3.3 当对纠正措施的实施效果进行验证性时，且对管理体系运行有效性产生怀疑及有可能产生严重后果时，质量负责人应尽快安排对相关区域进行附加审核。\n\n4.3 纠正措施若引起文件的更改,按《文件控制管理程序》执行。\n\n4.4资料员保存纠正措施的原因分析、制定、实施和验证的有关记录，并负责提交管理评审。\n\n4.3 纠正措施的监管\n\n4.3.1 监督员对纠正措施的实施过程、纠正措施的结果进行监控，认真检查纠正措施是否切实消除了问题发生的原因，以便验证纠正措施的有效性。\n\n4.4 附加审核\n\n4.4.1 针对发现的比较严重的不符合项，经评价问题确实严重或严重危害检测业务，已经影响到本公司实际运作情况对管理体系或认可准则的符合性时，应当立即报告实验室主任，由其决定是否需要采取附加审核，由质量负责\n\n人按照《内部审核程序》的要求组织人员对相关活动区域进行审核。\n\n4.4.2 纠正措施若引起文件的更改，按《文件控制程序》执行。\n\n4.5 资料管理员保存纠正措施的原因分析、制定、实施和验证的有关记录，并负 责提交管理评审。\n',150,'现用文件/程序文件/程序文件2022/16-2022实施纠正措施程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('37054454-0333-4ac0-b6f6-64c6a03c071d','00000000-0000-0000-0000-000000000001','40055ae1-3a24-466a-b70a-78bb7c26362a','0cadf789-6c6b-4b36-a6fc-a797e4657a0f',NULL,'procedure:xztc_cx_19_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 负责设计各项技术记录表格。\n\n3.2 质量负责人应：\n\n3.2.1 负责质量记录保存期限的审批。\n\n3.3 技术负责人应：\n\n3.3.1 负责技术记录保存期限的审批。\n\n3.4 资料管理员应：\n\n3.4.1 负责记录的管理工作。\n\n3.2.1及时发放记录格式的有关信息；\n\n3.2.2负责标识、收集、编目、保存记录等工作。\n\n3.5 检测人员应：\n\n3.5.1 负责各种技术记录的填写。\n',140,'现用文件/程序文件/程序文件2022/19-2022记录控制程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('3777a960-6d4e-4331-b1e0-8042abd412f1','00000000-0000-0000-0000-000000000001','544b293a-5553-4bfe-baef-80b1c8d9e410','a343bfe0-5a01-4e73-8d80-9e2fe7ca3f22',NULL,'procedure:xztc_cx_24_2022:overview','','开展新项目评审程序','section','# XZTC/CX-24-2022 开展新项目评审程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/24-2022开展新项目评审程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/24-2022开展新项目评审程序.docx','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('377eb0cb-b24d-45f8-ba09-2fd5e8cb9635','00000000-0000-0000-0000-000000000001','9a4a4b45-61c0-4fad-a8ff-ef554366ea0f','647474cd-a228-43a8-ade5-a9a43a4ebe48',NULL,'procedure:xztc_cx_14_2022:source:scope','','范围','scope','### 范围\n\n适用于所有来自客户和其他方面投诉的处理\n',130,'现用文件/程序文件/程序文件2022/14-2022处理投诉程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('378e7c98-14a3-4d23-b510-ba14d2e1311e','00000000-0000-0000-0000-000000000001','4573b997-12b2-4cd2-8689-6590c02ae7b7','f381721c-0f02-476f-b688-9bb0ebefb96e',NULL,'procedure:xztc_cx_27_2022:source:scope','','范围','scope','### 范围\n\n本程序适用于测量不确定度以及判断测量结果是否处于合理不确定度范围内的情况。不确定度评定的应用范围：检测方法要求、客户的要求、据以做出满足某规范决定的窄限、其它需进行不确定度评定的情况，如比对检测等。\n',130,'现用文件/程序文件/程序文件2022/27-2022测量不确定度的评审控制程序.docx#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('37a85352-014c-4b8b-9c8e-0e8ecec7f5cb','00000000-0000-0000-0000-000000000001','ddbdafda-6b10-4c15-bd38-6c64672f57d1','4b70f485-3633-4627-be9b-28114a44e2a7',NULL,'procedure:xztc_cx_22_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 质量负责人应：\n\n3.1.1 组织有关人员制定检测方案、主持检测方法的评审并确认；\n\n3.1.2 负责组织协调实验室间的比对。\n\n3.2 检测部应：\n\n3.2.1 负责提出检验方法确认的申请。\n\n3.3 技术负责人应：\n\n3.3.1 负责检测标准方法的查新。\n',140,'现用文件/程序文件/程序文件2022/22-2022检测方法的选择与确认程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('37fad7d7-9a41-4ea4-b5d9-29947210b5cc','00000000-0000-0000-0000-000000000001','1917466d-93d3-4089-9509-3c8928052166','41376c7d-5629-443e-92be-2c8727f1036e',NULL,'procedure:xztc_cx_03_02_2022:source:purpose','','目的','purpose','### 目的\n\n为确保实验室所需的参考标准和标准物质，始终处于受控状态的规范管理，确保检验结果的准确性，可靠性，可比性。\n',120,'现用文件/程序文件/程序文件2022/03-02-2022标准物质管理程序.docx#目的','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('38081583-378c-4da4-95c2-a035b7edaca1','00000000-0000-0000-0000-000000000001','cda70d11-6fd2-45dc-88ec-6b6b88267f6a','8fd66b6b-cf04-4f03-b795-e5e7a61f9695',NULL,'procedure:xztc_cx_25_2022:source:records','','记录','record_requirement','### 记录\n\n《检测委托合同单》 XZTC/BG-09-02\n\n《仪器设备使用记录表》 XZTC/BG-03-02\n\n《报告发放登记表》 XZTC/BG-29-03\n',170,'现用文件/程序文件/程序文件2022/25-2022检测工作控制程序.docx#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('38a49a38-af44-4ec3-8096-965af6e57ee7','00000000-0000-0000-0000-000000000001','dc7146d9-e84c-407e-8e35-2515e05d7642','3b870297-530f-4b96-a1fd-83e397708084',NULL,'procedure:xztc_cx_05_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1实验室主任应：\n\n3.1.1负责仪器设备检定/校准计划的批准。\n\n3.2技术负责人应：\n\n3.2.1负责仪器设备检定/校准计划的审核。\n\n3.3设备管理员应：\n\n3.3.1负责在用仪器设备检定/校准计划的编制和实施。\n',140,'现用文件/程序文件/程序文件2022/05-2022实现测量可溯源程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('39c1d1fa-5c9e-4879-8942-eb9e9600c62d','00000000-0000-0000-0000-000000000001','810f7acb-fe9d-4025-a66c-0891768b873b','5901e814-4bc7-4220-898e-422827d22b6d',NULL,'procedure:xztc_cx_11_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 服务和供应品的识别\n\n4.1.1 对检测质量有影响的外部支持服务包括：仪器设备的计量检定/校准、仪器设备的搬运、安装、维修、保养；\n\n4.1.2 对检测质量有影响的供应品包括：仪器设备及其零配件、检测过程中所需的标准物质、物质。\n\n4.1.3服务和供应品的需求计划\n\n各实验室根据本室工作的需要，编制本室的服务和供应品采购书面计划，实验室负责人审核后报办公室。由办公室汇集后报技术负责人审查，技术负责人审查后报中心主任批准。临时少量的需求可向办公室口头申请。\n\n采购计划中应尽可能包括型号、规格、类别、级别、检测说明等技术指标和质量要求以及建议的服务方和供应商。\n\n4.2 外部服务机构和供应品供应商的调查、评价、选择\n\n4.2.1质量负责人负责对服务方和供应商进行调查、评价、选择。根据调查评价结果确认《合格服务商/供应商名录》。\n\n4.2.2服务方、供应商的调查应包括下列内容：\n\n⑴是否具备合格的资质；\n\n⑵是否有良好的信誉；\n\n⑶是否能充分保证服务项目和供应品的质量；\n\n⑷收费是否合理、服务是否到位。\n\n4.2.3服务方、供应商的评价和选择应考虑以下内容：\n\n⑴被提名供应商的资信能力；\n\n⑵供应商的供货业绩；\n\n⑶供应商的质量保证能力；\n\n⑷价格；\n\n⑸交货情况；\n\n⑹服务情况。\n\n4.2.4一般情况下均应签订书面服务或供应合同。\n\n4.2.5 评价、选择\n\n4.2.5.1 为保证外部服务和供应品的质量，技术负责人负责组织设备管理员对拟选用的外部服务机构，供应品的供应商（生产厂家、中间供应商）和仪器设备的供应商（生产厂家、中间供应商）进行调查，收集相关证实材料。\n\n4.2.5.2 设备管理员根据收集的信息，组织对服务和供应品的供应商（生产厂家）进行评价，填写《供应商评价表》和《合格供应商和外部服务机构名册》，经技术负责人审核；实验室主任批准后使用。\n\n4.2.5.3 采购过程中应在《合格供应商和外部服务机构名册》中选用供应商。如果《合格供应商和外部服务机构名册》仍不能满足需要，则按以上要求对拟选用的供应商进行调查、评价，合格后补入《合格供应商和外部服\n\n务机构名册》，以供选择。\n\n4.2.6 再评价\n\n4.2.6.1 每年12月份，检测部组织设备管理员对在册供应商在本年度内的供应情况进行评价；\n\n4.2.6.2 凡经评价不合格的供应商，将此供应商从《合格供应商和外部服务机构名册》中删除。有新的供应商经评价合格，加入到新名册中，重新整理《合格供应商和外部服务机构名册》，经技术负责人审核、实验室主任批准后使用。\n\n4.3 采购申请\n\n4.3.1采购申请的提出\n\n4.3.1.1 技术负责人根据检测工作的需要，组织设备管理员对供应品的需求情况\n\n提出申请，填写《物品采购申请/验收表》。采购申报表中应明确供应品的名称、规格、数量、技术要求等要求。\n\n4.3.1.2 购置仪器设备时，由技术负责人组织设备管理员提出申请填写《仪器设备购置申报表》，写明购置理由及产品的质量、技术性能、指标的要求。\n\n4.3.1.3 采购计划中应明确供应品名称、规格、数量、单价及质量要求。\n\n4.3.1.4 根据仪器设备的计量检定/校准的服务需求情况，技术负责人组织设备管理员编制计量检定/校准的服务需求计划。服务需求计划中应明确服务的内容、时间要求、服务方的资质、服务质量等要求。\n\n4.3.2 实施\n\n4.3.2.1 技术负责人将采购计划和服务需求计划报技术负责人审核，实验室主任批准后实施。\n\n4.3.2.2 办公室主任根据采购计划中的要求，选择合适的供应商。对重大的或大宗的供应品，应签订采购合同。采购合同中应明确供应品的名称、规格、型号、类别、等级、明确的标识、图纸、检查说明、质量要求、质量标准及其他技术资料、验收时机和方式。\n\n4.3.2.3 办公室主任根据计量检定/校准的服务需求计划中的要求，选择合适的计量检定/校准的服务供应商，并签订服务合同。服务合同中应明确服务的内容、时间要求、质量要求、服务的方式、验收标准及其他要求，明确双方的责、权、利等。\n\n4.4 验收\n\n4.4.1 购入仪器设备的验收\n\n技术负责人根据采购计划中的质量要求组织相关人员进行验收，并填写《购入仪器设备验收记录》。验收包括：\n\n4.4.1.1 文件资料验证：合格证、说明书、保修卡、有关技术资料应齐全有效；\n\n4.4.1.2 实物验证：包装是否完好，仪器设备有无损坏、规格、型号、外观质量是否符合要求，随机附件是否齐全；\n\n4.4.1.3 调检验证：安装质量是否符合要求，仪器设备运转是否正常，技术性能、指标是否达到规定要求。\n\n4.4.2 其他供应品的验收\n\n4.4.2.1 供应品到货后，技术负责人根据采购计划中的质量要求组织相关人员进行验收，填写《物品采购申请/验收表》作为接收入库的凭证。\n\n4.4.2.2 验收内容\n\n4.4.2.2.1 资料验收：进货单的规格、型号、数量、质量是否与计划和采购合同一致，合格证、生产许可证和其他质量证明手续是否齐全。\n\n4.4.2.2.2 实物验收：是否符合采购合同中所要求的品种、规格型号、技术要求、数量、标识、包装，外观有无变形、过期、破损等。\n\n4.4.3 计量检定/校准的服务验收\n\n4.4.3.1 服务完成后，技术负责人组织有关人员对其服务项目进行验收。\n\n4.4.4 经验收不合格的，按不符合检测工作控制程序处置\n\n4.5 库房管理\n\n4.5.1 供应品验收合格后，设备管理员填写入库单，同时按类别填写物品台账。\n\n4.5.2 领用\n\n检测部需要领用物品时，填写资料单，经办公室主任审核，技术负责人批准后领取。设备管理员按领料单发放物品。有保存期限要求的物品，应做到先进先出，防止过期浪费。\n\n4.5.3 贮存\n\n4.5.3.1 库房内物品宜分区贮存，有毒、易燃、贵重物品应设专库存放，严禁不同物品混放。\n\n4.5.3.2 库房应作到防火、防盗、防潮等要求，设置必要的设施并设专人保管。\n\n4.5.3.3 库房内物品应有标识牌，进行正确的标识，做到账务、卡相符。标识牌应包括物品的名称、规格型号、数量、检测状态。\n\n4.5.4 搬运\n\n4.5.4.1 物品在搬运过程中，物品管理员注意保护好物品。\n\n4.5.4.2 对易燃易爆、易碎、易损、贵重物品的搬运、应明确搬运方法、工具、人员的要求。\n\n4.6检查验收不合格的处理\n\n4.6.1检查验收发现不合格供应品或服务项目时，应在验收报告或检查确认记录中注明项目、内容、依据、处理意见等报技术负责人同意后向服务方或供应商提出并要求解决。\n\n4.6.2不合格的仪器设备、标准物质、零配件、试剂、消耗材料等不能投入使用。\n\n4.7服务和供应品采购计划、服务方和供应商记录、检查和验收记录等均应归档保存，执行《记录管理程序》。\n',150,'现用文件/程序文件/程序文件2022/11-2022外部支持服务和供应品管理程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('3a756ecc-15d3-4912-9377-b84f65936750','00000000-0000-0000-0000-000000000001','4573b997-12b2-4cd2-8689-6590c02ae7b7','f381721c-0f02-476f-b688-9bb0ebefb96e',NULL,'procedure:xztc_cx_27_2022:overview','','测量不确定度的评审控制程序','section','# XZTC/CX-27-2022 测量不确定度的评审控制程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/27-2022测量不确定度的评审控制程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/27-2022测量不确定度的评审控制程序.docx','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('3ac4f7b7-fd67-42e8-b15a-89d205144cb4','00000000-0000-0000-0000-000000000001','43c73354-2b49-458e-b110-281f4f7db028','b835ad93-cc81-40b1-8e88-266b4fe4424e',NULL,'procedure:xztc_cx_01_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 工作职责与人员能力要求\n\n4.1.1 要求：\n\n4.1.1.1 办公室主任组织建立本公司人员名册。\n\n4.1.1.2 技术负责人、质量负责人、监督员、内审员、资料管理员、设备管理员、样品员、报告签发人、检验员、特殊设备操作人员的能力应能满足相应的法律法规、客户和本公司的要求。\n\n4.1.2 能力要求的确定\n\n4.1.2.1 根据法律法规、客户、本公司要求，办公室负责提出并编制《各岗位任职资格条件》（见：《质量手册》6.2.2），由质量负责人审核，实验室\n\n主任批准。\n\n4.1.2.2 根据本公司的岗位人员的能力要求，由实验室主任对4.1.1条涉及的人员，依据其教育、培训、经验和技能，进行能力和资格确认，并将确认结果告知技术负责人，作为制定培训计划的依据。办公室主任负责组织建立检测人员技术档案。\n\n4.1.2.3 本公司必须至少应有2 名取得国家珠宝玉石质量检验师资格并已注册的检验人员， 当涉及贵金属检测时，实验室至少有一名熟悉贵金属知识、了解其性能、熟练掌握其检测方法并进行检测的专业人员，本公司的检验人员，必须是珠宝专业本、专科毕业或经过专业培训并取得相应的资格证书，如国家注册珠宝鉴定师CGC、英国皇家宝石协会FAG证书,当涉及贵金属检测时，实验室至少有一名熟悉贵金属知识、了解其性能、熟练掌握其检测方法并进行检测的专业人员等。\n\n4.1.2.4 对于两年以上未从事珠宝玉石检验的人员，在重新上岗检验时，必须重新经过培训并获得4.1.2.3中所规定的资格证书后才能承担主要检验任务。\n\n4.1.2.5本公司的授权签字人应满足《检测和校准实验室能力认可准则》、CNAS-CL01-A015:2022和《检验检测机构资质认定能力评价 检验检测机构通用要求》RB/T214-2017的要求。\n\n4.2 签约人员管理\n\n4.2.1 监督管理\n\n监督员应对本公司使用的长期雇佣人员、签约人员、额外技术人员及关键的支持人员进行有效的监督管理，确保这些人员能够胜任。\n\n4.2.1.1 在试用期满后，由使用部门将试用人员在试用期间的工作、考核、鉴定情况上报办公室主任。对通过考核鉴定的人员，办公室主任上报实验室主任正式录用。\n\n4.2.1.2 实验室主任负责全公司工作的监督，技术负责人负责对技术工作的监督，质量负责人负责对管理体系工作的监督，监督员负责对各岗位的技术活动的监督。\n\n4.3 培训管理\n\n4.3.1 培训计划\n\n4.3.1.1 需求确定：\n\n技术负责人根据本公司业务发展的需要，岗位人员的能力确定情况，各阶段的人员考核情况，相关法律法规，客户要求和各部门的需求，确定\n\n培训目标。\n\n4.3.1.2 培新计划的制定：\n\n技术负责人根据确定的培训需求，于每年底份制定下一年度的培训计划\n\n（见：《年度人员培训计划表》）。如有临时培训的要求，制定临时补充培\n\n训的计划。人员培训计划的内容：应包括岗前、转岗、技能再提高、仪\n\n器设备更新后或投入使用前、执行新标准或新方法前、开展新的检测项\n\n目前所涉及的专业知识、校准知识、质量控制和监督管理知识、计量理论知识、误差理论、数据处理、法律法规、职业道德规范等各岗位所需的应知应会的培训，等各岗位所需的应知应会培训，计划中要明确人员教育、培训和技能的目标。培训计划报实验室主任审批后由质量负责人组织实施。\n\n4.3.2 培训计划的实施\n\n质量负责人按培训计划内容，落实每一项培训工作。\n\n4.3.2.1 由本公司内部组织的培训，质量负责人应提前落实好培训地点和培训教材，选择合适的教员，做好培训记录和必要时的培训考核记录（见：《人员培训记录表》）。\n\n4.3.2.2 外委培训人员，质量负责人应提前联系好培训单位或机构其他相关事宜。送外委托培训人员名单由技术负责人审核后交实验室主任批准，并做好培训记录（见：《人员培训记录表》）。\n\n4.3.2.3 送外培训取得有关资质及学习证明书（或复印件）交资料管理员归入个人技术档案保存。\n\n4.3.3 培训考核\n\n4.3.3.1 对于每次内部培训，必要时质量负责人组织有关人员应采取提问、实际操作、笔试等适宜方式，对培训的有效性进行考核（见：《人员培训记录表》）。\n\n4.4 岗位工作职责的规定要求\n\n4.4.1 质量负责人应组织编制技术负责人、质量负责人、样品管理员、报告签发人、检测员、监督员、设备管理员、内审员等人员的《各岗位职责》（见：《质量手册》6.2.2）权限，由质量负责人审核后报实验室主任审核、批准后实施。\n\n4.4.2 当前工作描述应包括以下内容：\n\n4.4.2.1 从事检测工作方面的职责\n\n4.4.2.2 检测计划和结果评价方面的职责\n\n4.4.2.3 提交意见和解释的职责\n\n4.4.2.4 方法改进、新方法制定和确认方面的职责\n\n4.4.2.5 所需的专业知识和经验\n\n4.4.2.6 资格和培训计划\n\n4.4.2.7 管理职责\n\n4.5 人员技术档案\n\n4.5.1 人员技术档案应包括以下内容：\n\n4.5.1.1 有档案目录以便于查阅；\n\n4.5.1.2 学历证明；\n\n4.5.1.3 学位证明；\n\n4.5.1.4 职称证明；\n\n4.5.1.5 培训、技能和经验的记录；\n\n4.5.1.6 授权和/或能力确认证明。\n',150,'现用文件/程序文件/程序文件2022/01-2022人员培训程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('3c7d1d08-cd5f-4a2d-aa61-1b9f8e884fc9','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_7','7.7','确保结果有效性','section','## 7.7 确保结果有效性\n\n7.7.1 本公司应对所开展的检测项目的检测结果的质量进行有效性控制，开展有计划和有系统的质量保证活动，保证检测结果的准确性、可靠性，提高客户对本公司的信任。\n\n7.7.2 本公司制定了《检测结果质量控制及能力验证程序》，程序中规定了一系列质量控制活动，确定了监控计划的编制、实施要求和内容。\n\n7.7.3 在检测活动中，在可行的情况下采用适合的统计技术使检测的质量发展趋势得到及时了解，以便发现异常波动，采取预防措施加以控制。\n\n7.7.4 监控活动将有计划性地实施，并对其计划内容、监控措施进行定期的评审，以适当调整计划内容，保证计划实施的有效性。\n\n7.7.5 本公司应根据有证标准物质的来源情况、检测的特性和范围以及实验室人员的多少来制定内部质量控制计划，该计划包括可疑结果的判断准则。适当时，内部质量控制计划所采用的技术可包括但不限于：\n\n使用标准物质或质量控制物质；\n\n使用其他已校准能够提供可溯源结果的仪器；\n\n测量和检测设备的功能核查；\n\n适用时，使用核查或工作标准，并制作控制图；\n\n测量设备的期间核查；\n\n使用相同或不同方法重复检测；\n\n保存样品的重复检测；\n\n物品不同特性结果之间的相关性；\n\n审查报告的结果；\n\n实验室内比对；\n\n盲样测试。\n\n7.7.6 质量监控计划的制定和实施\n\n7.7.6.1 本公司将根据具体情况、专业范围、技术特点，制定年度质量监控计划及实施。\n\n7.7.6.2 将根据年度质量监控计划的安排，结合本公司具体情况有序地开展活动，在日常工作中对检测过程中影响因素与检测结果质量进行监控，定期或不定期地对本公司的数据记录进行分析。\n\n7.7.6.3 应分析质量控制的数据，在发现质量控制数据超出预定的判据时，应采取有计划的纠正措施或风险管控，并防止报告错误的结果。具体可执行《不符合检测工作管理程序》《实施纠正措施程序》《风险评估控制程序》。\n\n7.7.7 每年对质量监控计划的适宜性及时进行评审，并对实施效果进行评定，其结果提交管理评审。\n\n7.7.8 支持性文件\n\n《不符合检测工作管理程序》 XZTC/CX-15-2018\n\n《实施纠正措施管理程序》 XZTC/CX-16-2018\n\n《风险评估控制程序》 XZTC/CX-32-2018\n\n《检测结果质量控制及能力验证程序》 XZTC/CX-30-2018\n',770,'现用文件/质量手册（第四版）.docx#7.7','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('3c86193e-a612-471f-b1f0-dc206c36ed4a','00000000-0000-0000-0000-000000000001','bd275009-ec1d-4a48-b6fc-39304fe0dee9','f488cefe-287f-47a2-b075-c5cd1cbcfa0b',NULL,'procedure:xztc_cx_17_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《文件控制程序》 XZTC/CX-08-2022\n\n《不符合检测工作管理程序》 XZTC/CX-15-2022\n\n《记录控制程序》 XZTC/CX-19-2022\n《内部管理体系审核程序》 XZTC/CX-20-2022\n\n《管理评审程序》 XZTC/CX-21-2022\n',160,'现用文件/程序文件/程序文件2022/17-2022实施预防措施程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('3db44996-8ba9-463b-ac4e-5d5d789271f8','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:8_5','8.5','应对风险和机遇的措施','section','## 8.5 应对风险和机遇的措施\n\n8.5.1 实施有效的预防措施可以消除潜在的不符合情况，可以化解可能发生的风险，避免出现质量风险和其他不期望的结果对本公司和客户利益的损害。本公司无论在技术方面还是在管理体系方面，都应主动寻找潜在的不符合，分析原因，采取相应的预防措施，执行《实施预防措施程序》，以减少类似不符合情况发生的可能性并以此改进提高本公司的质量工作。\n\n8.5.2 公司管理层应组织人员经常分析对公司可能存在的不符合的潜在原因，并适时制定相应的预防措施的实施计划和程序，预防措施程序应包括措施的启动和控制、趋势和风险分析以及能力验证结果在内的资料分析，以确保其有效性。\n\n8.5.3 机遇可能促使实验室扩展活动范围，使用新技术、新方法可提高实验室检测的质量，但应满足本手册对方法的选择、验证和确认等相关要求，确保结果符合有关法律规范的要求。\n\n8.5.4 支持性文件\n\n《实施预防措施程序》 XZTC/CX-17-2018\n\n《风险评估控制程序》 XZTC/CX-32-2018\n',860,'现用文件/质量手册（第四版）.docx#8.5','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('3e7c99e2-977d-441e-8564-fb22f8b2964d','00000000-0000-0000-0000-000000000001','4b1065a9-98af-473e-b8a2-3d777155a7be','52408b83-0022-4fbd-b6d1-25730e7ff996',NULL,'procedure:xztc_cx_13_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司管理活动涉及到的所有部门和员工。\n',130,'现用文件/程序文件/程序文件2022/13-2022内部沟通程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('3ea28422-1850-4195-a036-b8c6e36f199e','00000000-0000-0000-0000-000000000001','544b293a-5553-4bfe-baef-80b1c8d9e410','a343bfe0-5a01-4e73-8d80-9e2fe7ca3f22',NULL,'procedure:xztc_cx_24_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 开展新项目的需求\n\n4.1.1 根据市场变化的需求，检测标准的修订及更新，检测部及公司领导，可提出开展（增加）新的检测项目或应用新方法标准的需求和申请（见《开展新项目申请表》）。\n\n4.1.2 技术负责人根据工作需求和申请制订开展新检测项目计划，报实验室主任审核。\n\n4.1.3 技术负责人组织相关人员进行论证，是否有足够能力开展新的检测项目工作，包括必要的检测仪器设备，环境设施，相应的标准和人员等。\n\n4.1.4 通过论证的计划，经实验室主任批准后，由技术负责人制定实施方案和组织实施。\n\n4.2 新项目的开展\n\n4.2.1 经立项批准的新项目，由技术负责人负责组织提供现行有效标准规范及检测方法，及设备、人员要求，技术负责人组织人员编写作业指导书（必要时）及检测人员的培训，提供报告格式信息内容。\n\n4.2.2 技术负责人负责组织人员按照要求及相关程序文件要求，编制仪器设备、检测消耗品采购计划，改造设施环境，购进后仪器设备的检定等工作。\n\n4.2.3 质量负责人从管理体系方面（如文件控制、记录控制、人员、设施和环境、设备、量值溯源、方法、证书和报告）检查验证新项目的开展是否符合管理体系标准的要求。\n\n4.2.4 作业指导书的编制内容。\n\n4.2.4.1 检测方法的名称；\n\n4.2.4.2 检测方法的适用范围；\n\n4.2.4.3 用于检测的仪器设备，包括技术性能参数要求；\n\n4.2.4.4 所需的标准物质（参考物质）；\n\n4.2.4.5 被检测样品的管理要求；\n\n4.2.4.6 被测定参数或量值及其范围；\n\n4.2.4.7 检测需要的设施环境条件；\n\n4.2.4.8 检测程序描述；\n\n4.2.4.9 需遵守的安全设施；\n\n4.2.4.10 检测的准则和要求；\n\n4.2.4.11 需记录的数据的分析和表达的方法；\n\n4.2.4.12 如有必要时，检测结果不确定度评定的要求。\n\n4.2.5 若开展新项目的同时需用非标准方法时，按《检测方法的选择与确认程序》进行制定与控制。\n\n4.2.6 检测人员的要求（负责新项目检测人员）\n\n4.2.6.1 项目负责人应具有两年以上检验工作经验，本科及以上学历。\n\n4.2.6.2 检测人员具有两年以上检测工作经验，大专以上学历。\n\n4.2.7 对于申请国家有检测方法标准的项目，应按国家检测方法操作。对于国家没有检测方法标准的项目，应按自定检测标准的要求予以确认，执行《检测方法的选择与确认程序》。\n\n4.3 新项目的实施验证\n\n4.3.1 技术负责人根据实施方案下达检测任务通知书，进行方法验证。\n\n4.3.2 验证内容包括：\n\n4.3.2.1 全部输入的文件资料的有效性、适宜性；\n\n4.3.2.2 人员培训效果；\n\n4.3.2.3 仪器设备的配置及校准状态；\n\n4.3.2.4 设施环境条件符合情况；\n\n4.3.2.5 项目检测人员的模拟检测（不少于三次）；\n\n4.3.2.6 通过实验室间比对结果验证；\n\n4.3.2.7 必要时，计算出检测结果的测量不确定度；\n\n4.3.3 检测部根据验证结果填写《开展新项目评审表》，经技术负责人组织论证和批准试运行。\n\n4.3.4 技术负责人根据新的检测项目要求组织编制有关文件，组织培训和考核，组织进行必要的试运行。\n\n4.3.5 试运行成熟后，经技术负责人审核，实验室主任批准后，将新检测项目列入本公司可承检项目中，正式纳入管理体系运行，审核内容如下：\n\n4.3.5.1 检测目的和法律、法规的要求，\n\n4.3.5.2 检测标准/方法和作业文件；\n\n4.3.5.3 检测仪器设备检定结果；\n\n4.3.5.4 检测消耗品来源及其质量；\n\n4.3.5.5 检测环境和设施与后勤保障；\n\n4.3.5.6 人员职责与培训；\n\n4.3.5.7 熟练检测和比对的结果；\n\n4.3.5.8 其他相关要求。\n\n4.3.6 新项目通过验证符合要求后，报实验室主任同意后向中国合格评定国家认可委员会申请认可增项。\n\n4.3.7 对于新修订的或更新的标准等的应用，经上述程序由公司内部组织验证符合要求后，即可用于检测工作。在新标准采用初期，应加强监督员的质量监督工作。\n',150,'现用文件/程序文件/程序文件2022/24-2022开展新项目评审程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('409b8fc0-84a3-474e-a7b2-02f80454b81c','00000000-0000-0000-0000-000000000001','76ffd146-ed11-4da9-a42a-c1ef8787db95','a64ffdaa-5ea0-412e-b076-f9c0c9283c85',NULL,'procedure:xztc_cx_29_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司出具的各类检测报告的编制、核验、签发、修改等活动。\n',130,'现用文件/程序文件/程序文件2022/29-2022结果报告管理程序.docx#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('40a059bf-0717-4a8d-898e-05a652c24000','00000000-0000-0000-0000-000000000001','575be231-b422-4860-84b2-bcd28c6a6d7f','296ce497-e0aa-4f43-a7f0-0b59a7e6e6f8',NULL,'procedure:xztc_cx_15_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《处理投诉程序》 XZTC/CX-14-2022\n\n《实施纠正措施程序》 XZTC/CX-16-2022\n\n《内部管理体系审核程序》 XZTC/CX-20-2022\n\n《文件控制管理程序》 XZTC/CX-08-2022\n',160,'现用文件/程序文件/程序文件2022/15-2022不符合检测工作管理程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('411681e6-7963-4835-9ff7-edcb0e0c4e70','00000000-0000-0000-0000-000000000001','f0487552-998f-4890-94df-49779d41b185','48e77eb2-f569-435f-b92e-7a4a99351f71',NULL,'procedure:xztc_cx_20_2022:source:purpose','','目的','purpose','### 目的\n\n验证本公司体系是否符合管理体系和《实验室资质认证评审标准》的要求，检查管理体系的各项要求是否在工作中得到全面的贯彻，发现和解决问题，确保管理体系得到有效运作和持续改进。\n',120,'现用文件/程序文件/程序文件2022/20-2022内部管理体系审核程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('4256f3c1-42b8-4b96-a39d-b89fe55fb534','00000000-0000-0000-0000-000000000001','ce715165-4592-4000-9ca6-0d9fcae8c9e5',NULL,NULL,'external_basis:cnas_cl01_a015_2018:overview','','检测和校准实验室能力认可准则在珠宝玉石、贵金属检测领域的应用说明','section','# CNAS-CL01-A015:2018 检测和校准实验室能力认可准则在珠宝玉石、贵金属检测领域的应用说明\n\n- 来源类型：external_guidance\n- 版本：2018\n- 实施日期：2018-09-01\n- 查新状态：due\n- 查新日期：2026-07-19\n- 查新结论：本地正式依据文件缺失\n- 查新证据：参考/2025年最新版CMA和CNAS质量体系/07-CNAS-CL01-A015：2018 检测和校准实验室能力认可准则在珠宝玉石、贵金属检测领域的应用说明.pdf\n- 下次查新：2027-07-19\n- 归档文件：参考/2025年最新版CMA和CNAS质量体系/07-CNAS-CL01-A015：2018 检测和校准实验室能力认可准则在珠宝玉石、贵金属检测领域的应用说明.pdf\n- 正式条款数：0\n',100,'参考/2025年最新版CMA和CNAS质量体系/07-CNAS-CL01-A015：2018 检测和校准实验室能力认可准则在珠宝玉石、贵金属检测领域的应用说明.pdf','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:19',NULL,NULL),('42e46a92-d95e-4606-87b0-dd62d5904a6b','00000000-0000-0000-0000-000000000001','9d510096-db76-494b-af6a-0346649008e6','85c08c02-e477-43d9-8b8a-185fa6d8912b',NULL,'procedure:xztc_cx_28_2022:source:records','','记录','record_requirement','### 记录\n\n《样品台账》 XZTC/BG-28-01\n\n《样品标识卡》 XZTC/BG-28-02\n\n《样品损坏、丢失报告表》 XZTC/BG-28-03\n',170,'现用文件/程序文件/程序文件2022/28-2022样品处置和管理程序.docx#记录','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('42e9410f-952a-4ed4-a197-1d7844296ce6','00000000-0000-0000-0000-000000000001','40055ae1-3a24-466a-b70a-78bb7c26362a','0cadf789-6c6b-4b36-a6fc-a797e4657a0f',NULL,'procedure:xztc_cx_19_2022:source:records','','记录','record_requirement','### 记录\n\n《记录归档登记表》 XZTC/BG-19-01\n\n《记录借阅登记表》 XZTC/BG-19-02\n\n《质量记录清单及保存期限表》 XZTC/BG-19-03\n\n《技术记录清单及保存期限表》 XZTC/BG-19-04\n',170,'现用文件/程序文件/程序文件2022/19-2022记录控制程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('42f69519-25be-4430-892f-381b75a67cea','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:6_6','6.6','外部提供的产品和服务','section','## 6.6 外部提供的产品和服务\n\n6.6.1 范围\n\n外部提供的产品包括测量标准和设备、辅助设备、消耗材料和标准物质。外部服务包括校准服务、抽样服务、检测服务、设施和设备维护服务、能力验证服务以及评审和审核服务。做好对外部支持服务和供应品的质量控制是保证检测结果质量的重要环节之一。本公司对影响检测质量的供应品和外部支持服务质量的控制执行《外部支持服务和供应品管理程序》。\n\n6.6.2 供应品和外部支持服务的验收\n\n6.6.2.1 供应品的验收：\n\n供应品是指对检测结果有影响的物品，对供应品的验收按照采购文件中规定的验收标准和质量要求进行，只有当证明物品质量符合检测标准、规范的要求后方可投入使用，其验收证明记录均保留。\n\n6.6.2.1 外部支持服务的验收：\n\n包括检测仪器设备的检定/校准、搬运、安装、维修、保养、计算机服务系统（含硬件、软件）等；外部支持服务完成后，本公司组织人员对服务质量按规定的验收标准进行验收，验收不合格的不接收，其验收证明记录均保留，所有的供应品和外部支持服务必须在验收合格之后才能投入使用。\n\n6.6.3 外部服务和供应品的采购\n\n本公司在采购物品以及外部服务时，应事先编制详细的采购文件，经批准后，检测人员应记录所使用的供应品的质量状况，为评价、选择合格供应商提供信息。\n\n6.6.4 外部支持服务和供应品的评价\n\n在采购前，由本公司组织对拟选用的服务和供应品进行评价，并将通过评价的合格供应商列入《合格供应商名册》，经批准发布，以供作为选择供应商的依据，并保存评价记录及《合格供应商名册》。定期根据产品和服务质量进行再评价。\n\n6.6.5 支持性文件\n\n《外部支持服务和供应品管理程序》 XZTC/CX-11-2018\n\n《记录控制程序》 XZTC/CX-19-2018\n\n7. 过程要求\n',660,'现用文件/质量手册（第四版）.docx#6.6','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('43f34485-88b7-4417-82fc-2703fac66435','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:6_3','6.3','设施和环境条件','section','## 6.3 设施和环境条件\n\n6.3.1 本公司对用于检测的设施、环境的提醒配置和应用实施控制管理，制定了《设施与环境条件控制和维护程序》，防止设施和环境条件对检测结果的不良影响，确保检测结果的准确有效。\n\n6.3.2 根据检测工作范围、项目的要求，提供配置适宜的检测场所和办公环境，并进行合理有效的布局，防止对检测工作产生不利影响。\n\n6.3.3 本公司设施和环境条件的配置应满足以下要求：\n\n保证动力电和照明用电的供给；\n\n天平放置在稳定的、防震动的桌子上，以保证其稳定性；\n\n对与本公司相邻区域采取有效的隔离措施；\n\n本公司应有与检测范围相应的安全监控设施等；\n\n对检测结果有影响的设施和环境条件的技术要求，按检测标准和相关要求编制作业指导书；\n\n检测室在日常工作中对影响检测结果的设施和环境条件实施监测、控制，并予以记录；\n\n检测室应注意环境条件因素（诸如灰尘、电磁干扰、温度、湿度、供电和振动等）对检测技术活动的影响。当发现环境条件危及检测结果时，检测师应停止检测；\n\n实验室与办公区要保持良好的隔离，并进行标识，无关人员未经批准不得随意进入实验区域；\n\n本公司制定并实施有关安全和人员健康的文件化程序，并配备了相应的安全防护设施；\n\n本公司应配备妥善处理有害废弃物的设施并编制相应的作业指导书；\n\n检测室内加强内务管理，配置必要的消防设施，保证检测区域的整洁、安全。\n\n6.3.4 本公司的各项检测活动都在固定场所内进行，无控制之外的地点或设施。\n\n6.3.5 当实验室发生地址搬迁或环境重大变化时，必须立即停止使用认可标识，待制定验证计划并经CNAS现场确认合格后，方可恢复使用 。\n\n6.3.6 检验检测活动涉及用电，检测样品检测前、检测中、检测后的完整和安全，因此必须树立安全第一的意识，保证安全生产，必须建立和保持相应识别风险、评估风险、风险控制的程序，对存在的安全隐患加以控制，确保检测工作场所、环境及对其有影响的周边环境安全，保证公司及客户财产的安全。\n\n6.3.6 支持文件\n\n《设施与环境条件控制和维护程序》 XZTC/CX-02-2018\n\n《内务与安全管理程序》 XZTC/CX-33-2018\n\n《检测工作的监督程序》 XZTC/CX-31-2018\n',630,'现用文件/质量手册（第四版）.docx#6.3','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('4543c578-355a-4a90-ae9e-5352a896bae5','00000000-0000-0000-0000-000000000001','bc8c7454-2b19-4837-aeb8-b3d9a1f13d25','30de644c-9b17-4536-86cf-18ad00d7b322',NULL,'procedure:xztc_cx_16_2022:source:records','','记录','record_requirement','### 记录\n\n《实施纠正措施记录表》 XZTC/BG-16-01\n',170,'现用文件/程序文件/程序文件2022/16-2022实施纠正措施程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('45c9cd54-bba6-4466-87dc-9254e6888ddb','00000000-0000-0000-0000-000000000001','7e5f11cb-e0dd-4d71-b0ba-357981f48045','7f87a99b-52a2-4b35-98d4-c4e17fc06bac',NULL,'procedure:xztc_cx_18_2022:overview','','改进控制程序','section','# XZTC/CX-18-2022 改进控制程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/18-2022改进控制程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/18-2022改进控制程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('45cce676-566c-4e00-9336-c03c2595fc6a','00000000-0000-0000-0000-000000000001','44ff5408-e03d-4859-9cd4-926a8f69fda5','948d2434-2b53-47e6-adab-cf2ee95dfc3c',NULL,'procedure:xztc_cx_09_2022:source:scope','','范围','scope','### 范围\n\n适用于公司对标书或合同的评审、签订、执行及与客户的沟通。\n',130,'现用文件/程序文件/程序文件2022/09-2022客户要求、标书、合同评审程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('47523c7f-7545-427a-a7ad-1aa34e407586','00000000-0000-0000-0000-000000000001','9f720d1f-600b-423a-8082-f8987b0594cf','3a8d9ea2-2b78-4dc0-a1e8-164f02246028',NULL,'procedure:xztc_cx_06_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 落实保护机密信息和所有权的措施所需的资源。\n\n3.2 质量负责人应：\n\n3.2.1 制定保护机密信息的措施并对违反保密的行为进行处理；\n\n3.2.2 批准保密资料的借阅；\n\n3.3 技术负责人应：\n\n3.3.1 监督本部人员做好对客户机密信息的保密工作；\n\n3.4 样品管理员应：\n\n3.4.1 了解客户的保密要求，做好样品和相关资料的传递交接记录过程中的保密工作。\n\n3.5 资料管理员应:\n\n3.5.1 做好对有保密要求的文件和资料的保管工作；\n\n3.6 监督员应：\n\n3.6.1 对公司各人员履行保密措施的情况进行监督检查。\n\n3.7 其他有关人员应：\n\n3.7.1 自觉遵守本公司的各种保密规定，做好相应的保密工作。\n',140,'现用文件/程序文件/程序文件2022/06-2022保护客户机密信息程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('47c31480-c7da-45f2-8817-df01fe188b8d','00000000-0000-0000-0000-000000000001','4b1065a9-98af-473e-b8a2-3d777155a7be','52408b83-0022-4fbd-b6d1-25730e7ff996',NULL,'procedure:xztc_cx_13_2022:overview','','内部沟通程序','section','# XZTC/CX-13-2022 内部沟通程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/13-2022内部沟通程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/13-2022内部沟通程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('482612fc-b91a-43dc-858e-ce89126d26de','00000000-0000-0000-0000-000000000001','c2a1158c-96eb-41f7-ac15-c6a434f41e4e',NULL,NULL,'reference_procedure:ref_2025_procedures:overview','','2025年程序文件（CMA和CNAS）参考稿','section','# REF-2025-PROCEDURES 2025年程序文件（CMA和CNAS）参考稿\n\n- 文件定位：参考程序文件，不进入正式体系文件组合包。\n- 来源文件：参考/2025年最新版CMA和CNAS质量体系/02-2025年程序文件（CMA和CNAS）(1).docx\n- 结构化用途：用于与现用质量手册和现用程序文件逐块比对，形成缺口建议或人工修订参考。\n- 控制边界：参考文件不得自动覆盖现用受控文件、条款库或要素映射。\n',100,'参考/2025年最新版CMA和CNAS质量体系/02-2025年程序文件（CMA和CNAS）(1).docx','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('482b80f3-43e9-4163-bba6-1b745abd3ad3','00000000-0000-0000-0000-000000000001','9d510096-db76-494b-af6a-0346649008e6','85c08c02-e477-43d9-8b8a-185fa6d8912b',NULL,'procedure:xztc_cx_28_2022:source:purpose','','目的','purpose','### 目的\n\n规范对样品的接收、标识、流转(运输)、储存的管理，保证样品的完整性、具有代表性和有效性，确保检测结果的科学性和公正性。\n',120,'现用文件/程序文件/程序文件2022/28-2022样品处置和管理程序.docx#目的','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('49f9a20d-a9cb-4328-bdfd-49d385a05f7f','00000000-0000-0000-0000-000000000001','44ff5408-e03d-4859-9cd4-926a8f69fda5','948d2434-2b53-47e6-adab-cf2ee95dfc3c',NULL,'procedure:xztc_cx_09_2022:source:records','','记录','record_requirement','### 记录\n\n⑴《合同、协议登记表》 XZTC/BG-09-03\n\n⑵《合同评审记录表》 XZTC/BG-09-01\n\n⑶《检测委托单》\n',170,'现用文件/程序文件/程序文件2022/09-2022客户要求、标书、合同评审程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('4a8622f5-6460-40ec-96da-d476ef7792a5','00000000-0000-0000-0000-000000000001','afb48a72-ca24-408e-86d1-685bc252a4a9','f5bfe2a1-1db8-49ca-8b36-6c8c9378a7fc',NULL,'procedure:xztc_cx_23_2022:overview','','允许方法偏离控制程序','section','# XZTC/CX-23-2022 允许方法偏离控制程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/23-2022允许方法偏离控制程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/23-2022允许方法偏离控制程序.docx','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('4bc1e792-3733-40a8-9ce6-6dfddfa8a1c6','00000000-0000-0000-0000-000000000001','bd275009-ec1d-4a48-b6fc-39304fe0dee9','f488cefe-287f-47a2-b075-c5cd1cbcfa0b',NULL,'procedure:xztc_cx_17_2022:source:records','','记录','record_requirement','### 记录\n\n《实施预防措施记录表》 XZTC/BG-17-01\n',170,'现用文件/程序文件/程序文件2022/17-2022实施预防措施程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('4cc5c5cd-0994-460e-afd4-755ff3ca31b4','00000000-0000-0000-0000-000000000001','684b63da-4e5d-4436-bd6f-95cd011fd70d','bbf06eea-34a2-451e-9ac6-88cf92290425',NULL,'procedure:xztc_cx_01_02_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1公司实验室主任负责人员的聘用。\n\n3.2质量负责人负责各个岗位人员工作的监督。\n\n3.3全体员工按检验检测机构人员管理程序要求进行检测工作。\n\n4.程序\n\n4.1人员岗位要求\n\n4.1.1实验室主任\n\n（1）任职条件：由公司股东大会任命。\n\n（2）岗位职责\n\na.对公正性做出承诺；\n\nb.实行实验室主任负责制，全权负责各项工作及资源调配，确保管理体系所需的资源；\n\nc.贯彻执行党和国家的路线、方针和政策、法律、法规和规程；\n\nd.负责组织建立、实施和维持与检测公司活动范围相适应的管理体系，并确保其持续适应、有效，提供管理体系运行的必备资源，使得管理体系实现预期结人员管理程序\n\n果；\n\ne.主持制订质量方针和目标，批准颁布质量手册和程序文件；\n\nf.组织管理体系的管理评审工作，保证检测工作的科学、公正、准确；\n\ng.做好日常思想教育工作，组织公司开展文明检测活动，严格执行安全制度和安全操作规程，并对执行情况进行监督检查；\n\nh.有人事任免权，对检测人员有奖励和处罚权，对人员、资金和资源有调配权。\n\nI.实验室主任为合同的批准人\n\n4.1.2技术负责人\n\n（1）任职条件\n\na.大专及以上学历（珠宝鉴定或相关专业毕业），具有中级及以上技术职称或同等能力。\n\n注：以下情况可视为同等能力：博士研究生毕业，从事相关专业检测活动1年及以上；硕士研究生毕业，从事相关专业检测活动3年及以上；大学本科毕业，从事相关专业检测活动5年及以上；大学专科毕业，从事相关专业检测活动8年及以上。\n\nb.熟悉本公司管理体系要求，有丰富的专业技术工作经验和管理经验；\n\nc.应熟悉和所承担项目有关的法律法规和相关技术标准、检测方法原理，掌握检测操作技能、标准操作程序、质量控制要求、实验室安全与防护知识、计量和数据处理知识等；\n\nd.熟悉本公司的检测业务，具有较强的组织协调能力，能组织本公司或本专业的技术活动，能胜任对技术运作过程进行控制和全面负责的管理职责。\n\n（2）岗位职责\n\na．负责贯彻执行国家和行业主管发布的各种技术标准、法规、规范，及时跟踪有关新规范、新标准，负责各种新规范、新标准、新方法的宣贯工作；\n\nb．确保检测数据及结果满足相关法律法规要求和客户要求；\n\nc．组织职工参加想关业务的学习和培训，吸收新技术、新方法，不断提高检测人员的自身素质，以保证检测质量；\n\nd．审核重点检测任务的检测方案和技术报告；\n\ne．对技术人员的配备考核、聘任、晋级和评定职称提出建议；\n\nf．参与质量手册、程序文件的编制和修订，审批作业指导书；\n\ng．负责领导处理检测技术事故，核批、签发测试检验报告和重要仲裁检测报告；\n\nh．检查检测过程中质量手册的执行情况，督促技术资料档案管理；\n\ni．及时发现和识别不符合项，督促责任部门（人）制定纠正／预防措施；\n\nk．对纠正、预防措施的完成情况和效果进行评价，为管理体系改进提出意见；\n\nl．运用过程方法建立管理体系和分析风险、机遇。\n\nm．负责实验室仪器设备、检测所需物品的采购\n\nn．组织合同评审，并形成书面记录。\n\n4.1.3质量负责人\n\n（1）任职条件\n\na.具有大专及以上学历；\n\nb.理解并掌握RB/T 214和管理体系的要求，熟悉本公司的管理体系文件；\n\nc.能与机构决定政策和资源的管理层直接接触和沟通。\n\n（2）岗位职责\n\na．负责全公司质量保证体系工作，对检测质量进行全面的监督和检查。确保管理体系实现其预期结果；\n\nb．组织检测人员学习各种技术法规，进一步提高检测技能，确保管理体系要求融入检验检测的全过程；\n\nc．组织、参与质量手册、程序文件的编制和修订；\n\nd．负责处理各检测组提出的检测实施过程中的各种疑议；\n\ne．调查用户投诉，提出处理意见，会同公司综合办公室组织实施解决办法；\n\nf．按客户要求完成约定和承诺的检测工作，保证优质高效的为用户服务，提升客户满意度；\n\ng．随时向公司领导报告检测质量的状况，并对玩忽职守的检测人员提出处理意见；\n\nh．负责制定内审计划，主持和实施内部审核；\n\ni．每年总结一次全公司质量工作情况，书面向公司领导报告，并提出次年质量工作计划；\n\nj．及时发现和识别不符合项，督促责任部门（人）制定纠正／预防措施；\n\nk．对纠正／预防措施的完成情况和效果进行评价，为管理体系改进提出意见。\n\n4.1.4授权签字人\n\n（1）任职条件\n\n具有大专及以上学历（珠宝鉴定或相关专业）、具有中级及以上技术职称或同等能力（同等能力同技术负责人要求）；掌握的质量管理程序、签字领域的标准和方法、报告签发程序；对检测结果的有正确的判断力；熟悉计量认证准则和相关的法律法规.并经资质认定部门批准。\n\n（2）岗位职责\n\na．负责对报告格式的正确性进行审核；\n\nb．审核检测项目的关键过程；\n\nc．对检验、检测结果的完整性、合理性和正确性进行审核；\n\nd．对报告的完整性、结论进行审核；\n\ne．只能签发授权范围内的检测报告；\n\nf．不接受来自任何方面和明示和暗示，有权拒签虚假报告；对所签发报告的结人员管理程序\n\n论负责。\n\ng.非授权签字人不得签发检验检测报告或证书。\n\n4.1.5检测室主任\n\n（1）任职条件\n\n具有大专及以上学历（珠宝鉴定或相关专业）、精通本专业检测业务和技术、熟悉业务管理、了解相关法律法规的人员担任。有相关管理经验。\n\n（2）岗位职责\n\na．贯彻执行国家相关的质量、计量、检测法律法规和公司管理体系文件，确保所在检测室能按公司管理体系有效运行。\n\nb．及时地保质保量地完成各项检测任务，认真做好原始检测记录，出具正确的检测报告；\n\nc．负责维护和保养本部的仪器设备，按照公司年度的“期间核查计划”实施仪器设备的期间核查，保证其始终处于受控状态；\n\nd．负责检测的原始记录、仪器设备使用记录的整理和保管；\n\ne．负责检测过程中的样品的管理；\n\nf．积极参加公司安排的检测室间的能力验证；\n\ng．负责本部仪器设备和消耗材料购置计划的制定及验收；\n\nh．负责编制本部相关的作业指导书；\n\ni.开发、修改、验证和确认方法。\n\n4.1.6 检测人员\n\n（1）任职条件\n\na. 具有大专及以上学历（珠宝鉴定或相关专业），经过检测技术培训和考核，有2年及以上相关检测经验，能独立承担检测任务；\n\nb．熟悉与检测活动有关的仪器设备，并且能熟练操作,熟悉相关的技术标准。\n\n（2）岗位职责\n\na．严格遵守国家、行业和地方标准、规范和规程，执行《作业指导书》，确保测试检验数据的科学性、可靠性和公正性；\n\nb．要熟悉检测业务和有关标准、试验方法，正确制定与执行检测方案，保证检测数据准确可靠；\n\nc．检测工作中要公正无私，并实事求是认真做好原始记录，不得弄虚作假和马虎从事。检测试验完毕后，要严格按试验方法和规范程序进行检测数据整理，认真准确填写检测报告，并签名以示负责；\n\nd．检测人员在检测过程中，要坚守岗位，不得擅离职守。凡因责任心不强造成责任事故的，要根据情节严肃处理；\n\ne．参与审核日常检测试验报告，保证日常检测试验质量；\n\nf．精心测试检测工作，并做好事故和失误的防范工作；\n\ng．检测人员要保养、维护好仪器设备和工具，熟悉操作规程，保持试验环境和设备仪器整洁；\n\nh．及时向公司领导报告试验和设备事故，并参与处理检测技术事故；\n\ni．注意收集科技发展信息，注意检测技术和手段更新；\n\nj．积极参与岗位培训和有关法律、法规和新的检测规范、标准的学习。\n\n4.1.7内审员\n\n（1）任职条件\n\n具大专及以上学历，必须由经过管理体系相关知识培训取得资格证书和实验室主任授权；熟悉工作程序和管理体系的要求，有能力判定管理体系各环节是否达到规定要求。\n\n（2）岗位职责\n\na．监督管理体系的运行，对体系的保证和运行起参谋作用；\n\nb．在本公司外部审核中担任联络员；\n\nc．带头实施管理体系，在管理体系中成为沟通领导与群众的渠道和纽带；\n\nd．在审核中坚持原则，善于沟通，确保审核的独立、客观、公正和有效性，认真完成审核任务，负责编制、填写、收集和提交内部审核记录；\n\ne．负责对内审所发现的问题的纠正进行跟踪、验证；\n\nf．参与本公司管理评审工作，为管理评审提供依据。\n\n4.1.8监督员\n\n（1）任职条件\n\n具大专及以上学历，从本专业技术工作5年以上；由经过管理体系相关知识培训取得资格证书，经实验室主任授权；熟悉标准和方法，了解检测过程和检测目的，懂得评价检测结果。\n\n（2）岗位职责\n\na．负责监督检测人员是否按相应的技术标准、规范或《作业指导书》进行检测。\n\nb．负责对检测过程进行连续的监督，核查检测结果；\n\nc．记录观察到的问题，有权要求当事人返工、改正或中止检测；\n\nd．督促相关人员解决发现的问题、验证问题解决的结果；\n\ne．负责本检测室的安全生产和消防工作。\n\n4.1.9资料管理员\n\n（1）任职条件\n\n专科及以上学历，具有基本的文件、档案管理知识。\n\n（2）岗位职责\n\na．应维护标准、规程、资料和原始记录、检测报告副本的完整、系统、准确，人员管理程序\n\n充分发挥资料档案的作用；\n\nb．各项技术资料、档案应认真填写，整理齐全，立卷成册，妥善保管，做到\n\n不漏项、不遗失、规范化、标准化；\n\nc．资料整理完毕，应由质量负责人审查，技术负责人签署意见后，由资料员验收保管。移交人和验收人均应签名；\n\nd．对用户的技术资料和检测检验数据要严格保密，做好防盗、防火、防虫、防尘、防潮等安全工作，对被损或变质的资料要及时修补和复制；\n\ne．对新购的标准、规程要及进整理、编目、入柜，认真做好保管借阅，做到存放有序，提供准确；\n\nf．公司内人员借阅资料，必须登记，经技术负责人同意后，方可借出；\n\ng．资料借出后，应按时完整，归还。如需延期应办理延期手续，退还档案时，应如数清点页码；\n\nh．需销毁的案卷资料，应登记造册，经公司技术负责人签字，实验室主任批准后，方可销毁；\n\ni．认真执行《文件管理控制程序》努力学习档案法规和科技知识，不断提高业务水平。\n\n4.1.10 设备管理员\n\n（1）任职条件\n\n专科及以上学历，熟悉检测活动相关的仪器设备的性能、用途和使用情况，了解仪器设备的日常维护要求。\n\n（2）岗位职责\n\na．积极宣传、贯彻执行国家计量法规，提高全公司人员的计量意识，负责量值溯源（传递）工作；\n\nb．建立仪器设备台帐，制定仪器设备周期检定计划；\n\nc．根据质量负责人制订的期间核查计划拟定期间核查方案，协助检测室间的\n\n能力验证的实施；\n\nd．督促落实周期检定计划，保证计量器具的周检率、周检合格率、完好率达到要求；\n\ne．收集整理仪器设备检定证书，保证所有的仪器设备都在检定周期内；\n\nf．制止使用不合格或超检定周期的仪器设备的使用，对违反计量法和设备维护程序的人员及时纠正并提出批评和整改意见。\n\ng．检查仪器设备使用及维护情况及其记录。\n\n4.1.11 样品管理员\n\n（1）任职条件\n\n专科及以上学历，了解样品的特性和业务受理流程。\n\n（2）岗位职责\n\na.样品管理员收到样品后按照样品的编号(型号、规格)进行分类存放，存放的环境应符合相关规定（标准）的规定，并将符合要求的\n\n送检样品及时送到相应检测岗位，做好样品交接记录；\n\nb.样品管理员对其管理的样品的质量负责，确保样品有序放置。定时检查，以保证样品的保存期内的有效性，样品异常时应及时向综合办公室负责人报告；\n\nc.负责管理工作场所，严禁送检人员和其他岗位工作人员进入工作人员区域，对样品的保密负责，维护接样大厅的良好次序和环境。\n\n4.1.12 样品接收人员\n\n（1）任职条件\n\na.工作细致、认真、负责；\n\nb.了解样品管理方面的知识；\n\nc.熟悉公司管理体系文件；\n\nd.了解检测方法。\n\n（2）岗位职责\n\na.检查委托检测样品是否符合检测要求；\n\nb.严格执行《质量手册》和《程序文件》中规定的样品交接制度；\n\nc.指导送样者认真阅读样品委托合同书及填写送样检测委托单；进行样品唯一性编号及登记工作；\n\nd.注明证书种类、收费标准；\n\ne.认真执行与样品保管员的交接手续；\n\nf.取样人在取样品和证书时，验明证件，办理好样品交接及收款手续。\n\n4.1.13 安全员\n\n（1）任职条件\n\na.工作细致、认真、负责；\n\nb.了解保安方面的知识；\n\nc.熟悉公司管理体系文件；\n\nd.了解检测方法。\n\n（2）岗位职责\n\n在质量负责人的管理下，做好以下工作：\n\na.负责公司整体的安全工作，包括防火、防盗、危险品的防护；\n\nb.负责联系本公司所在区域的保安系统，做好中心防盗保安系统的日常维护与安全检查；\n\nc.负责发生危险事故时的处理。\n\n4.1.14 检测复检人员\n\n（1）任职条件\n\n相关专业检验检测活动5年以上）或大专毕业（从事相关专业检验检测活动8年以上）以上或中级以上职称。\n\nb.有从事宝玉石检测工作的长期经历及丰富实践经验。\n\nc.十分熟悉宝玉石的鉴定特征，检测仪器使用原理、使用方法及有关维护保养及定期校准的规定，并掌握校准状态。\n\nd.十分熟悉宝玉石检测技术国家标准和检测方法。\n\ne.遵纪守法，能严把质量关，实事求是，客观公正对结果有最终评价的能力。\n\nf.十分熟悉记录、报告、证书及核查程序。\n\n（2）岗位职责\n\na.熟练掌握珠宝玉石检测的标准、鉴定特征及有关检测方法，是本检测中心授权签字人；\n\nb.对检测仪器的性能十分熟悉；\n\nc.严格执行本检测中心《质量手册》，严把质量关；\n\nd.对检测人员所鉴定的宝玉石样品，逐一进行认真检查，并核查有关原始记录，进行签字。\n\n4.1.15意见解释人\n\n（1）任职条件：\n\n应具有中级及以上相关专业技术职称或同等能力\n\na.3年以上珠宝玉石检测工作经历；\n\nb.熟悉检测业务、检测方法、检测程序、检测结果的应用；\n\nc.熟悉相关的法律、法规和标准。\n\n（2）工作职责：\n\na.负责公司检测报告的意见和解释；\n\nb.负责对客户的疑议进行意见和解释；\n\nc.对意见和解释准确性负责；\n\nd.负责填写意见和解释记录。\n\n4.2授权\n\n公司对以下专门人员进行授权：检测人员、批准发布检测报告人员、提出意见和解释人员、操作特殊类型设备人员、内审员、监督员（见公司有关人员任命及授权文件）。\n\n4.3人员技术档案\n\n所有人员的资格证书、培训结业证书、技能考级证书、授权书、任命书等资料由办公室收集、整理、复印存入公司档案。\n\n4.4试用期、见习期检测人员上岗前由办公室组织拟使用实验室对其培训，合格后上岗，并由质量负责人安排质量监督员或相应人员对其进行适当的跟踪和\n\n监督，以确保检测工作质量。\n\n4.5从事特定岗位人员，需持不同规定的资格证书（如法定的、特殊技术领域的等），办公室列入人员培训计划，确保其持证上岗。\n',140,'现用文件/程序文件/程序文件2022/01-02-2022人员管理程序.docx#职责','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('4eacc076-7e2b-41d0-8c24-93e38babe439','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:8_2','8.2','管理体系的运行','section','## 8.2 管理体系的运行\n\n8.2.1 管理层责任\n\n本公司管理层为管理体系的运行提供资源保障，为定期的内部审核活动提供支持，确保内部审核工作全面顺利进行，以便定期检查管理体系的运行情况和运行质量，定期主持管理评审会议，全面评价管理体系的运行情况和检测活动的现状，寻求改进的机会实施改进，安排检测室定期开展质量控制活动，进行内部人员比对、结果报告和质量核查评比等活动。确保质量控制水平不断提高，定期参加认可委颁布的能力验证活动，不断检查本公司的技术能力水平，根据本公司业务的发展情况，不断充实提高技术能力资源，引进人才和先进设备，确保本公司技术能力不断提高，更好地服务于公司的工作。\n\n8.2.2 本公司的管理体系文件的贯彻由质量负责人负责，并监督管理体系文件的执行情况，对执行中出现的问题和违反文件规定的行为给予及时解决和纠正。\n\n8.2.3 为使过程受控，将有关政策、制度、计划、程序和作业指导书等制定成文件，形成管理体系文件，对有关岗位人员进行培训，使其理解并有效执行，以达到确保检测结果质量的目的，让各岗位人员方便地取得并有效地使用管理体系文件。\n\n8.2.4 为了使管理体系正常运行和保持其有效性，满足《检验检测机构资质认定评审准则》（2023年版）中对质量管理和技术要求的规定，本公司设置了质量负责人、技术负责人，设置管理体系岗位和关键技术岗位，对各岗位人员的作用和职责做了明确规定。\n\n8.2.5 服务承诺\n\n8.2.5.1 实验室主任通过以下活动对其建立和改进管理体系的承诺提供证据：\n\n通过实验室主任的公正性声明、员工职业道德规范以及宣传教育等措施确保公司及其人员工作的独立性、公正性、诚信度，不利用职权和检测业务上的便利谋取不正当的利益，不参与社会上有可能损害独立性和诚信度的活动，不受任何对工作质量有影响的不正当的来自内外部的行政、商业、财务等方面的压力和干扰，防止任何商业贿赂行为；\n\n有保护客户的机密信息（包括国家秘密、商业秘密、技术秘密）和所有权的政策和程序；\n\n本公司组织机构框图表明了各部门、各岗位设置以及领导关系、业务联系在组织中的地位；\n\n实验室主任全面负责公司的工作。技术负责人、质量负责人、部门负责人由公司实验室主任任命；\n\n规定了所有管理、操作和核查人员的职责、权利和相互关系；\n\n授权熟悉各项检测方法、程序、目的和结果评价的人员担任监督员，在检测的各个关键环节，对检测人员包括在培员工、签约员工进行适当的监督。\n\n任命一名技术负责人全面负责技术运作和确保检验检测所需资源；任命一名质量负责人，确保管理体系的实施和运行以及管理体系文件的现行有效性；\n\n技术负责人和质量负责人有一方不在岗位时由相关代理人代理其任务和职责；\n\n通过岗位培训和宣传教育使本公司人员理解其活动的相互关系和重要性，以及如何为管理体系质量目标的实现作出贡献；\n\n定期对管理体系进行评审，确保管理体系适应性、充分性和有效性，确保该体系在本公司的持续改进和有效运行。\n\n8.2.5.2 公司的职责是按《检验检测机构资质认定评审准则》（2023年版）从事检测工作，并满足客户要求、政府要求和认可机构要求，遵循客观独立、公平公正、诚实信用原则，恪守职业道德，承担社会责任，具体规定如下：\n\n严禁以检验检测活动、数据和结果谋取不正当利益，确保检验检测活动的公平公正；\n\n严禁参与任何对检验检测结果和数据的判断产生不良影响的商业或技术活动，确保检验检测的客观独立和数据、结果的正确可靠；\n\n严禁从事与客户利益有竞争的产品的设计、研制、生产、供应、安装、使用或维护的活动，确保诚实守信地开展检验检测活动；\n\n承诺无条件接受CNAS安排的专项监督，并配合CNAS委托的无利益冲突的第三方行业权威技术机构的协助检查；\n\n当发生实验室名称、地址、法定代表人、最高管理者、授权签字人变更，或受到行政/刑事处罚时，必须在20个工作日内向CNAS提交书面通报；\n\n对于日常不常开展或因设备/人员变动已不具备的检测能力（如某些特定的珠宝玉石鉴定子项），实验室有义务及时主动申请缩小认可范围；\n\n一旦被撤销或注销认可资格，必须立即交回认可证书，并全面停止在任何报告或宣传材料上使用认可标识。\n\n8.2.6 对管理体系的过程进行更改时，实验室主任应对此而导致的其他过程的变化做出判定，并采取适当的措施，确保体系运行的连续性和完整性。\n\n8.2.7 重要性传达\n\n实验室主任根据法律法规文件及认可准则的要求和公司下发的各类批示文件精神，将检测工作需要满足的各种法定要求通过各种方式向员工传达，确保检测工作始终满足《检验检测机构资质认定评审准则》（2023年版）中对质量管理和技术要求的规定和要求；同时，强调服务客户工作的重要性，传达方式主要包括书面通知、网络通知、办公会议、公告、座谈等，通过这些方式的沟通确保满足法定要求和客户要求的重要性得到深入贯彻执行。\n',830,'现用文件/质量手册（第四版）.docx#8.2','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('4f688e27-673e-4511-972a-1039aa62d543','00000000-0000-0000-0000-000000000001','f0487552-998f-4890-94df-49779d41b185','48e77eb2-f569-435f-b92e-7a4a99351f71',NULL,'procedure:xztc_cx_20_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《不符合检测工作管理程序》 XZTC/CX-15-2022\n\n《实施纠正措施程序》 XZTC/CX-16-2022\n《实施预防措施程序》 XZTC/CX-17-2022\n\n《内部管理体系审核程序》 XZTC/CX-21-2022\n',160,'现用文件/程序文件/程序文件2022/20-2022内部管理体系审核程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('51b0438b-ba2a-44d6-9289-24d0e1d081eb','00000000-0000-0000-0000-000000000001','9f720d1f-600b-423a-8082-f8987b0594cf','3a8d9ea2-2b78-4dc0-a1e8-164f02246028',NULL,'procedure:xztc_cx_06_2022:element:confidentiality','','要素落实：保密性','control_requirement','### 要素落实：保密性\n\n- 程序文件：XZTC/CX-06-2022 保护客户机密信息程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('53d34a08-1050-451e-baae-1ebef9097f1c','00000000-0000-0000-0000-000000000001','1917466d-93d3-4089-9509-3c8928052166','41376c7d-5629-443e-92be-2c8727f1036e',NULL,'procedure:xztc_cx_03_02_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1参考标准和标准物质的选用与购置\n\n4.1.1我公司所用参考标准与标准物质应优先选用由国家级机构提供的合适的有证标准物质或国际级机构提供的合适的有证标准物质。由其它制造商提供的有证标准物质或无证标准物质，在使用前则需要验证。\n\n4.1.2各实验室应根据需要拟订本室的参考标准和标准物质的购置计划，填写购置表，并提前汇总，报技术负责人审核，并由实验室主任批准，由检测室负责实施。\n\n4.1.3实验室根据审核批准意见拟订购置计划，并负责实施。\n\n4.2参考标准和标准物质的验收与验证\n\n4.2.1参考标准和标准物质到货后由实验室会同相关技术人员及供货方进行验收。\n\n4.2.2有证标准物质验收内容包括：包装和证书情况；证书中基本信息标准物质名称及编号，研制和生产单位名称。\n\n4.2.3无证标准物质（含非国家级机构或国际级机构提供的，由其他制造商提供的有证标准物质）的验收内容与4.2.2相同，且需进行验证，验证应使用以下五种方法中的一种，或是其中几种方法的组合：\n\n⑴使用其他已知的参考标准或标准物质进行校准；\n\n⑵与其他方法所得的结果进行比较；\n\n⑶与其他检测实验室进行比较；\n\n⑷对影响结果的因素作系统性的评审；\n\n⑸对所得结果不确定度进行评估。\n\n4.2.3.1验证过程所得到测量值的范围和准确度记录应包含以下信息：\n\n⑴测量结果的不确定度：\n\n⑵检出限；\n\n⑶方法的选择。\n\n4.2.4属应检定/校准的参考标准和标准物质先由统一计划，送计量检定部门或组织有关技术人员校验。\n\n4.2.5实验室负责人验收合格后，填写验收记录，并列入试验消耗登记台帐。\n\n4.2.6验收发现有质量问题，由实验室负责人负责在有效期内联系退货及办理索赔事宜。\n\n4.3参考标准和标准物质的存储，使用和维护。\n\n4.3.1参考标准和标准物质实行专人负责管理，由实验室确定保管人，具体负责其使用和日常管理工作。\n\n4.3.2参考标准和标准物质的资料，由管理组收集，建档，保管。\n\n4.3.3使用人员在使用参考标准和标准物质时，应认真核查其标识与性能指标，以满足检测精度要求。\n\n4.3.4实验室应根据检测标准要求，对参考标准和标准物质设立专柜贮存，保证其完整性，有效性，准确性。\n\n4.4参考标准的标识\n\n4.4.1参考标准经计量检定/校准或校验合格后，在其上面贴“合格证”。\n\n4.4.2标识的内容包括：鉴定日期、有效日期（或停用日期）、检定单位、设备编号及检定/校验员。\n\n4.4.3仪器设备保管人负责参考标准和标准物质的标识和管理。\n\n4.5参考标准和标准物质的期间核查\n\n4.5.1参考标准的期间核查时间间隔在两次检定期间至少进行一次。\n\n4.5.2参考标准只能用于检定或校准，不得将其作为计量器具使用，不应将其用于通用检测，中间应有工作计量器具作为缓冲。\n\n4.5.3参考标准和标准物质的期间核查\n\n参考标准和标准物质的期间核查是在两次校准之间进行，通常假定在2/3间隔时间实施核查。但为了确保其量值有效，发挥其量值传递、测量溯源性作用，应规定在特定情况下对其实施核查。\n\n期间核查是有效的预防措施，可以发生在质量控制要素中的任何时间；\n\n(2)标物使用频率高；\n\n(3)标物性状不稳定；\n\n(4)标物储存环境条件发生变化时（如电磁干扰、温度、湿度、不受实验室控制后\n\n返回等）；\n\n(5)怀疑标物受污染时；\n\n(6)检测项目争议大，结果受质疑时；\n\n(7)临近失效或以过使用有效期仍将使用的标物。\n\n4.5.3.1参考标准和标准物质期间核查的内容\n\n(1)是否在其有效期内；\n\n(2)储存条件和环境要求是否满足（与说明书要求一致）；\n\n(3)核查其外观（其颜色、性状等）是否发生变化；\n\n(4)是否按照该标准物质证书上所规定的适用范围、使用说明、测量方法与操作步骤使用；\n\n标物的特征量值重新验证，证实其是否保持校准状态的置信度。\n\n对于稳定的标准物质如：重铬酸钾、苯钾酸、苯基丙铵酸、钝锌、钝铅等，通常只需对其进行1234方面的核查。\n',150,'现用文件/程序文件/程序文件2022/03-02-2022标准物质管理程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('53fa6861-e0d5-47f0-b549-370d17122562','00000000-0000-0000-0000-000000000001','4573b997-12b2-4cd2-8689-6590c02ae7b7','f381721c-0f02-476f-b688-9bb0ebefb96e',NULL,'procedure:xztc_cx_27_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 技术负责人应：\n\n3.1.1 根据检测项目的特点识别并提出评审要求，组织评定和评定结果的审核工作。\n\n3.1.2 组织测量不确定度的验证。\n\n3.1.3 批准对外公布实验室能力时的测量不确定度指标。\n\n3.1.4 根据各检测项目的特点识别评定要素。\n3.1.5 组织需要评定的检测项目编写“测量不确定度评定与表示”报告。\n\n3.1.6 会同监督员对本部门的评定报告和使用进行审核。\n\n3.2 检测项目的负责人应：\n\n3.2.1 学习和掌握“测量不确定度的评定与表示”的基础知识和方法。\n\n3.2.2 编写本项目测量不确定度的评定报告。\n\n3.2.3 及时发现和反馈会导致测量不确定度发生较大变化的信息。\n',140,'现用文件/程序文件/程序文件2022/27-2022测量不确定度的评审控制程序.docx#职责','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('544233ca-158f-44db-9712-8ef976d08165','00000000-0000-0000-0000-000000000001','9f907214-fdff-400d-bd65-a376c631c875','619a08d7-264c-4a61-82aa-35e13cfa6e5d',NULL,'procedure:xztc_cx_07_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 为维护客户合法权益，保护客户对本公司的良好信心，实验室主任颁布了《公\n\n正性声明》，表明本公司不从事任何可能影响判断独立性和工作诚实性的活动，（详见《质量手册》）。本公司制定并发布了《员工行为准则》（详见《质量手册》），规定了对员工遵守法律、法规，抵制干扰、秉公办事，保护客户所有权和机密信息，保证数据的真实性和判断的独立性的要求，《员工行为准则》\n\n的控制实施，确保公正性、诚实性的实现。本公司质量方针、质量目标中明确提出了公正性和诚实性的要求，全面贯彻和落实本公司质量方针、目标，将确保公正性、诚实性控制的实现。本公司向社会、客户做出的服务承诺，包括了公正性、诚实性的承诺，接受客户的监督，保证控制要求的实现（详见《质量手册》）。\n\n4.2 自律、公正行为和诚实性的贯彻\n\n4.2.1 本公司将自律、公正行为准则、诚实性和质量方针作为全体员工的培训课程，对全体员工进行培训。\n\n4.2.2 全体员工应熟悉、理解和自觉遵守本公司的自律、公正行为和诚实性准则、质量方针，执行中如发现需要改进、提高和补充内容，可以及时向实验室主任报告，并提出合理的修订、补充建议。\n\n4.2.3 落实管理职责，明确授权签字人的职责范围，保证出具的检验报告和结果的一致性准确、科学和公正反映被检产品的实际质量。\n\n4.2.4 设置足够的监督员，发挥其质量监督作用，对检验过程实施全过程的监督，形成有效的监督机制，保证公正性的实现。\n\n4.2.5公司所有人员在检测工作中应遵守以下规定：\n\n⑴与项目无关的人员不得参与该项目的检测工作；\n\n⑵抽样应安排两人进行，现场检测应至少有两名检测人员参加；\n\n⑶样品接收人员不得将委托书传入检测室，以确保数据结果的公正性；\n\n⑷不得向非委托方提供检测项目的进展情况、检测结果等信息；\n\n⑸未经实验室主任批准，不得带外单位的人员（包括委托方）观看检测过程和查阅检测资料；\n\n⑹进入司法和仲裁程序的样品，公司只与司法和仲裁部门联系，不与当事人发生任何联系，也不接受收当事人提供的任何资料；\n\n⑺由双方单位共同委托的样品，任何一方提出更换样品时，必须由委托各方共同办理相关手续。\n\n4.3 监督检查\n\n4.3.1管理层应识别对检验工作的公正性风险，并进行分析、评估、控制。\n\n4.3.2管理层在制定年度计划和下达创收指标时应统一认识明确在检测能力许可范围内和确保检测质量前提下完成创收任务，严禁以数量压质量。\n\n4.3.3 监督员应组织对本公司自律、公正行为和诚实性准则、质量方针的执行情况进行不定期的检查，并填写《检测公正性检查记录表》。\n\n4.3.4 检查中发现员工存在理解、掌握问题时，应组织培训。\n\n4.3.5 检查中发现员工有意违背自律、公正行为和诚实性准则、质量方针，监督员应报告技术负责人和实验室主任，对其培训教育、批评帮助、警告或其他行政、司法处理。\n\n4.3.6 对自觉遵守维护本公司自律、公正行为和诚实性准则、质量方针且能够提出合理建议的，应予以表扬和奖励。\n\n4.3.7 对来自其他部门的不正当干预，管理层应按照公正性声明的要求予以抵制，必要时管理层应研究对策以集体名义予以抵制。\n\n4.3.8检测室出具给客户的检测数据和结果应从制度上保证不是个人行为结果，技术负责人和各检测人员、监督员应确保检测、校核、审批三级签字确认制度落实到实处。\n\n4.3.9 样品管理员和检测报告的发放人员应坚持原则忠于职守，把好检测样品接收关，防止客户和检测人员在无监督条件下直接发生业务往来。\n\n4.3.10诚实是公正的前提，检测室负责人和监督员应坚持原则不接受检测能力许可范围以外的检测任务，对于设备和环境条件不能完全满足要求的检测活动以及对检测方法有效性没有把握的检测工作应如实告之客户。\n\n4.3.11公司所有人员均有权监督制止违反公司公正性声明和诚信承诺的人和事，必要时应及时向有关负责人报告。\n\n4.3.12内审和管理评审应把公正性声明和公正性承诺及措施的落实情况作为审核和评审内容，质量负责人应跟踪与此相应的纠正和预防措施落实情况。\n\n4.4 奖惩措施\n\n4.4.1实验室主任对自觉维护公司信誉，坚持原则，忠于职守，维护检测工作诚确保公正性程序\n\n实性和公正性声明从而避免公司信誉受到伤害的人和事给予表扬和奖励。\n\n4.4.2对违反本程序第4.2条规定的行为，由公司实验室主任组织人员进行调查，视情节严重程度和造成的影响大小给予批评教育、警告直至辞退的处分。\n\n4.4.3当内审和管理评审发现对公正性存在理解、掌握和执行的问题时，实验室主任应组织专题研究并组织一定范围内的直至全体员工的培训，以期统一认识，统一行动。\n\n4.5检验能力的维护\n\n4.5.1 实验室主任应经常听取技术负责人关于本公司技术资源配置和检验能力的情况，并对存在的问题和纠正、改进的措施提出要求。\n\n4.5.2 对技术资源配置和检验能力中存在的问题，实验室主任应给予积极协调和\n\n解决，对纠正和改进计划和活动中出现的延迟给予积极负责的解决。\n\n4.4.3 实验室主任应充分重视能力验证、实验室间比对计划，将该项工作的计划和实施列入本年度的重点工作计划，并力争始终保持满意的程度。\n\n4.4.4 实验室主任应经常召集技术负责人，质量负责人和各部门负责人研究管理\n\n体系内部审核和评审的情况，推进管理体系运行的水平，始终保持管理体 系的符合性、有效性和适应性。\n\n4.5 检验能力的提高\n\n4.5.1 实验室主任应了解本公司的检测要求，了解国家法律法规对本公司的强制、推荐性技术和标准的要求，确定本公司的发展方向并策划本公司的发展计划。\n\n4.5.2 实验室主任应经常听取、了解有关客户利益的要求，从而分析本公司可能涉及到的法律责任和后果，及时采取积极的化解、预防和改进措施，防止酿成不良的责任和后果。\n\n4.5.3 技术负责人应经常向实验室主任报告管理体系运行中存在的技术问题，并将本公司的发展策划转变为实施计划。\n\n4.5.4 质量负责人应经常保持与实验室主任的沟通，负责跟踪国际实验室认可标准和中国合格评定国家认可委员会的认可要求，及时反映管理体系建设和运行中存在是实际问题，积极协助实验室主任维护本公司管理体系的完整性、符合性、有效性和适应性。\n\n5.相关程序\n\n《保护客户机密信息程序》 XZTC/CX-06-2022\n\n《实施纠正措施程序》 XZTC/CX-16-2022\n\n《实施预防措施程序》 XZTC/CX-17-2022\n\n《内部管理体系审核程序》 XZTC/CX-20-2022\n\n《管理评审程序》 XZTC/CX-21-2022\n',150,'现用文件/程序文件/程序文件2022/07-2022确保公正性程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('5730c907-6234-4dd4-886b-22dab4e1c171','00000000-0000-0000-0000-000000000001','684b63da-4e5d-4436-bd6f-95cd011fd70d','bbf06eea-34a2-451e-9ac6-88cf92290425',NULL,'procedure:xztc_cx_01_02_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《记录管理程序》 XZTC/CX-19-2022\n',160,'现用文件/程序文件/程序文件2022/01-02-2022人员管理程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('573fa3d3-2264-41b0-82db-c6f8e312c9fc','00000000-0000-0000-0000-000000000001','dc7146d9-e84c-407e-8e35-2515e05d7642','3b870297-530f-4b96-a1fd-83e397708084',NULL,'procedure:xztc_cx_05_2022:element:metrological_traceability','','要素落实：计量溯源性','control_requirement','### 要素落实：计量溯源性\n\n- 程序文件：XZTC/CX-05-2022 实现测量可溯源程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('576d486e-cca5-452a-b850-34c894409f47','00000000-0000-0000-0000-000000000001','25bc5721-9452-4aa9-a626-0262a1bb1ee4','36ac3d04-2b8c-435e-a334-26a97ebfa4ad',NULL,'procedure:xztc_cx_03_2022:overview','','仪器设备管理程序','section','# XZTC/CX-03-2022 仪器设备管理程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/03-2022仪器设备管理程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/03-2022仪器设备管理程序.docx','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('57b9b287-d4cc-4af4-a3fb-21fc815c239b','00000000-0000-0000-0000-000000000001','ddbdafda-6b10-4c15-bd38-6c64672f57d1','4b70f485-3633-4627-be9b-28114a44e2a7',NULL,'procedure:xztc_cx_22_2022:overview','','检测方法的选择与确认程序','section','# XZTC/CX-22-2022 检测方法的选择与确认程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/22-2022检测方法的选择与确认程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/22-2022检测方法的选择与确认程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('57efc885-1097-4a85-bb21-2f76de0132af','00000000-0000-0000-0000-000000000001','ddbdafda-6b10-4c15-bd38-6c64672f57d1','4b70f485-3633-4627-be9b-28114a44e2a7',NULL,'procedure:xztc_cx_22_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 总则\n\n4.1.1 本公司对检测工作涉及的各环节和过程包括检测、数据处理和测量不确定度评定等，分别制定程序文件和作业指导书。\n\n4.1.2 技术负责人按质量管理体系要求组织相应的作业指导书，包括仪器设备操作规范、检测方法实施细则等。\n\n4.1.3 保证检测所需技术文件如标准、操作规程及其他的应用技术文件的受控状态，保持其现行有效版本，并便于相关人员取阅使用。\n\n4.1.4 对检测方法的偏离，仅在该偏离已被有关文件明确规定，经技术判断、授权和客户同意情况下允许发生，否则按不符合的检测工作进行控制。\n\n4.1.5 国家或行业、地方标准可直接引用，不必增补或改写为内部文件，如有必要，可对方法中的步骤进行选择，制定补充或附加说明文件。\n\n4.1.6 对于《检测和校准实验室能力认可准则在贵金属、珠宝检测领域的应用说明》（CNAS-CL24:2006)的要求编制作业指导书。\n\n4.2 方法的选择\n\n4.2.1 公司应采用满足客户需要并适用于所进行的检测的方法，且应优先使用以国际、区域或国家标准颁布的方法并确保所用标准为最新有效版本。技术负责人负责组织标准方法的查新，可通过标准化研究所或标准网站进行查新。\n\n4.2.2 实验室在引入方法前，应验证该方法是否能够正确地运用，以确保实现所需方法的性能和数据的有效性。\n\n4.2.3 当客户未指定所用方法时，公司应选择由国际、区域或行业标准发布的，或由知名的组织或有关科学书籍期刊发布的，或由设备制造商制定的方法。\n\n4.2.4 公司制定的或采用的方法如能满足检测的预期用途并经过验证确认后，也可使用。所选用的方法应通知客户。当认为客户提出的方法不合适或已过期时，公司应通知客户。\n\n4.3 方法的制定\n\n4.3.1 方法的制定由技术负责人指定具有足够资源的有资格的人员进行。\n\n4.3.2 新的检测方法，在进行检测之前需详细描述下述信息：\n\n4.3.2.1 适当的识别；\n',150,'现用文件/程序文件/程序文件2022/22-2022检测方法的选择与确认程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('580443ea-d35a-4be1-9fc3-25a5f4d6859f','00000000-0000-0000-0000-000000000001','69032715-7174-46fa-b564-18c838e80d23','1b4fd63c-d774-4713-8a57-1bcc9ea019f3',NULL,'procedure:xztc_cx_30_2022:source:purpose','','目的','purpose','### 目的\n\n通过有计划的采用必要的监控手段，科学的统计监视过程，对检测活动及结果实施质量监控，并及时排除质量环节出现的不符合的因素，以此来验证和评审检测活动的有效性和结果的准确性。以及确定本公司的检测能力或按照预定的要求，通过评审本公司的整体运作对实验室能力进行评价。采取适宜的措施控制检测质量，使本公司的检测数据具有良好的准确度和可信度。\n',120,'现用文件/程序文件/程序文件2022/30-2022检测结果质量控制及能力验证程序.docx#目的','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('585af2c2-d2f7-4bad-a7be-b438135e29f9','00000000-0000-0000-0000-000000000001','71ac64b2-e042-4afc-aacc-a1b8f9d5b18c','b61891de-34e0-475d-aa81-5f55a84285ec',NULL,'procedure:xztc_cx_04_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 负责期间核查计划、方案、作业指导书的批准。\n\n3.2 技术负责人应：\n\n3.2.1 负责审核期间核查计划、方案、作业指导书，并组织实施，组织核查不符合设备的整改活动；\n\n3.2.2 负责收集核查期间的相关文件和记录。\n\n3.3 设备管理员应：\n\n3.3.1 负责编制期间核查计划、组织方案及编制作业指导书。\n\n3.4 检测室应：\n\n3.4.1 负责实施期间核查活动。\n',140,'现用文件/程序文件/程序文件2022/04-2022仪器设备和标准物质期间核查程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('59aa9634-a102-4927-83f9-db016533a403','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_10','7.10','不符合工作','section','## 7.10 不符合工作\n\n7.10.1 不符合检测工作的控制\n\n7.10.1.1 为保证检测结果的准确性，实施对检测工作中出现的不符合进行控制，以防止非预期的检测结果出现，使不符合检测工作得到及时妥善地处理，本公司制定了《不符合检测工作管理程序》，防止不合格报告的发放或使用。\n\n7.10.1.2 本公司技术负责人、质量负责人、各部门负责人、报告的审核和批准人、监督员和内审员负责识别不符合检测工作，并规定了他们的相应的管理权限和职责。当发现不符合检测工作时，必须马上采取扣发报告、暂时停止工作等措施。\n\n7.10.1.3 对发生的不符合检测工作应根据其性质和严重程度由质量负责人作出评价，提出处理意见，对不符合的可接受程度作出决定，并明确采取纠正措施的要求。\n\n7.10.1.4 经评定暂时无法通过纠正措施恢复正常的检测活动，应决定取消相关检测工作，并及时通知客户。\n\n7.10.1.5 当责任部门对不符合检测工作采取的整改措施经验证其有效后，由质量负责人批准检测工作的恢复。\n\n7.10.1.6 经评定表明不符合检测工作对本公司的体系运行和程序的符合性产生怀疑或该不符合检测工作可能再度发生时，应制定和实施纠正措施，按《实施纠正措施程序》有关要求执行。\n\n7.10.1.7 对不符合检测工作采取的措施及过程应形成记录，并予以保存。\n\n7.10.1.8 支持性文件\n\n《不符合检测工作管理程序》 XZTC/CX-15-2018\n\n《实施纠正措施程序》 XZTC/CX-16-2018\n',800,'现用文件/质量手册（第四版）.docx#7.10','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('59ee1883-f668-4e72-a846-61235e5ccb22','00000000-0000-0000-0000-000000000001','1917466d-93d3-4089-9509-3c8928052166','41376c7d-5629-443e-92be-2c8727f1036e',NULL,'procedure:xztc_cx_03_02_2022:source:scope','','范围','scope','### 范围\n\n本程序适用于本室现用的参考标准和标准物质的购置，验收，流转，存储等控制。\n',130,'现用文件/程序文件/程序文件2022/03-02-2022标准物质管理程序.docx#范围','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('5a6e5bc5-13dd-45b7-8924-3c7dec151ebc','00000000-0000-0000-0000-000000000001','44ff5408-e03d-4859-9cd4-926a8f69fda5','948d2434-2b53-47e6-adab-cf2ee95dfc3c',NULL,'procedure:xztc_cx_09_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1在签定合同之前，要与客户进行沟通，给客户提供充分说明，充分理解客户的期望和要求，协商解决双方存在的差异。在与客户沟通时，除就一般内容进行商讨外，如果存在下列情况，需征得客户同意：\n\n⑴如果客户要求采用非标准方法或对标准方法偏离，充分讨论具体实施方案；\n\n⑵需要分包时，分包方的选择；\n\n⑶报告传送方式有特殊要求，如电话、传真、电子邮件等；\n\n⑷是否需要评定测量不确定度。\n\n4.2双方认可后，起草合同草案。\n\n4.3合同内容应包括：服务内容、检测项目、检测方法、技术规范、现场检测条件的提供与配合、时间、费用、分包、违约责任、特殊申明和特殊要求等。\n\n4.4合同书的格式可以采用本公司《检测委托单》，也可以采用双方同意的其他书面形式。\n\n4.5合同全面评审的内容：\n\n4.5.1合同草本中客户的要求是否充分明确，检测项目、参数及其他内容是否合理可行。\n\n4.5.2本公司的技术能力和资源（人力、物力、信息）是否满足要求。\n\n4.5.3检测方法是否合适。\n\n4.5.4收费是否合理，提交报告的时间是否合适。\n\n4.5.5是否需要分包，分包方是否为客户接受。\n\n4.5.6 安全和环保是否有保障。\n\n4.5.7 是否符合国家有关法律法规。\n\n4.6合同评审的方式可以采用集中会审或传阅评审。\n\n4.7通过评审的合同由双方法人代表或其授权人签字确认并生效。\n\n4.8评审的简化\n\n4.8.1对常规、重复性的检测任务，如客户要求不变，只须初次进行评审并做好记录，以后不再全面评审。\n\n4.8.2对于检测能力范围内的常规检测项目，由收样人员在接收样品时审查样品和检测项目并在委托单或任务单上签字确认。\n\n4.9在合同执行期间如需对合同进行修改，应按原程序进行评审，并将修改内容通知客户和所有受到影响的人员。\n\n4.10执行期较短的合同在合同完成后2周内，执行期较长的合同在合同完成后4周内将全程的记录文件归档保存。\n',150,'现用文件/程序文件/程序文件2022/09-2022客户要求、标书、合同评审程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('5abf53aa-81b7-47c0-b5fd-78b04201baf6','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:8_9','8.9','管理评审','section','## 8.9 管理评审\n\n8.9.1 管理评审是本公司的管理层对管理体系运行的适应性和有效性进行正式评价，实验室主任主持本公司的管理评审，质量负责人负责制定每年度的管理计划。管理评审的周期为12个月，但可根据实际运行状况增加临时评审。本公司执行的管理层应根据预定的日程表和程序对管理体系和检测活动进行评审，以确保其持续适用和有效，并对管理体系进行必要的改动或改进。评审工作的实施执行《管理评审程序》。\n\n8.9.2 管理评审的输入应包括以下相关信息：\n\n与实验室相关的内外部因素的变化；\n\n目标实现；\n\n政策和程序的适宜性；\n\n以往管理评审所采取措施的情况；\n\n近期内部审核的结果；\n\n纠正措施；\n\n由外部机构进行的评审；\n\n工作量和工作类型的变化或实验室活动范围的变化；\n\n客户和员工的反馈；\n\n投诉；\n\n实施改进的有效性；\n\n资源的充分性；\n\n风险识别的结果；\n\n保证结果有效性的输出；\n\n其他相关因素，如监控活动和培训。\n\n8.9.3 管理评审的输出应记录与下列事项相关的决定和措施：\n\n对管理体系及管理过程的有效性进行评定；\n\n履行相关实验室检测活动的改进措施；\n\n对质量活动的评定、实施过程中资源的需求及由此采取的措施和时间要求等因素；\n\n下年度的目标、目的和活动计划等。\n\n8.9.4 评审时应记录发现的问题和由此采取的纠正或预防措施，本公司将组织责任部门、各岗位落实各项决定的改进措施，确保在规定的期限内得到有效实施。\n\n8.9.5 支持性文件\n\n《文件控制程序》 XZTC/CX-08-2018\n\n《实施纠正措施程序》 XZTC/CX-16-2018\n\n《记录控制程序》 XZTC/CX-19-2018\n\n《内部管理体系审核程序》 XZTC/CX-20-2018\n\n《管理评审程序》 XZTC/CX-21-2018\n',900,'现用文件/质量手册（第四版）.docx#8.9','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('5b665ac0-f670-4666-9ca7-f167e2559c45','00000000-0000-0000-0000-000000000001','9a4a4b45-61c0-4fad-a8ff-ef554366ea0f','647474cd-a228-43a8-ade5-a9a43a4ebe48',NULL,'procedure:xztc_cx_14_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 信息受理\n\n4.1.1 信息来源包括：\n\n4.1.1.1 客户的投诉；\n\n4.1.1.2 走访、调查；\n\n4.1.1.3 消费者协会的报告\n\n4.1.1.4 市场调研；\n\n4.1.1.5 媒体信息。\n\n4.1.2 投诉受理\n\n4.1.2.1 由办公室负责客户投诉的受理工作。直接与客户接触的人员也应随时了解客户不满意的信息。按《服务客户程序》收集客户投诉和其他外部信息，及时上报办公室主任。\n\n4.1.2.2 办公室主任及相关人员应热情主动地接待客户的来访，耐心倾听客户的投诉，详细记录投诉的内容，填写《客户投诉登记表》。\n\n4.1.2.3 办公室主任及时拆阅客户来函，仔细阅读来函内容，热情接听投诉电话并准确记录。填写《客户投诉登记表》，并保留投诉信函。\n\n4.2 调查核实\n\n4.2.1 办公室主任将收集到的投诉信息进行核实，向客户及其代表进行调查，了\n\n解事情的全过程，确定责任方及责任人，保留调查记录。\n\n4.2.2 对客户反映本公司工作人员工作纪律、职业道德方面的问题，按4.3.8条处理。\n\n4.2.3 办公室受理投诉申请，详细记录投诉内容，填写好有关记录，并向质量负责人报告。质量负责人负责召集有关人员对投诉材料进行认真分析、讨论和调查。\n\n调查工作包括以下内容：\n\n4.2.3.1 检测依据是否正确、有效；\n\n4.2.3.2 所用仪器设备是否在检定周期之内，是否符合标准要求；\n\n4.2.3.3 检测方法是否符合标准要求，是否有效；\n\n4.2.3.4 检测工作程序是否符合规定要求；\n\n4.2.3.5 检测环境条件是否符合标准要求；\n\n4.2.3.6 数据处理是否正确。\n\n4.2.4 质量负责人组织有关人员对原检测技术方案、技术条件、原始记录、检测报告等进行检查、核实和分析后，做出维持原报告或复检的决定。\n\n4.3处置\n\n4.3.1 经过调查核实，确认检测结果正确，属于客户的不理解而非我方责任的，由办公室主任负责以电话、信函、走访等方式向客户解释清楚，以便取得客户的理解，消除误解。\n\n4.3.2 如果确属本公司原因，造成客户的投诉和不满意，质量负责人组织相关岗位人员则按《不符合检测工作管理程序》和《实施纠正措施程序》进行原因分析，确定纠正措施并实施。客户要求复检理由充分时，应安排复检。\n\n4.3.3 复检\n\n4.3.3.1 复检用原样品或备用样品进行，如果客户已取回原样品或样品超过留存期或不可重复的检测（如样品状态已变化等）则不予以复检。\n\n4.3.3.2 为保证公正性，凡与投诉有关的当事者应当回避。检测部应另行安排具有相应技术水平的人员进行复检。\n\n4.3.3.3 检测结论以复检数据为准。\n\n4.3.4 答复\n\n4.3.4.1 复检结果证明原报告有误，应重新组织人员再次复验或送检，以两次相\n\n同结果作为最终判定结果。如最终结果确与原检测报告不一致，应按原\n\n程序重新出具检测报告，具体执行《结果报告管理程序》并在新报告和实验记录上注明产生问题的原因、更改的时间和原报告编号，同时收回原报告，按规定程序审批后发送顾客并向客户进行必要的解释，免收检测费。\n\n4.3.4.2 复检结果证明原报告无误，由办公室主任通知顾客。\n\n4.3.5 由质量负责人组织责任部门负责填写《客户投诉处理通知单》，由办公室主任向投诉方通报处理结果并征求意见，求得投诉方的谅解。\n\n4.3.6 投诉的处理应具有时效性，应做到在最短时间内得到严肃、认真的处理，确因检测结果有问题而给客户造成不良影响或损失时或损失时，质量负责人应向实验室主任报告，并妥善处理，必要时由实验室主任进行处理。\n\n4.3.7 当投诉涉及重大质量事故时，质量负责人可提出附加审核的要求。\n\n4.3.8 对于涉及到工作人员公正性行为、服务态度及执行合同方面的投诉，质量负责人协调技术负责人引进调查处理，对于检测结果质量问题，由实验室主任协调质量负责人，技术负责人进行调查、处理。\n\n4.3.9 投诉单位对复检结果仍有异议的，可向上级主管部门申请处理或进行仲裁。\n\n4.3.10 异议申请无论其结果如何，一般都应在一个月内答复完毕（发文确认原报告或发文更正报告）。\n\n4.3.11在对客户客户处理的过程中只要可能，本公司应告知投诉人已收到投诉，并向其提供处理进程的报告和结果，通知投诉人的处理结果应由与所涉及的实验室活动无关的人员作出，或审查和批准。只要可能，实验室应正式通知投诉人投诉处理完毕。\n\n4.4 记录管理\n\n办公室负责收集、归档客户投诉及相关的整改资料，提交管理评审，作为管理体系改进的信息。\n',150,'现用文件/程序文件/程序文件2022/14-2022处理投诉程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('5cbeb3dd-a810-4a72-b9c9-b0f05704cdeb','00000000-0000-0000-0000-000000000001','b3f4c46e-f363-44f3-86f5-4d207df828ef','a3a3bc75-4867-43ee-af53-ba1e1745ecbe',NULL,'procedure:xztc_cx_26_2022:source:scope','','范围','scope','### 范围\n\n适用于检测数据的采集、计算和处理、数据的修约、数据的判定、数据的转移、错误数字的更正，以及可疑数据的处理。\n',130,'现用文件/程序文件/程序文件2022/26-2022计算机文件及数据控制程序.docx#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('5d62e3a2-bd37-4368-ad49-b4a6b0723535','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_11','7.11','数据控制与信息管理','section','## 7.11 数据控制与信息管理\n\n7.11.1 本公司编制了《计算机文件及数据控制程序》，程序中要求检测工作各个环节的责任人（包括检测人员、报告编制人、审核人、授权签字人等）对本公司的数据进行保护和核查。\n\n7.11.2 本公司用于数据收集、处理、记录、报告、存储或检索的信息管理系统采用常用的商业现成软件，并在其设计的应用范围内使用，可被视为已经过充分的确认。当更改管理系统时，包括公司软件配置或对商用现成软件的修改，在使用前应被批准、形成文件并确认。\n\n7.11.3 对现有的信息管理系统和自动设备采集、处理、记录、编写报告、储存或检索数据时，建立和实施有效的数据保护系统，防止未经授权的访问，保护数据不丢失、不泄密、防修改，并确保：\n\n由本公司自己开发或委托开发的计算机软件形成文件，并经过验证合格，验证结果予以记录；\n\n按照《电子文件及数据控制程序》的要求，确保信息管理系统和自动采集设备的数据传输和数据处理正常运行及储存于计算机内的检测数据的完整性、保密性；\n\n对信息管理系统和自动采集设备进行定期维护，保证其正常功能运行，同时满足信息管理系统和自动采集设备的运行环境和必要条件，以此保护检测数据和信息的完整性；\n\n检测数据的变更必须得到有效的确认和控制；检测数据的借阅必须按相关程序申请，并得到批准；\n\n信息管理系统由外部供应商进行管理和维护，供应商或运营商应符合本准则的所有适用要求；\n\n维护计算机、自动设备确保其功能正常，并提供必要的环境和运行条件。\n\n7.11.4 公司应确保员工易于获取与实验室信息管理系统相关的说明书、手册和参考数据。\n\n7.11.5 本公司在运用计算机信息系统实施检验检测、数据传输或者对检验检测数据和相关信息进行管理时，应当具有保障安全性、完整性、正确性措施。\n\n7.11.6 支持性文件\n\n《计算机文件及数据控制程序》 XZTC/CX-26-2018\n\n《检测方法的选择与确认程序》 XZTC/CX-22-2018\n\n8.管理体系要求\n',810,'现用文件/质量手册（第四版）.docx#7.11','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('5eb82395-c9af-4f04-a253-70530f35ac18','00000000-0000-0000-0000-000000000001','7e5f11cb-e0dd-4d71-b0ba-357981f48045','7f87a99b-52a2-4b35-98d4-c4e17fc06bac',NULL,'procedure:xztc_cx_18_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 持续改进的策划\n\n4.1.1 本公司要达到持续改进的目的，就必须不断提高质量管理体系的有效性和效率，在实现质量方针和目标的活动中，持续追求对质量管理体系个过程的改进；\n\n4.1.2 日常的改进活动：对是成改进活动的策划和管理可以使用纠正和预防措施；\n\n4.1.3 较大的改进项目：涉及对现有过程的更改及资源需求变化，在策划进行时就应考虑：\n\n4.1.3.1 改进项目的目标和总体要求；\n\n4.1.3.2 分析现有过程的状况和确定改进方案；\n\n4.2 实施改进并评价改进结果\n\n4.2.1 办公室通过质量方针和目标的贯彻过程、审核结果、客户满意度调查、数据分析、纠正和预防措施的实施、管理评审的结果，寻找体系持续改进的机会，确认体系需要改进的方面（如检测服务质量、资源配置等），各部\n\n门进行策划，制定改进计划报质量负责人审核，实验室主任批准后予以实施。\n',150,'现用文件/程序文件/程序文件2022/18-2022改进控制程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('61bcba47-afe2-4b87-a31d-211acb6a6922','00000000-0000-0000-0000-000000000001','b3f4c46e-f363-44f3-86f5-4d207df828ef','a3a3bc75-4867-43ee-af53-ba1e1745ecbe',NULL,'procedure:xztc_cx_26_2022:source:purpose','','目的','purpose','### 目的\n\n对计算机和计算机文件、数据实施管理。确保检测数据的准确性、保密性。\n',120,'现用文件/程序文件/程序文件2022/26-2022计算机文件及数据控制程序.docx#目的','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('62febb38-f261-44f8-ac54-ecc94def0d41','00000000-0000-0000-0000-000000000001','7e5f11cb-e0dd-4d71-b0ba-357981f48045','7f87a99b-52a2-4b35-98d4-c4e17fc06bac',NULL,'procedure:xztc_cx_18_2022:source:scope','','范围','scope','### 范围\n\n适用于改进纠正和预防措施的制定实施与验证。\n',130,'现用文件/程序文件/程序文件2022/18-2022改进控制程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('631e0a21-b827-4a49-a9d4-51065938e406','00000000-0000-0000-0000-000000000001','76ffd146-ed11-4da9-a42a-c1ef8787db95','a64ffdaa-5ea0-412e-b076-f9c0c9283c85',NULL,'procedure:xztc_cx_29_2022:overview','','结果报告管理程序','section','# XZTC/CX-29-2022 结果报告管理程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/29-2022结果报告管理程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/29-2022结果报告管理程序.docx','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('63269a2c-6ab6-4fc7-b10b-ffcb0c31c061','00000000-0000-0000-0000-000000000001','76ffd146-ed11-4da9-a42a-c1ef8787db95','a64ffdaa-5ea0-412e-b076-f9c0c9283c85',NULL,'procedure:xztc_cx_29_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 检测报告的信息内容\n\n4.1.1 具体执行《质量手册》的要求\n\n4.2 检测报告输入信息（原始记录）审核\n\n4.2.1 技术负责人负责检测原始记录的审核工作,审核的主要内容包括：\n\n4.2.1.1 检测工作是否按有关标准规范、方法等完成；\n\n4.2.1.2 仪器设备使用是否匹配；\n\n4.2.1.3 环境条件是否符合要求；\n\n4.2.1.4 所得数据是否合理；\n\n4.2.1.5 检测结论是否正确。\n\n4.2.2 审核无误后签字确认。\n\n4.3 报告的编制\n\n4.3.1 检测人员根据检测活动项目以及标准规范的规定及客户的要求确定适合的报告格式；\n\n4.3.2 报告编制人依据原始记录编制报告，同时要做到以下几点：\n\n4.3.2.1 检测报告必须做到字迹清楚、数据准确、计算无误、内容真实、结果客观明确。\n\n4.3.2.2 报告内容必须涵盖必要的检测信息，符合标准规范、规程的要求及《质量手册》相应章节的要求，且与相应的原始记录保持一致。\n\n4.3.2.3 报告编写必须严格按规定格式、专业术语、符号和法定计量单位编制。\n\n4.3.3 报告内容：\n\n4.3.3.1 检测报告的标题；\n\n4.3.3.2 实验室名称、联系方式；\n\n4.3.3.3 检测报告的标号、页码和总页码；\n\n4.3.3.4 客户的名称；\n\n4.3.3.5 所用检测方法的标识（检验依据）；\n\n4.3.3.6 检测样品的名称、规格、状态、编号描述；\n\n4.3.3.7 送检日期及检测日期；\n\n4.3.3.8 检测结果使用法定计量单位（包括各个检测项目、技术要求和检测结果）与检测结论；及检测报告的声明；\n\n4.3.3.9 检验报告编制人、审核人和批准人的签名；\n\n4.3.3.10 未经本公司书面批准，不得部分复制。\n\n4.3.4 附加信息\n\n4.3.4.1 对于报告中没有包含的《认可准则》中规定的对检测结果做出解释说明的内容，本公司保证在客户要求时能方便的提供。\n\n4.3.4.2 对有特殊要求的检测项目，报告中还应包括下列信息：\n\n4.3.4.2.1 对检测方法的偏离、增删以及特殊条件的说明（如环境条件等）；\n\n4.3.4.2.2 需要时给出符合/不符合要求或规范（标准）的结论；\n\n4.3.4.2.3 当测量不确定度关系到检测结果的有效性或影响到样品的合格判定时，或客户要求给出测量不确定度时，或标准要求给出测量不确定度时，应给出测量的不确定度；\n\n4.3.4.2.4 根据需要提出意见和解释；\n\n4.3.4.2.5 特定方法、客户或有关部门要求的附件信息。\n\n4.4 检测报告的审核、签发\n\n4.4.1 打印好的报告由相应检测人员签字后，报告审核人员审核整个报告的内容及原始数据录入的准确性。最后有授权签字人批准。检测、计算、审核、签字人签字应在其授权领域范围内依次进行，不得越级、越权或代人签字。\n\n4.4.2 经批准的报告一式两份，一份由资料管理员存档，另一份由样品管理员保存待发，委托方签字领取。检验报告和鉴定证书，可只保留电子的或纸质的原始纪录，不再保存报告或证书的副本。\n\n4.4.3 若需以电话、传真或其他方式传送检测结果时，经技术负责人批准后传送并做好登记，在传送时应向委托方声明：所发内容只做参考，以正式书面报告为准。详见《保护客户机密信息程序》。\n\n4.4.4 若以邮寄方式发放报告，报告发放人员负责报告的保密性和完整性，并在发放登记“备注”中注明邮寄方式，详见《保护客户机密信息程序》。\n\n4.4.5发送的检测证书/报告，应遵循与客户在检测委托合同书中达成的发送方式。要求客户派原送样人或委托代理人取样（证书）。取证书和样品时，客户必须交回取样（证书）委托单，并出示送样人证件及委托取样（证书）人证件。\n\n4.5 报告的修订\n\n4.5.1 当报告发出后，如发现有误而需修订时，应由检测员填写《报告更改申请表》，经技术负责人批准后，重新出具检测报告。\n\n4.5.2 若委托方发现报告有误而要求更改检测报告时，则由委托方提出书面申请（若更改的报告有见证或监督要求的，还需附见证方和监督方的书面意见，并签字确认），原报告审批人填写《报告更改申请表》，按《处理投诉程序》执行。待查明原因确认事实后，及时通知客户，并按发本程序4.4.1条款执行程序。\n\n4.5.3 对已发出有误报告进行修订时，应将有误报告全部收回后，方可将修订后\n\n的报告办理新的发放手续发放。\n\n4.5.4 当追溯到报告有误是由检测方法或仪器设备问题导致时，应及时与客户联系安排重新检测。\n\n4.5.5 修订后的出具的新报告及《报告更改申请表》和收回的原报告同其他相关结果报告管理程序\n\n资料一同送交资料员处存档备查。\n\n4.6 报告的存档、借阅\n\n4.6.1 报告的存档和借阅档案《记录控制程序》执行。\n\n4.7 检测报告的检查\n\n4.7.1 技术负责人负责定期（每半年至少一次）组织监督员组成检查小组。对各\n\n领域的检测报告的质量、管理情况进行随机抽查。\n\n4.7.2 主要检查内容基本包括：\n\n4.7.2.1 报告应涵盖的信息是否齐全；\n\n4.7.2.2 原始记录、委托记录、更改记录是否齐全、正确；\n\n4.7.2.3 原始记录、报告的错误量统计；\n\n4.7.2.4 报告审核、签发过程是否符合规定；\n\n4.7.2.5 存档情况\n\n4.7.3 检查时由监督员填写《报告抽查情况记录表》。\n\n4.7.4 技术负责人根据检查情况决定是否采取相应措施。详见《实施纠正措施程序》。\n\n4.7.5 抽查记录由资料管理员保管，每年全部检查结果，交资料管理员归档。\n\n4.8 关于对检测结果给出意见和解释\n\n4.8.1 通常情况之下，本公司只向客户报告送检样品的检验结果，如客户有特殊需求，需给出意见和解释时，由给出意见和解释人员（授权签字人）在检测报告上予以解释，解释的项目通常包括：\n\n对结果是否符合要求的声明及依据；\n\n全同要求的履行及依据；\n\n如何使用结果的建议及依据；\n\n如何对产品进行改进及依据\n\ne.上述意见和解释可与客户直接对话沟通，并且这些对话要有记录。\n\nf.当做出与规范或标准符合性声明时，应考虑与所用判定规则相关的风险水平（如错误接受、错误拒绝以及统计假设），将所使用的判定规则制定成文件，并应用判定规则。在报告符合性声明时应清晰标识:\n\n符合性声明适用于哪些结果；\n\n满足或不满足哪个规范、标准或其中哪些部分；\n\n应用的判定规则（除非规范或标准中已包含）。\n',150,'现用文件/程序文件/程序文件2022/29-2022结果报告管理程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('6410b54f-2aef-4c4a-ad2a-5b693f70a44e','00000000-0000-0000-0000-000000000001','dc7146d9-e84c-407e-8e35-2515e05d7642','3b870297-530f-4b96-a1fd-83e397708084',NULL,'procedure:xztc_cx_05_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 量值溯源计划的拟定\n\n4.1.1 设备管理员将根据《中华人民共和国强制检定的工作计量器具明细目录》检定周期和本公司实际确定检定/校准的仪器设备名录，制定检定/校准的年度计划，经技术负责人审核，实验室主任批准后实施。对于溯源到国家/国际计量标准不可能或不适用时，可采用分步校准，或通过参加适当的能力验证等提供相关的证明。\n\n4.1.2 设备量值溯源计划\n\n4.1.2.1 量值溯源计划可分两部分：\n\n4.1.2.1.1 是可以溯源到国际单位制（SI）或国家计量基准的仪器设备，国家规定强检的仪器设备依法实施计量检定（校准），应由设备管理员编制详细的《仪器设备周期检定计划表》，技术负责人审核，实验室主任批准；\n\n4.1.2.1.2 无法溯源到国际单位制（SI）或国家计量基准的仪器设备，应采用其他的核查方式，由设备管理员制定计划，经技术负责人批准后，由设备管理员组织实施。\n\n4.1.2.2 因设备无检定/校准机构而采取的核查方式可包括：\n\n4.1.2.2.1选择可满足溯源的诸如有证标准物质、约定的方法或有关各方广泛接受且满足时用的协议标准等；\n\n4.1.2.2.2 通过实验室间的比对对设备的主要量值功能进行确认；\n\n4.2 设备核查计划的编制与实施\n\n4.2.1 设备管理员根据本公司无法溯源的仪器设备情况，组织协调相关检测部人员编制设备核查计划和作业指导书。\n\n4.2.2 设备管理员根据各自的无法溯源的仪器设备情况，检测/校准原理、检测/校准范围、技术特性和使用要求等编制设备核查计划。设备管理员通过用设备测量标准物质或采用实验室间比对的方法实现量值的可靠性和统一性。确保该设备与一定量值范围内的校准相一致。\n\n4.2.3 检测部编制的计划由设备管理员整理后，交技术负责人审批，设备管理员组织实施。并控制以下内容：\n\n4.2.3.1 实验室间比对报告要经过技术负责人的确认。\n\n4.2.3.2 自核查报告要经过技术负责人的确认。\n\n4.2.4 仪器设备进行核查操作时，应有相应的实施记录。\n\n4.2.5 经过以上确认后，设备方可启用。\n\n4.3计量检定（校准）计划的编制与实施\n\n4.3.1 设备管理员根据各依法授权的计量检定机构的检定(校准)范围,按规定的周期拟定本公司的年度检定/校准计划并进行实施(见：《周期检定计划表》)，对需要检定/校准的仪器设备设备管理员应根据仪器设备技术指标和实际工作需要，委托法定检定/校准机构进行，计划的拟定与实施应对以下几方面进行控制：\n\n4.3.1.1 计划内的仪器设备应确保送至对该项目有检定（校准）能力的法定计量机构进行检定（校准）；\n\n4.3.1.2 检定证书应由设备管理员确认。\n\n4.3.1.3 校准证书和测试报告应由设备管理员对相应的技术指标进行评价，确认合格后方可启用对应的仪器设备及标准物质。\n\n4.4 对量值溯源计划的附加要求\n\n4.4.1 新购置的，经过修理的或长期停用准备启用的检测仪器设备，必须纳入量值溯源计划内，确定其状态后方可投入使用。\n\n4.4.2 使用频率高、漂移性较大的检测仪器设备及标准物质在检定周期内应在计\n\n4.5仪器设备计量检定(校准)结果确认\n\n4.5.1设备员对校准单位能力及校准结果进行验证，确认校准结果是否满足检测标准及仪器使用要求，确认合格后填写《周期检定计划表》。\n\n4.5.2 仪器设备管理员负责按计划将依法管理的计量器具、参考标准、标准物质 送检定或校准,检定合格后更换标识,将证书/报告复印一份,原件存档,复印件放入仪器设备盒中。\n\n4.5.3校准结果需要经过确认，对是否符合标准、规范要求作出判定。对校准产生的修正值或修正因子,须将其标识在显著的地方,以引起使用人员的注意。原有修正值或修正因子需更新。\n\n4.5.4 检测人员负责按计划将专用计量器具、无法溯源的仪器分别进行自校准或开展比对，校准或比对的结果应形成记录，记录的管理方法与检定证书相同。\n\n4.5.5 检测人员不得使用未经检定/校准的，或已超过有效期的，或不合格的仪器设备。监督员负责监督仪器设备的正确使用，仪器设备管理员负责标识、收回或隔离、封闭不符合要求的仪器设备。\n\n4.5.6 开展自校准的条件包括：\n\n⑴有经过培训考核合格的校准人员；\n\n⑵有进行校准的参考标准或有证标准物质；\n\n⑶校准方法编制成文件并经批准发布；\n\n⑷有合适的校准环境条件\n\n⑸有参考标准的管理制度。\n\n4.6 仪器设备检定(校准)状态的标识\n\n4.6.1设备员对经过检定(校准)合格的设备检定（校准）状态进行标识，具体标识方法参见《仪器设备的控制管理程序》。\n\n4.7 标准物质的量值溯源\n\n4.7.1本公司尽可能购买具备国际认可、国家认可资格的标准物质经营单位和生产厂家购买有证标准物质和参考物质；\n\n4.7.2 标准物质的溯源应由证物质的合格证书保证，必要时应溯源到SI单位制单位，内部标准物质应检查其技术和经济的实用性；\n\n4.7.3标准物质和参考物质的使用要求,见《标准物质管理程序》。\n\n4.8标准溶液管理\n\n标准溶液配制和标定按标准进行，规定标准溶液和其他内部标准物质的制备、 标定、验证、有效期限、注意事项或危害、制备人、标识等要求，并保存详\n\n细记录。标准溶液的配制应有稀释记录。\n\n4.9仪器设备校准状态的保护\n\n仪器设备经过检定/校准，其校准状态应受到保护，以防止无意或有意的可能造成失效的调整。保护包括硬件方式保护（如加封印）或软件方式保护（如设置密码）。由仪器设备管理员实施。\n\n4.7参考标准和标准物质的运输和储存\n\n参考标准和标准物质的安全处置、运输、储存和使用按照《设备和设施管理程序》执行。\n\n4.8 量值溯源性资料的保管\n\n4.8.1 所有与量值溯源有关的计划、对比报告、检定（校准）证书、核查报告等均由设备管理员统一归档保管。\n',150,'现用文件/程序文件/程序文件2022/05-2022实现测量可溯源程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('647e53eb-6086-4d1d-817a-1ae391878f3a','00000000-0000-0000-0000-000000000001','25bc5721-9452-4aa9-a626-0262a1bb1ee4','36ac3d04-2b8c-435e-a334-26a97ebfa4ad',NULL,'procedure:xztc_cx_03_2022:source:purpose','','目的','purpose','### 目的\n\n对所使用仪器设备实施有效的管理，确保其始终处于完好受控状态，以保证检测结果的准确性，特编制本程序。\n',120,'现用文件/程序文件/程序文件2022/03-2022仪器设备管理程序.docx#目的','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('657aaca1-c05a-4883-b0e6-1887855cbec3','00000000-0000-0000-0000-000000000001','0298e975-ff58-4c04-b700-8e0cf4cd55d0','9f92ea6a-b554-401a-b1b5-c76269f78919',NULL,'procedure:xztc_cx_34_2022:source:related_documents','','相关文件','text','### 相关文件\n\n无\n',160,'现用文件/程序文件/程序文件2022/34-2022内部监控管理程序.doc#相关文件','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('659144fc-241f-4248-957c-9461c9ced016','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:8_6','8.6','改进','section','## 8.6 改进\n\n8.6.1 持续改进是本公司的一项管理原则，本公司要利用对质量方针评审、对质量目标的统计、内/外部审核结果的评审、对检测数据进行分析、通过对客户满意度调查，对客户投诉的处理，对不符合事项采取纠正措施和预防措施，对管理评审的输出项目进行改进等手段，使管理体系得到持续改进，以确保其符合性和有效性。\n\n8.6.2 持续改进具体措施如下：\n\n质量负责人负责监督管理体系方面的纠正措施和预防措施的实施；\n\n技术负责人负责监督技术运作的纠正措施和预防措施的实施；\n\n管理层负责体系持续改进的策划工作；\n\n质量负责人负责有效地处理顾客意见；\n\n责任部门负责制定纠正措施和预防措施的实施。\n\n8.6.3 本公司在策划和管理时应考虑：\n\n改进项目的目标和总体要求；\n\n分析现有过程的状态，确定改进方案；\n\n实施改进并评价改进的结果；\n\n改进可以是日常的改进活动，也可以是较重大的改进项目。\n\n8.6.4 本公司应通过开展客户满意度调查，积极从客户处搜集其他反馈信息，无论是正面的还是反面的反馈。本公司应对这些反馈进行分析总结和评价，形成报告，以改进管理体系、检测工作及对客户的服务。\n\n8.6.5 支持性文件\n\n《不符合检测工作管理程序》 XZTC/CX-15-2018\n\n《实施纠正措施程序》 XZTC/CX-16-2018\n\n《实施预防措施程序》 XZTC/CX-17-2018\n\n《内部管理体系审核程序》 XZTC/CX-20-2018\n\n《管理评审程序》 XZTC/CX-21-2018\n\n《服务客户程序》 XZTC/CX-12-2018\n',870,'现用文件/质量手册（第四版）.docx#8.6','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('6734114a-0a5d-4c02-86fe-ac295f4cfe1c','00000000-0000-0000-0000-000000000001','40055ae1-3a24-466a-b70a-78bb7c26362a','0cadf789-6c6b-4b36-a6fc-a797e4657a0f',NULL,'procedure:xztc_cx_19_2022:element:record_control','','要素落实：记录控制','control_requirement','### 要素落实：记录控制\n\n- 程序文件：XZTC/CX-19-2022 记录控制程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('67fe2aca-0049-437d-a184-142733dd57f5','00000000-0000-0000-0000-000000000001','bc8c7454-2b19-4837-aeb8-b3d9a1f13d25','30de644c-9b17-4536-86cf-18ad00d7b322',NULL,'procedure:xztc_cx_16_2022:source:purpose','','目的','purpose','### 目的\n\n对管理体系或技术运作过程中的不符合，采取有效的纠正措施，以实现管理体系的持续改进。\n',120,'现用文件/程序文件/程序文件2022/16-2022实施纠正措施程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('687d74b1-e65b-485e-a4aa-961b980377e5','00000000-0000-0000-0000-000000000001','43c73354-2b49-458e-b110-281f4f7db028','b835ad93-cc81-40b1-8e88-266b4fe4424e',NULL,'procedure:xztc_cx_01_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 审核签约人员的录用。\n\n3.1.2 批准本公司的年度培训计划。\n\n3.2 技术负责人应：\n\n3.2.1 负责制定本公司的年度培训计划。\n\n3.2.2 负责对人员的考核及管理。\n\n3.3 质量负责人应：\n\n3.3.1 组织实施年度培训计划，组织验证培训效果。\n\n3.4 办公室主任应：\n\n3.4.1 负责组织确定人员能力要求。\n\n3.4.2 负责组织建立本公司人员名册及个人技术档案。\n\n3.5资料员\n\n3.5.1负责建立人员技术档案。\n',140,'现用文件/程序文件/程序文件2022/01-2022人员培训程序.docx#职责','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('69450fd9-ed81-4172-ac75-db4adbdec3fe','00000000-0000-0000-0000-000000000001','bd275009-ec1d-4a48-b6fc-39304fe0dee9','f488cefe-287f-47a2-b075-c5cd1cbcfa0b',NULL,'procedure:xztc_cx_17_2022:source:scope','','范围','scope','### 范围\n\n适用于公司对可能发生潜在的不符合的预防控制的管理。\n',130,'现用文件/程序文件/程序文件2022/17-2022实施预防措施程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('69b6a8a5-9c37-44a4-b8f2-3519133711e9','00000000-0000-0000-0000-000000000001','43c73354-2b49-458e-b110-281f4f7db028','b835ad93-cc81-40b1-8e88-266b4fe4424e',NULL,'procedure:xztc_cx_01_2022:element:personnel','','要素落实：人员','control_requirement','### 要素落实：人员\n\n- 程序文件：XZTC/CX-01-2022 人员培训程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('6adeef0f-2915-4454-9cbb-cda321a9d167','00000000-0000-0000-0000-000000000001','afb48a72-ca24-408e-86d1-685bc252a4a9','f5bfe2a1-1db8-49ca-8b36-6c8c9378a7fc',NULL,'procedure:xztc_cx_23_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《实施纠正措施程序》 XZTC/CX-16-2022\n\n《检验工作的监督程序》 XZTC/CX-31-2022\n',160,'现用文件/程序文件/程序文件2022/23-2022允许方法偏离控制程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('6af89301-0890-4bf0-96ed-89a5c4a7dd01','00000000-0000-0000-0000-000000000001','7e5f11cb-e0dd-4d71-b0ba-357981f48045','7f87a99b-52a2-4b35-98d4-c4e17fc06bac',NULL,'procedure:xztc_cx_18_2022:source:purpose','','目的','purpose','### 目的\n\n采取有效的改进、纠正和预防措施、实施质量管理体系的持续改进，向本公司和客户提供更多的利益。\n',120,'现用文件/程序文件/程序文件2022/18-2022改进控制程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('6b5f3ea0-9e28-4367-b218-eebebb1c82ec','00000000-0000-0000-0000-000000000001','f0487552-998f-4890-94df-49779d41b185','48e77eb2-f569-435f-b92e-7a4a99351f71',NULL,'procedure:xztc_cx_20_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 内部审核的策划\n\n4.1.1 办公室负责人每年年初制定年度内部审核计划，经质量负责人审核，实验室主任批准。\n\n4.1.2 可根据实际情况采取滚动式审核或定期集中审核的方法（见《年度内审计划表（集中式）》），内部审核每隔12个月至少进行一次，一般可安排在管\n\n理评审前进行。\n\n4.1.3 审核范围应覆盖本实验室所有岗位和管理体系要素，包括检测活动。\n\n4.1.4 当对不符合或偏离的鉴别、纠正措施实施而需进行附加审核时，由办公室负责人安排对相关活动区域的临时审核，详见《实施纠正措施程序》。\n\n4.2 准备工作\n\n4.2.1 成立审核组：内审员由办公室负责人委派，由经过培训取得内审员培训合格证书的人员担任，审核组长由办公室负责人本人或委托人担任。在审核中，内审员应独立于被审核的活动，不能审核自己的工作，以保证审核的客观性、公正性。\n\n4.2.2 制定审核实施计划\n\n4.2.2.1 审核实施计划由审核组长编制，办公室负责人审核，质量负责人批准（见：《内部审核日程计划表》）。\n\n4.2.2.2 审核实施计划应对管理体系要素及相关岗位全面覆盖，且重点突出。内容包括：\n\n4.2.2.2.1 审核的目的和范围；\n\n4.2.2.2.2 审核依据；\n\n4.2.2.2.3 审核组长和审核人员；\n\n4.2.2.2.4 审核要素和岗位及审核员分工；\n\n4.2.2.2.5 审核日程安排等。\n\n4.2.3 审核计划的发放\n\n4.2.3.1 审核计划经质量负责人批准后实施。一般应在审核一周前发放到各受审岗位。受审岗位做好准备、安排好工作，以保证审核的顺利进行。\n\n4.2.4 审核组预备会\n\n4.2.4.1 审核前3-5天，由审核组长组织内审员召开预备会议。布置审核要求，明确每个审核员的工作内容，并准备《内审检查记录表》和必要的文件。\n\n4.3 实施审核\n\n4.3.1 首次会议：审核正式开始时，审核组长主持召开由审核组全体成员和受审核岗位人员参加的首次会议，主要内容为：\n\n4.3.1.1 介绍审核组成员和审核分工；\n\n4.3.1.2 宣布审核目的和范围；\n\n4.3.1.3 说明审核活动的内容及其要点，审核采用的方法和程序；\n\n4.3.1.4 宣布审核时间表。\n\n4.3.2 现场审核\n\n4.3.2.1 审核员依照分工按检查表开展审核工作；\n\n4.3.2.2 审核过程应通过交谈询问、查阅文件和记录、观察及现场考核检查等方法收集客观证据，并在《内审检查记录表》中填写相关审核记录；\n\n4.3.2.3 受审核岗位人员应如实回答审核员的提问，主动配合审核员的工作，及时提供审核的证明材料、实物等；\n\n4.3.2.4 审核中发现问题应及时提出，有不同意见时，应耐心解释，使问题尽早解决；\n\n4.3.2.5 审核组应在审核期间定期或不定期召开例行会议，交流总结审核工作，以确保审核的准确性；\n\n4.3.2.6 开具不符合报告。审核结束时，审核员根据审核记录记载的资料经评审确定的不符合项填写《不符合项处置通知表》对不符合事实予以描述并评价其性质，由责任岗位人员制订的落实纠正/纠正措施要求，经部门负责人批准后实施，由审核组长组织内审员验证纠正/纠正措施实施的有效性。\n\n4.3.3 末次会议\n\n4.3.3.1 由审核组长主持，参加人员为受审核岗位人员和内审员；\n\n4.3.3.2 审核组介绍本次审核的过程和结果，说明不符合项的数量及分布；对审核情况的综合评价，及对采取措施的建议和要求；不符合项处置通知表交由不符合部门确认；\n\n4.3.3.3 实验室主任、质量负责人对审核活动总结、提出整改落实的要求；\n\n4.3.3.4 审核组长组织相应内审员负责做好会议的记录和签到\n\n4.3.4 内部审核报告\n\n4.3.4.1 审核活动结束后，由审核组长负责编制《内部审核报告》；\n\n4.3.4.2 内部审核报告应包括以下内容：审核的目的和范围、受审核部门或岗位名称、审核日期及审核员、审核所依据的文件、审核过程的描述、审核结果、观察到的不符合项、根据审核情况做出的结论或建议等。\n\n4.3.4.3 《内部审核报告》应在审核结束一周内提交质量负责人，经质量负责人签批后，由审核组分发到各受审核部门、岗位有关人员，并报质量负责人和技术负责人。\n\n4.4 不符合项处置及跟踪验证\n\n4.4.1 各责任部门、岗位根据内审组的要求，落实纠正和纠正措施，认真填写《不符合评审处置记录表》、《实施纠正措施记录表》，并报告实施情况，由审\n\n核组长组织内审员进行验证。详见《不符合检测工作的控制管理程序》和\n\n《实施纠正措施程序》。\n\n4.4.2 若发现不符合已对客户产生不利影响，应及时书面通知客户。\n\n4.4.3 在下次内审中，应首先对上次内审中发现的不符合项进行审核，内审员应检查纠正措施是否有效得以实施。\n\n4.5 审核资料\n\n4.5.1 内审记录：\n\n内审组应该认真保留内部审核的全部记录，包括文审记录、内审计划表、内审首次会议记录表、内设检查表、不符合检测工作记录表、末次会议记录等。所有审核记录应按规定的质量记录保存时间保存。\n\n4.5.2 不符合项记录：\n\n其中应当记录已确定的每一个不符合项，详细记录其性质、可能产生的原因、需采取的纠正措施和适当的不符合项关闭时间、不符合项的分布情况等。\n\n4.5.3 内部审核报告：\n\n审核结束后，内审员负责编制最终内部审核报告。报告应当总结审核结果，并包括以下信息：\n\n4.5.3.1 审核组成员名单；\n\n4.5.3.2 审核日期；\n\n4.5.3.3 审核区域；\n\n4.5.3.4 被检查的所有区域的详细情况；\n\n4.5.3.5 机构运作中值得肯定的或好的地方；\n\n4.5.3.6 确定的不符合项及其对应的相关文件条款；\n\n4.5.3.7 改进建议；\n\n4.5.3.8 商定的纠正措施及其完成时间，以及负责实施纠正错误的人员；\n\n4.5.3.9 采取的纠正措施；\n\n4.5.3.10 确认完成纠正措施的时间；\n\n4.5.3.11 质量负责人确认完成纠正措施的签名。\n\n4.5.4 内部审核报告提交：\n\n内部审核报告交质量负责人，必要时将包括不符合项的记录及整改资料在内的内审资料提交实验室主任。\n\n4.5.5 输入管理评审\n\n质量负责人应当对本次内部审核的结果和采取的纠正措施的趋势进行分析，并形成报告，在下次管理评审会议时提交会议评审。\n',150,'现用文件/程序文件/程序文件2022/20-2022内部管理体系审核程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('6b6341e6-29f2-4926-a86a-a7dde1eda4c0','00000000-0000-0000-0000-000000000001','60178817-f881-41e9-98b7-cbaaa29f3720','7798efd3-8799-47f0-8311-65fc9a5d613d',NULL,'procedure:xztc_cx_35_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 技术负责人应\n\n3.1.1 根据检测/检验标准依据和检测/检验方案的要求提出抽样方法，批准抽样计划。\n\n3.2 检测部应\n\n3.2.1 负责根据抽样计划组织实施抽样工作。\n\n3.3 监督员应\n\n3.3.1 负责对抽样管理状态进行监督。\n',140,'现用文件/程序文件/程序文件2022/35-2022抽样控制程序.doc#职责','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('6cfe6de1-71f2-4c66-b3e7-4f342e53cee4','00000000-0000-0000-0000-000000000001','c6a9947a-3e7f-4a66-b3d2-383348f9be03','534421f2-4307-4f6c-9df2-108bd6be4607',NULL,'procedure:xztc_cx_21_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 负责按期主持管理评审，批准管理评审报告。\n\n3.2 质量负责人应：\n\n3.2.1 协助实验室主任完成管理评审的有关工作，组织制定评审计划及对改进措施的实施跟踪和验证。\n\n3.2.2 负责组织协调各相关岗位准备评审所需的输入资料，监督管理评审提出的改进措施的实施并验证。\n\n3.3 各部门负责人和岗位人员\n\n3.3.1参与管理评审。\n',140,'现用文件/程序文件/程序文件2022/21-2022管理评审程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('6d3af914-23b2-45d4-9c7c-00b25e9b37e5','00000000-0000-0000-0000-000000000001','25bc5721-9452-4aa9-a626-0262a1bb1ee4','36ac3d04-2b8c-435e-a334-26a97ebfa4ad',NULL,'procedure:xztc_cx_03_2022:source:scope','','范围','scope','### 范围\n\n适用于开展检测工作所使用的仪器设备及其软件的购置、验收、使用、维护、修理、降级与报废、仪器设备的标识与档案等领域的管理工作。\n',130,'现用文件/程序文件/程序文件2022/03-2022仪器设备管理程序.docx#范围','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('6da4a3da-0dd8-4ecb-b84c-20bcc60d313f','00000000-0000-0000-0000-000000000001','44ff5408-e03d-4859-9cd4-926a8f69fda5','948d2434-2b53-47e6-adab-cf2ee95dfc3c',NULL,'procedure:xztc_cx_09_2022:source:related_documents','','相关文件','text','### 相关文件\n\n⑴《记录控制程序》 XZTC/CX-19-2022\n',160,'现用文件/程序文件/程序文件2022/09-2022客户要求、标书、合同评审程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('6e387c51-2f3d-4837-b0c1-459ce9a4600e','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_2','7.2','方法的选择、验证和确认','section','## 7.2 方法的选择、验证和确认\n\n7.2.1 总则\n\n7.2.1.1 本公司对开展的检测项目应选择的方法都做了明确规定，且规定的方法中亦包括了被检测物品的处置、传递、储存和准备。必要时能够得到实施不确定度的评定和数据分析统计的控制。\n\n7.2.1.2 本公司对开展的检测项目的主要仪器设备，均提供设备使用操作规程；对检测样品的处置亦提供作业指导书，其原则是不降低检测结果的质量。\n\n7.2.1.3 如选择新的检测方法，检测室主任应组织编制相应的作业指导书或操作规程。\n\n7.2.1.4 检测人员所使用的程序文件、规范、标准、作业指导书及其他应用技术文件均保存在作业现场，以便使用人员方便取阅，且保存和使用的规范标准和规程、作业指导书均为现行最新有效版本。\n\n7.2.2 方法的选择\n\n7.2.2.1 检测方法的选择将遵循符合国家规范、行业规定、地方标准的前提下，使用标准的最新有效版本，最大限度地满足客户的要求。应优先使用标准方法，使用前应进行验证。\n\n7.2.2.2 当客户未对检测项目指定方法时，本公司选择方法的原则是：\n\n优先使用国际、区域或国家、行业颁布的标准方法；\n\n由著名的技术组织或有关科学书籍和期刊公布的方法，以及仪器设备制造商指定的方法（如技术说明书等）。\n\n7.2.2.3 为使检测活动能够顺利进行，并保证结果的可信度，在开展检测活动之前，应验证标准方法是否能够正确地运用，以确保实现所需方法的性能和数据的有效性。具体确认方法执行《检测方法的选择与确认程序》。\n\n标准方法及验证：\n\n标准方法在初次使用前，检测室应验证正确地运用这些标准方法，验证后经技术负责人批准后方可使用；\n\n如果标准方法发生了变化，检测室应重新验证、批准，验证的方法见《检测方法的选择与确认程序》。\n\n7.2.2.4 当客户提出的方法不适合或已过期时，应及时通知客户进行协商，另行选择方法。\n\n7.2.2.5 对检测方法的偏离，则应提出允许偏离的申请，阐明偏离的原因和理由，经过评审和批准形成文件，并征得客户认可后，方能允许使用（见《允许方法偏离控制程序》）。\n\n7.2.3 本公司制定的方法\n\n为了适应长远的检测工作需要，本公司如果制定新的检测方法，则应进行可行性论证和立项，有计划、有步骤组织具有足够资源支配权且有资格的人员进行方法的制定和实施，应按照本手册的7.2.4和7.2.5的要求进行评审、验证和确认活动。本公司目前没有自己制定的检测方法。\n\n7.2.4 非标准方法\n\n当在标准方法中无适用方法可供选择，而必须选择非标准方法时，本公司将与客户沟通协商，让客户充分了解检测中的各环节，说明其方法经确认是有效的，征得其同意，使出具的结果能为客户所接受。选择的非标准方法在使用前应得到技术负责人适当的确认。本公司目前所使用的检测方法均为标准方法。\n\n7.2.5 方法的确认\n\n7.2.5.1 方法确认的范围包括：非标准方法、本公司自行制定的方法、超出其覆盖范围使用的标准方法、扩充和修改过的标准方法。\n\n7.2.5.2 方法的确认过程包括：\n\n预期用途的识别（包括被确认方法应满足具体预期用途的特定要求和必须满足的客户需求）；\n\n采用合适的确认技术，确定被确认方法的特征（指使用所确认的得到的值的范围和准确度）；\n\n评价使用确认得到的值的范围和准确度是否满足预期用途；\n\n核查所确认的方法的有效性声明。\n\n7.2.5.3 方法的确认是通过核查方式，并提供客观证据，以证实某一特定预期用途的特殊要求得到满足。用于确定某方法性能的技术是下列情况之一，或是其组合：\n\n使用参考标准或标准物质（参考物质）进行校准或评估偏倚和精密度；\n\n对影响结果的因素做系统评审；\n\n与其他方法所得的结果进行比较；\n\n实验室间比对；\n\n根据对方法的理论原理和实践经验的科学理解，对所得结果不确定度进行的评定。\n\n7.2.5.4 本公司对选择的上述方法进行确认，其目的是经过确认来证实该方法是适用和有效的，同时，确认的方法将包括尽可能多的检测专业领域。\n\n7.2.5.5 本公司对方法的确认制定了《检测方法的选择与确认程序》，该程序规定了应做的确认结果的记录。在程序中对确认可采用的技术进行了描述。\n\n7.2.6 支持性文件\n\n《检测方法的选择与确认程序》 XZTC/CX-22-2018\n\n《检测不确定度的评定控制程序》 XZTC/CX-27-2018\n\n《允许方法偏离控制程序》 XZTC/CX-23-2018\n',720,'现用文件/质量手册（第四版）.docx#7.2','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('6f6335e3-1d38-4569-9ae8-92518bb82584','00000000-0000-0000-0000-000000000001','71ac64b2-e042-4afc-aacc-a1b8f9d5b18c','b61891de-34e0-475d-aa81-5f55a84285ec',NULL,'procedure:xztc_cx_04_2022:source:records','','记录','record_requirement','### 记录\n\n《仪器设备和标准物质期间核查计划》 XZTC/ BG-04-01\n\n《仪器设备和标准物质期间核查方案》 XZTC/ BG-04-02\n\n《仪器设备和标准物质期间核查记录表》 XZTC/ BG-04-03\n',170,'现用文件/程序文件/程序文件2022/04-2022仪器设备和标准物质期间核查程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('6faa2f35-e150-4f7c-a7af-f43a122dfaf1','00000000-0000-0000-0000-000000000001','43c73354-2b49-458e-b110-281f4f7db028','b835ad93-cc81-40b1-8e88-266b4fe4424e',NULL,'procedure:xztc_cx_01_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司所有与检测工作有关的人员培训、考核和监督等活动的控制。\n',130,'现用文件/程序文件/程序文件2022/01-2022人员培训程序.docx#范围','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('70a8c43e-a769-4421-af70-d204f44626da','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:6_2','6.2','人员','section','## 6.2 人员\n\n6.2.1 人员配备\n\n本公司配备了充足的管理和技术人员，并具有一定的学历和相应的专业技术知识以及丰富的工作经验，受过与其承担工作相当的教育、培训和考核，并具有相应的资格。本公司所有人员应行为公正、有能力，并按照实验室管理体系要求工作，从事检测活动的人员不得同时在任何其他实验室兼职。本公司制定了《员工行为规范》以此约束全体员工以公正、独立、诚实的态度和精神履行自己的职责。\n\n6.2.2 岗位任职资格条件\n\n本公司对检测结果有影响的各级人员所需的能力提出了具体要求，各岗位任职资格条件的完整规定见附录17《各岗位任职资格条件》 。主要原则如下：\n\n实验室主任、技术负责人、质量负责人须具有大专及以上学历，并接受过资质认定评审准则相关培训；\n\n授权签字人须具有中级及以上专业技术职称或同等能力，经资质认定部门批准，在其签字领域内行使签字权；\n\n检测人员须具有珠宝或相关专业学历或资格证书（CGC、 FGA、GIC、 NGTC等），经上岗培训考核合格并由实验室主任颁发上岗授权书后方可独立从事检测活动；\n\n内审员须持有内审员资格证书，经实验室主任任命；\n\n各岗位人员的具体学历要求、工作年限要求、专业技能要求以及需通过的考核项目，详见附录17。\n\n6.2.3 人员资格确认及授权\n\n6.2.3.1 根据本公司提出的要求及客户的要求和有关规定，对上述人员的教育、培训、工作经验、可证明的技能进行能力与资格确认，尚不能满足要求的人员，则应采取措施以求达到满足相关要求。\n\n6.2.3.2 对于资质认定的相关要求，相应的岗位应由具有珠宝鉴定师资格证的人员担任，由技术负责人负责组织相关的技能考核，考核合格后由实验室主任颁发上岗授权书，未经授权的人员不得操作相关设备。\n\n6.2.3.3 两年以上未从事珠宝玉石检验的人员，在重新上岗检验时，必须重新经过培训并获得能力与资格确认后才能承担主要检验任务。\n\n6.2.3.4 本公司将对上述人员当前工作的职责进行描述和授权，包括本岗位进行的职责；涉及检测工作及计划和结果评定职责；提出意见和解释的职责；方法改进、新方法制定、验证和确认方法的职责；报告、审查和批准结果的职责；\n\n本岗位所需的专业知识和经验；本岗位所需的资格和培训计划；本岗位的管理职责。\n\n6.2.4 技能的保持与提高\n\n6.2.4.1 本公司注重人才的培训、知识更新和素质的提高，以此作为不断改进工作质量的一种保证条件，并制定了《人员培训程序》。\n\n6.2.4.2 为了保持人员的能力，本公司制定了人才培训计划，确定培训需求及培训要达到的目标，培训计划需充分考虑岗位技能、知识更新的需要和当前业务的开展和未来发展的需要。\n\n6.2.4.3 实验室人员应接受有关检测方法、质量控制方法以及安全和防护、救护知识的培训，对于操作复杂分析仪器的人员还应接受仪器原理、操作和维护等方面知识的专门培训，掌握相关的知识和专业技能。当人员接受新的知识培训后，还应考核确认来评价培训的有效性，可通过能力验证、人员比对、操作考核及内部审核和外部评价来证明人员能力的提升。\n\n6.2.5 人员监督\n\n6.2.5.1 本公司确保长期使用合同制人员，应对其工作进行全面的监督，保证人员的能力能够胜任本岗位的工作，满足管理体系的要求。\n\n6.2.5.2 当使用在培人员时，应由相关部门和监督员对其能力进行适当的监督。\n\n6.2.5.3 技术负责人应定期组织评价各岗位人员的持续能力，并保存评价记录和授权记录。本公司的所有检测人员只有经过技术能力评价确认满足要求后才能授权其独立从事检测活动。\n\n6.2.6 人员技术档案\n\n资料管理员负责建立并保存所有人员的技术档案，应包括：人员档案登记表（含个人身份证明信息、工作经历、参加培训经历等）、岗位聘用书或任命书、技术证明资料、学历证书、培训证明材料。\n\n6.2.7 支持性文件\n\n《人员培训程序》 XZTC/CX-01-2018\n\n《人员管理程序》 XZTC/CX-01-02-2018\n',620,'现用文件/质量手册（第四版）.docx#6.2','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('70f6d155-ee8f-4bbc-af17-ede7d29ae9e1','00000000-0000-0000-0000-000000000001','3f002465-cdef-4e44-a37c-7aeaf5bd508d','f77b4435-116f-4c21-b9c3-c82afea7732d',NULL,'procedure:xztc_cx_08_2022:element:document_control','','要素落实：管理体系文件控制','control_requirement','### 要素落实：管理体系文件控制\n\n- 程序文件：XZTC/CX-08-2022 文件控制程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('713b02ad-b3dd-4bea-b91c-13aa5dc1d1c8','00000000-0000-0000-0000-000000000001','afb48a72-ca24-408e-86d1-685bc252a4a9','f5bfe2a1-1db8-49ca-8b36-6c8c9378a7fc',NULL,'procedure:xztc_cx_23_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 质量负责人应：\n\n3.1.1 负责组织允许偏离评审的工作；负责对允许偏离申请的批准；\n\n3.2 技术负责人应：\n\n3.2.1 负责允许偏离申请的审核；\n\n3.3 相关项目检测员应：\n\n3.3.1 负责提出允许偏离的申请。\n\n3.4 监督员应：\n\n3.4.1 负责监督方法偏离工作的过程。\n',140,'现用文件/程序文件/程序文件2022/23-2022允许方法偏离控制程序.docx#职责','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('71769405-961b-48e7-b7b0-8d8cb3e8d3c7','00000000-0000-0000-0000-000000000001','40055ae1-3a24-466a-b70a-78bb7c26362a','0cadf789-6c6b-4b36-a6fc-a797e4657a0f',NULL,'procedure:xztc_cx_19_2022:source:purpose','','目的','purpose','### 目的\n\n对记录进行控制和管理，提供满足质量要求的管理体系有效运行的客观证据，复现检测过程。\n',120,'现用文件/程序文件/程序文件2022/19-2022记录控制程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('73beb9e9-e838-47df-88fc-ac3f7adebf65','00000000-0000-0000-0000-000000000001','9f907214-fdff-400d-bd65-a376c631c875','619a08d7-264c-4a61-82aa-35e13cfa6e5d',NULL,'procedure:xztc_cx_07_2022:source:records','','记录','record_requirement','### 记录\n\n《检测公正性检查记录表》 XZTC/BG-07-01\n',170,'现用文件/程序文件/程序文件2022/07-2022确保公正性程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('73f34221-99a4-423a-b6c1-60cb5b4a5b27','00000000-0000-0000-0000-000000000001','69032715-7174-46fa-b564-18c838e80d23','1b4fd63c-d774-4713-8a57-1bcc9ea019f3',NULL,'procedure:xztc_cx_30_2022:overview','','检测结果质量控制及能力验证程序','section','# XZTC/CX-30-2022 检测结果质量控制及能力验证程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/30-2022检测结果质量控制及能力验证程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/30-2022检测结果质量控制及能力验证程序.docx','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('748cd382-6287-4752-a0db-879b686c9517','00000000-0000-0000-0000-000000000001','0298e975-ff58-4c04-b700-8e0cf4cd55d0','9f92ea6a-b554-401a-b1b5-c76269f78919',NULL,'procedure:xztc_cx_34_2022:overview','','内部监控管理程序','section','# XZTC/CX-34-2022 内部监控管理程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/34-2022内部监控管理程序.doc\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/34-2022内部监控管理程序.doc','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('74a19b9c-2cbc-4d8a-888a-9259ff183da2','00000000-0000-0000-0000-000000000001','bc8c7454-2b19-4837-aeb8-b3d9a1f13d25','30de644c-9b17-4536-86cf-18ad00d7b322',NULL,'procedure:xztc_cx_16_2022:overview','','实施纠正措施程序','section','# XZTC/CX-16-2022 实施纠正措施程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/16-2022实施纠正措施程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/16-2022实施纠正措施程序.docx','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('7645a6f9-4f00-4cec-b9e8-45dec04445da','00000000-0000-0000-0000-000000000001','7e5f11cb-e0dd-4d71-b0ba-357981f48045','7f87a99b-52a2-4b35-98d4-c4e17fc06bac',NULL,'procedure:xztc_cx_18_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 负责改进、纠正和预防措施的审批。\n\n3.2 质量负责人应:\n\n3.2.1 负责组织对质量管理体系、检测服务持续改进的策划，监督、协调措施的实施，并跟踪验证实施成果。\n\n3.3 监督员应：\n\n3.3.1 负责监督跟踪验证实施效果。\n\n3.4 各部门应：\n\n3.4.1 参与质量改进策划并负责实施与其相关的改进、纠正和预防措施。\n',140,'现用文件/程序文件/程序文件2022/18-2022改进控制程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('7a418abe-3c57-48aa-8470-3b0564815d5f','00000000-0000-0000-0000-000000000001','bd275009-ec1d-4a48-b6fc-39304fe0dee9','f488cefe-287f-47a2-b075-c5cd1cbcfa0b',NULL,'procedure:xztc_cx_17_2022:source:purpose','','目的','purpose','### 目的\n\n对管理体系或技术运作过程中的潜在的不符合，采取的预防措施，以实现管理体系的持续改进。\n',120,'现用文件/程序文件/程序文件2022/17-2022实施预防措施程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('7c666c3b-ad33-429e-b873-ca28c7d25435','00000000-0000-0000-0000-000000000001','c6a9947a-3e7f-4a66-b3d2-383348f9be03','534421f2-4307-4f6c-9df2-108bd6be4607',NULL,'procedure:xztc_cx_21_2022:source:scope','','范围','scope','### 范围\n\n适用于对本公司质量方针、目标和管理体系的适宜性、充分性和有效性的评审。\n',130,'现用文件/程序文件/程序文件2022/21-2022管理评审程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('7dbb26d2-c142-4fa5-a678-049059e170f2','00000000-0000-0000-0000-000000000001','3f002465-cdef-4e44-a37c-7aeaf5bd508d','f77b4435-116f-4c21-b9c3-c82afea7732d',NULL,'procedure:xztc_cx_08_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 批准《质量手册》《程序文件》和所有的作业指导书等重要的质量管理文件和本公司外发文件的签发、上级来文的批阅。\n\n3.2 质量负责人应：\n\n3.2.1 负责组织编制《质量手册》《程序文件》；\n\n3.2.2 负责《质量手册》各管理类程序文件的审核；\n\n3.2.3 负责批准管理类作业指导书；\n\n3.2.4 负责维护管理体系文件的有效性并组织对文件进行定期审查。\n\n3.3 技术负责人应：\n\n3.3.1 负责审核技术类程序文件批准技术作业指导文件和检验标准，规范的查新；\n\n3.4 办公室主任应：\n\n3.4.1 负责组织编制管理类作业指导书对其进行审核；\n\n3.5 监督员应：\n\n3.5.1 负责组织编制技术类作业指导书并对其进行审核；\n\n3.5.资料员\n\n3.5.1负责管理体系文件的发放和保管。\n\n3.6 其它：\n\n3.6.1 第四层次文件随其导出文件一起由相关人员编制、审核和批准。\n',140,'现用文件/程序文件/程序文件2022/08-2022文件控制程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('7feb2ee3-a0d4-4429-b166-0d09fc464c06','00000000-0000-0000-0000-000000000001','bd275009-ec1d-4a48-b6fc-39304fe0dee9','f488cefe-287f-47a2-b075-c5cd1cbcfa0b',NULL,'procedure:xztc_cx_17_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 负责重大预防措施的批准。\n\n3.2 技术负责人应：\n\n3.2.1 负责检测工作技术运作方面预防措施的评价和批准工作。\n\n3.3 质量负责人应：\n\n3.3.1 组织管理体系改进工作，负责管理体系运行过程中质量管理方面的预防措施的评价和批准工作。\n\n3.4 监督员应：\n\n3.4.1 负责预防措施实施的监督和跟踪验证。\n\n3.5 相关部门、岗位应：\n\n3.5.1 负责预防措施的制定和实施。\n',140,'现用文件/程序文件/程序文件2022/17-2022实施预防措施程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('81752063-5167-4119-a86f-175da98426b8','00000000-0000-0000-0000-000000000001','575be231-b422-4860-84b2-bcd28c6a6d7f','296ce497-e0aa-4f43-a7f0-0b59a7e6e6f8',NULL,'procedure:xztc_cx_15_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 不符合工作及其分类\n\n4.1.1 不符合工作\n\n在质量或技术活动中，不符合工作可能发生在不同的场所或过程，如检测过程质量控制、客户投诉 、服务和供应品验证、对员工考察或监督、仪器设备的校准、检测报告的核查、管理评审和内外部审核等；可能表现为对体系文件规定的偏离，可能直接或间接影响到报告的质量，以上均为不符合检测工作。\n\n4.2 识别\n\n4.2.1技术负责人、质量负责人、授权签字人、监督员和内审员负责对相关检测工作的环节和检测结果进行识别。内容可涉及以下各方面的工作：\n\n4.2.1.1人员操作的失误；\n\n4.2.1.2客户的投诉及有关信息反馈；\n\n4.2.1.3仪器设备的损坏或失效；\n\n4.2.1.4消耗材料质量的不合格；\n\n4.2.1.5环境条件的失控；\n\n4.2.1.6样品及其处理的不符合；\n\n4.2.1.7检测方法及选择存在的问题；\n\n4.2.1.8分包方工作的失误；\n\n4.2.1.9校准或溯源性的失控；\n\n4.2.1.10数据处理的差错；\n\n4.2.1.11原始记录的差错；\n\n4.2.1.12检测报告中的差错；\n\n4.2.1.13比对实验或能力验证中发现的问题；\n\n4.2.1.14质量控制中发现的问题；\n\n4.2.1.15内审、外审和管理评审中发现的问题等。\n\n4.2.2 各负责人员按照体系文件要求开展工作，发现不符合及时记录填写《不符合项处置通知表》，对不符合事实予以描述，并及时上报技术负责人。\n\n4.3 不符合工作的评价：\n\n4.3.1 当在各个环节中发现有不符合检测工作出现时，发现人员应将不符合内容记录于《不符合项处置通知表》中，并交由技术负责人对不符合检测工作的可接受性进行评价。\n\n4.3.2不符合工作的严重程度判定：\n\n⑴轻微：个别或少量偏离文件规定，对检测结果轻微影响，容易纠正；\n\n⑵中度：对多个部门或要素有影响，纠正时工作量较大；\n\n⑶严重：已涉及客户利益，实验室信誉和形象，质量方针、质量目标，难以纠正或纠正后仍不能完全消除其影响。\n\n4.4 不符合工作的处置：\n\n4.4.1质量负责人对不符合工作的处置做出决定。\n\n4.4.2对轻微的不符合，要求责任人或责任部门立即纠正，并检查纠正情况。提醒责任人或责任部门防止类似情况再次发生。\n\n4.4.3对中度的不符合，要求责任人或责任部门不但立即纠正，还应责成其采取纠正措施，防止类似情况再次发生。\n\n4.4.4对严重的不符合，公司要进行内审或管理评审，根据审核或评审情况采取纠正措施，改进管理体系，还要尽力消除对客户及其他相关方的影响。\n\n4.4.5在发生差异或偏离检测方法时，质量负责人应通知技术负责人处理。\n\n4.4.6责任部门负责对不符合工作采取恰当的行动予以纠正。纠正工作完成后应及时报告办公室。如需采取纠正措施，执行《实施纠正措施程序》、《实施预防措施程序》。\n\n4.5 验证\n\n4.5.1 技术负责人组织检测部经理和监督员对不符合工作纠正/纠正措施的有效性跟踪验证，证实所采取的纠正/纠正措施已消除了产生不符合工作的因素，通知相关部门恢复工作。\n\n4.5.2 内部审核中不符合项的跟踪验证，由质量负责人组织内审员实施。\n\n4.6 当对不符合的评价或跟踪验证表明不符合工作可能再发生时，必须按《实施纠正措施管理程序》执行。\n',150,'现用文件/程序文件/程序文件2022/15-2022不符合检测工作管理程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('81bb8d4e-648c-4c51-b182-1f7620efc203','00000000-0000-0000-0000-000000000001','ddbdafda-6b10-4c15-bd38-6c64672f57d1','4b70f485-3633-4627-be9b-28114a44e2a7',NULL,'procedure:xztc_cx_22_2022:source:records','','记录','record_requirement','### 记录\n\n《非标准方法确认评审表》 XZTC/BG-22-01\n\n《标准方法确认记录》 XZTC/BG-22-02\n\n《现行有效标准清单》 XZTC/BG-22-03\n',170,'现用文件/程序文件/程序文件2022/22-2022检测方法的选择与确认程序.docx#记录','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('81d5bd84-28b2-4c7e-b3ac-bd3bfeef54ac','00000000-0000-0000-0000-000000000001','45f6ba8e-a58b-4ca6-b52e-b35fadc1330d',NULL,NULL,'external_basis:cnas_cl01_2018:overview','','检测和校准实验室能力认可准则','section','# CNAS-CL01:2018 检测和校准实验室能力认可准则\n\n- 来源类型：external_standard\n- 版本：2018（2019-02-20第一次修订）\n- 实施日期：2018-09-01\n- 查新状态：due\n- 查新日期：2026-07-19\n- 查新结论：本地正式依据文件缺失\n- 查新证据：参考/2025年最新版CMA和CNAS质量体系/04-CNAS-CL01 检测和校准实验室能力认可准则 2018 年 09 月 01 日实施.pdf\n- 下次查新：2027-07-19\n- 归档文件：参考/2025年最新版CMA和CNAS质量体系/04-CNAS-CL01 检测和校准实验室能力认可准则 2018 年 09 月 01 日实施.pdf\n- 正式条款数：0\n',100,'参考/2025年最新版CMA和CNAS质量体系/04-CNAS-CL01 检测和校准实验室能力认可准则 2018 年 09 月 01 日实施.pdf','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('820d8cfb-3e61-44a5-8dab-1dad07d15afb','00000000-0000-0000-0000-000000000001','d1d75375-586e-4570-a58b-afb6e06daac5','82cfd29e-aa37-423c-af0a-375007e365f7',NULL,'procedure:xztc_cx_32_2022:element:risk_opportunity','','要素落实：风险和机遇','control_requirement','### 要素落实：风险和机遇\n\n- 程序文件：XZTC/CX-32-2022 风险评估控制程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('82d96bc2-c6b5-479f-8f83-0ce27c7001fa','00000000-0000-0000-0000-000000000001','f9f936aa-4e68-449e-a6bc-814098b9b434','f6b1b203-1e7a-48e5-953a-c9de0ae2969d',NULL,'procedure:xztc_cx_07_02_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1质量负责人负责制定本公司防止商业贿赂的程序。\n\n3.2办公室负责防止商业贿赂程序的实施。\n\n3.3实验室主任负责组织防止商业贿赂、廉洁技术服务的学习和培训。本公司所有工作人员均须参加培训学习。\n\n3.4各部门负责人负责本部门防止商业贿赂的监督和管理。\n\n3.5办公室负责防止商业贿赂的监督管理。\n',140,'现用文件/程序文件/程序文件2022/07-02-2022防止商业贿赂程序.doc#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('8311f046-fff5-404f-90bf-bc7c463af4a8','00000000-0000-0000-0000-000000000001','71ac64b2-e042-4afc-aacc-a1b8f9d5b18c','b61891de-34e0-475d-aa81-5f55a84285ec',NULL,'procedure:xztc_cx_04_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 期间核查计划\n\n4.1.1 为能有针对性地开展期间核查活动，每年应制定期间核查计划，其计划的内容可包括：\n\n4.1.1.1 计划期间核查时间；\n\n4.1.1.2 针对不同的设备和标准物质确定核查频次；\n\n4.1.1.3 需进行核查的仪器设备和标准物质；\n\n4.1.1.4 期间核查方法。\n\n4.1.2 设备管理员编制《仪器设备和标准物质期间核查计划表》，由技术负责人审核、实验室主任批准。\n\n4.2 核查仪器设备和标准物质的选择\n\n4.2.1 使用频率高、漂移性较大的仪器设备；\n\n4.2.2 仪器设备在使用中，有可疑现象出现；\n\n仪器设备和标准物质期间核查程序\n\n4.2.4 使用周期较长或性能容易发生变化的标准物质列入核查范围；\n\n4.2.5 经常携带到现场检测以及在恶劣环境下使用的仪器设备。\n\n4.3 期间核查方案\n\n4.3.1 根据期间核查计划的内容，实施计划前，应对具体的各类仪器设备分别编制仪器设备和标准物质期间核查方案，方案内容包括：\n\n4.3.1.1 仪器设备和标准物质名称、型号及设备管理编号；\n\n4.3.1.2 参加设备核查人员、时间；\n\n4.3.1.3 采用的核查方法；\n\n4.3.1.4 该设备检定周期时间；\n\n4.3.2 应有相关文件及记录（标准规范、作业指导书等）。\n\n4.3.3 设备管理员编制《仪器设备和标准物质期间核查方案》，由技术负责人审核、实验室主任批准。\n\n4.4 期间核查作业指导书\n\n4.4.1 实施期间核查前，应针对不同的仪器设备和标准物质，选用核查方法，编制相应的期间核查作业指导书。作业指导书的内容包括以下主要内容：\n\n4.4.1.1 仪器设备和标准物质名称、型号；\n\n4.4.1.2 选用的核查方法（平均值法、比对法等）；\n\n4.4.1.3 根据核查方法确定核查标准；\n\n4.4.1.4 选择检测点及确定检测线；\n\n4.4.1.5 明确核查判定准则；\n\n4.4.1.6 规定核查设施环境条件、相关记录及数据处理方法。\n\n4.4.2 期间核查作业指导书应经技术负责人批准。\n\n4.5 使用技术手段进行仪器设备和标准物质期间核查的方法可以是以下五种之一:\n\n4.5.1 参加实验室间比对；\n\n4.5.2 使用有证标准物质；\n\n4.5.3 与相同准确等级的另一个设备和标准物质或几个设备和标准物质的量值进行比较；\n\n4.5.4 对稳定的被测件的量值重新测定（即利用核查标准进行期间核查）；\n\n4.5.5 在资源允许的情况下，可以进行高等级的自校。\n\n4.6 期间核查人员\n\n仪器设备和标准物质期间核查程序\n\n4.6.1 期间核查人员应是对仪器设备和标准物质较为熟悉，具有一定的专业能力。 4.7期间核查的实施\n\n4.7.1 技术负责人组织设备管理员及检测室相关人员实施期间核查，设备管理员填写《仪器设备和标准物质期间核查记录表》。\n\n4.8 纠正措施\n\n4.8.1 当核查期间出现某仪器设备核查判定不合格时，检测部应组织相关人员按《不符合检测工作管理程序》、《实施纠正措施程序》的要求，分析原因，及时采取纠正措施。\n\n4.9 核查资料管理\n\n4.9.1 核查期间的各类文件、记录应由设备管理员整理后，列入设备管理统一归档管理。\n',150,'现用文件/程序文件/程序文件2022/04-2022仪器设备和标准物质期间核查程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('83688cfa-06ac-400a-8690-01e4a0ecf3dd','00000000-0000-0000-0000-000000000001','1e1e9194-f520-4a67-91ab-d313500615c8','e12e3730-cc7a-4ade-8704-2460e6762097',NULL,'procedure:xztc_cx_02_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 质量负责人应：\n\n3.1.1 负责审核环境设施的配置、改造或维修报告；\n\n3.2 技术负责人应：\n\n3.2.1 负责编制、提出设施和环境要求，对其实施控制管理；\n\n3.2.2 主持设备和环境条件的管理，需要时组织制定设施环境配置计划；\n\n3.2.3 负责设施环境的监督、监控记录的管理；\n\n3.2.4 负责组织设施的安装和维修。\n\n3.3 检测人员应：\n\n3.3.1 负责环境设施的正确使用、维护、监测、控制并做相关记录。\n',140,'现用文件/程序文件/程序文件2022/02-2022设施与环境条件控制和维护程序.docx#职责','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('83e5d99f-3de5-48cc-b586-c16310fbe73f','00000000-0000-0000-0000-000000000001','43c73354-2b49-458e-b110-281f4f7db028','b835ad93-cc81-40b1-8e88-266b4fe4424e',NULL,'procedure:xztc_cx_01_2022:overview','','人员培训程序','section','# XZTC/CX-01-2022 人员培训程序\n\n- 原始文件：现用文件/程序文件/程序文件2022/01-2022人员培训程序.docx\n- 文件类型：程序文件\n- Markdown结构：按目的、范围、职责、控制要求和记录要求拆分为独立章节块。\n- 块级追溯：每个内容块可独立关联条款、要素、岗位、记录表格和运行模块。\n',100,'现用文件/程序文件/程序文件2022/01-2022人员培训程序.docx','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('84b0cfc0-1240-4f69-b35f-4445cf240fd6','00000000-0000-0000-0000-000000000001','b3f4c46e-f363-44f3-86f5-4d207df828ef','a3a3bc75-4867-43ee-af53-ba1e1745ecbe',NULL,'procedure:xztc_cx_26_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 办公室主任应对本公司用于检测工作的计算机及其自动化设备，检测用计算机软件，保密电子信息实行统一管理。\n\n4.1.1 检测人员在工作前后应检查计算机和自动化设备状态是否正常，软件运行是否正常，如有异常现象应停止工作并采取必要的措施。出现工作异常现象的计算机和自动化设备应验证无误后方可使用。\n\n4.1.2 计算机开机启动后检测人员应严格按照操作规程进行操作，完成检测工作。\n\n4.1.3 检测人员在操作计算机进行检测工作时，应对输入的数据进行检查确认，确保数据输入的准确性；同时，对计算机采取的数据进行检查，确保采集的完整性。\n\n4.2 计算机软件和网络文件的编辑、验证和变更；\n\n4.2.1 经安装调试合格后的计算机系统，应由办公室主任统一管理，并按工作的性质把访问权限分配给相应的岗位人员。\n\n4.2.2 未经技术负责人批准，不得随意安装使用未经许可的软件，不得随意调整、变更各类检测软件和网络文件。当需要变更时，应填写《计算机内容变更申请表》，技术负责人审批后实施。\n\n4.3 数据换算、校对与处理；\n\n4.3.1 计算机及其自动化设备采集、换算的数据首先有检测员进行认真检查，然后由校对人员进行校对，并在电子记录中进行人员标识。如果可能时，采用人工计算的结果与计算机所得的结果进行数据比对，如果比对有误差，及时找出原因，作出相应调整。\n\n4.3.2 检测人员应对采集到的原始数据进行处理。数据处理应首先确认使用的物理常数、数字表、计算公式、图表和曲线等。数据计算时应遵循先修约后计算的原则。\n\n4.4 计算机文件和数据的更改；\n\n4.4.1 对只保留在计算机中的文件和数据应设立访问密码，并作为只读文件，未经批准不得修改，如果需要修改应经相关授权人员书面批准，并留有记录。\n\n4.5 软件和信息的保存；\n\n4.5.1 文件和数据的保存\n\n4.5.1.1 计算机使用者应对计算机中的重要文件和检测数据逐日进行备份，以保证文件和数据的安全性。当备份或拷贝完成后，应检查其正确性和完整性；\n\n4.5.1.2 对保密的数据和文件（如原始记录、检测报告、合同等），应以加密的方法进行保存；\n\n4.5.1.3 使用计算机进行数据处理时，计算机第一次运行的结果必须进行手工复核存档，以验证程序的正确性，对第一次打印出来的结果文件应作为原始档案进行归档，保证数据修订的可追溯性。复验检测数据时，如数据库数据与档案中数据不一致时，应以归档的检验数据为准。\n\n4.5.1.4 计算机使用者应将存有数据和文件的光盘或软盘交综合组归档，资料员应对其进行登记签收，按《文件控制程序》实施；\n\n4.5.1.5 资料管理员应对归档的光盘或软盘的保密性和安全性负责。\n\n4.5.2 软件的保管\n\n4.5.2.1 本公司使用的软件应定期由技术负责人组织软件功能的检查，如发现问题，及时更换软件，保障检测工作的进行；\n\n4.5.2.2 对于技术性数据处理的计算机软件（含说明书）安装使用后，由办公室统一保存填写《计算机软件登记表》归档。如果需要重新安装使用该软件，需经技术负责人同意后在资料员处登记借出。\n\n4.5.2.3 对于其他通用商业计算机软件的使用由办公室主任统一安装管理，填写计算机文件及数据控制程序\n\n《计算机软件登记表》，如需重新安装使用向资料员借用。\n\n4.6 计算机网络和自动化设备的维护与管理\n\n4.6.1 计算机及其自动化采集装置，计算的数据由技术负责人定期组织经行核对。核对的方法是人工计算的结果与计算机所得的结果进行数据比对，并做好记录。如果比对有误差，及时找出原因，做出相应调整。\n\n4.6.2 办公室主任应定期组织对计算机信息系统安全运行情况进行检查测试，及时排除各种安全隐患，防止信息被非法删除、修订、或复制。\n\n4.6.3 使用外来软件时，应交办公室主任进行鉴别。鉴别内容包括：是否存在对本公司信息系统的安全造成影响，是否适用于本公司工作。\n\n4.6.4 当计算机信息系统或自动化设备出现问题时，办公室主任应及时组织清除故障。当问题无法解决时，应及时同维修商联系。\n\n4.6.5 办公室主任负责统一安装防病毒软件，操作人员及时升级杀病毒。\n\n4.7 数据的检索\n\n4.7.1 对于尚未归档的电子数据和报告的检索，由实验室主任或指定人员负责；对归档的所有电子数据和报告的检索，都必须经实验室主任批准，由资料员负责进行管理\n\n4.8 计算机设备及其软件保存的环境\n\n4.8.1 计算机及其自动设备应保证在相对干燥、常温、无烟尘、无强大磁场干扰、无辐射、防止静电、不间断电流和相对安静的条件下运行。\n\n4.8.2 计算机软件及检测资料存档记录光盘或软盘应保证在相对干燥、常温、无烟尘、无强大磁场干扰、无辐射、防止静电的条件下储存。\n\n4.9.电子签名的控制管理及使用\n\n4.9.1 对公司使用实验室信息管理系统过程中所涉及电子签名的制作、储存和管理使用，由实验室主任统一协调负责，电子签名使用者和质量负责人进行监督。其中，由电子签名拟使用者明确使用范围并提出申请，经公司法人、最高管理者、技术负责人、质量负责人共同进行审批，审批同意后由实验室主任递交相应材料交由信息管理系统供应商进行制作并储存，制作完成后实验室主任负责在电子签名使用者的监督下销毁留存于实验室的相应纸质材料及电子材料，供应商将电子签名的使用权限仅绑定于使用者个人的操作账号。\n\n4.9.2 制作完成后的电子签名应独立贮存于供应商及其所提供的系统中，后续所 有可能发生的变更必须由电子签名使用者、公司法人、最高管理者、技术计算机文件及数据控制程序\n\n负责人、质量负责人共同进行审批，审批同意后由实验室主任协调联系供应商进行修改，电子签名使用者和质量负责人核对变更结果。\n\n4.9.3 电子签名在系统中应规定明确的使用范围并进行有效限制，使用者须定期更换操作账号的密码并妥善保管，还须配合质量负责人对电子签名的使用情况（包括不限于签字时间、签字领域、授权账号等信息）进行核实和检查，确保其真实性。\n\n4.9.4 电子签名的使用者应知悉其满足上述条件的电子签名与手写签名具备同等的法律效力，在使用时，表示其同意、认可、并愿意承担相应的责任和义务。且应对此进行声明，确保其有效性。\n',150,'现用文件/程序文件/程序文件2022/26-2022计算机文件及数据控制程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('86ddf7b7-6a8b-43b4-aaed-15845123290c','00000000-0000-0000-0000-000000000001','684b63da-4e5d-4436-bd6f-95cd011fd70d','bbf06eea-34a2-451e-9ac6-88cf92290425',NULL,'procedure:xztc_cx_01_02_2022:source:records','','记录','record_requirement','### 记录\n\n(1)《人员培训记录表》 XZTC/BG-01-02\n\n(2)《检测人员持证登记表》 XZTC/BG-01-03\n\n(3)《人员考核记录表》 XZTC/BG-01-04\n\n(4)《人员档案登记表》 XZTC/BG-01-07\n',170,'现用文件/程序文件/程序文件2022/01-02-2022人员管理程序.docx#记录','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('86eaf0a6-70cb-4ecb-8178-7c1775410ad6','00000000-0000-0000-0000-000000000001','76ffd146-ed11-4da9-a42a-c1ef8787db95','a64ffdaa-5ea0-412e-b076-f9c0c9283c85',NULL,'procedure:xztc_cx_29_2022:source:purpose','','目的','purpose','### 目的\n\n确保本公司客观、准确、清晰、完整的出具检测报告，对报告的规范性、编制、应涵盖的信息、签发、存档等各个环节实施有效的质量监控。\n',120,'现用文件/程序文件/程序文件2022/29-2022结果报告管理程序.docx#目的','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('86f8a02e-a043-4390-bccf-cbbf6aadfffb','00000000-0000-0000-0000-000000000001','344d5310-653c-4a9f-9199-8b2065c15849','110bbfd1-2758-4d2b-8ccf-07be4434138f',NULL,'procedure:xztc_cx_12_2022:source:scope','','范围','scope','### 范围\n\n适用于客户对检测工作有关操作的监视，技术支持及客户信息的反馈活动。\n',130,'现用文件/程序文件/程序文件2022/12-2022服务客户程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('87628bf3-86d7-4d45-bff3-f0637ed83fc2','00000000-0000-0000-0000-000000000001','27593939-ac0b-4de4-8378-23dc8ca73c80','f59f024b-b5bf-4c6a-8911-a8cf2cdccac1',NULL,'manual:7_4','7.4','检测样品的处置','section','## 7.4 检测样品的处置\n\n7.4.1 对样品的运输、接收、标识、流转、存储、保留和清理各环节实施控制管理，保证其代表性、有效性和完整性，以确保检测结果的科学、准确。针对样品的运输、接收、发放、标识、流转、保护、储存、保留及处理的控制，制定了《样品处置和管理程序》。\n\n7.4.2 本公司建立了样品标识系统，任何样品都必须按此系统进行编号，并且确保样品编号的唯一性，且应与检验报告或鉴定证书有一一对应关系。该系统的启动可确保样品唯一标识保持检测全过程（包括实物和记录），本公司的样品编号规则为：\n\n公司代码Z+年份后两位数字+月份+5位数字编码，例如乌鲁木齐2018年5月份编号为Z200500001～Z200599999。\n\n7.4.3 样品的标识确保不会在实物及记录和其他文件中混淆，具有唯一性以实现追溯，必要时标明其“待检”“在检”“完检”“留样”的状态。同时对群组样品进行必要的标识细分。\n\n7.4.4 在样品的交接过程中，实验室应对样品的特征予以详细地记录并得到双方的确认。在样品接收、移交过程中，如发现样品异常、与规定条件的偏离、样品与委托内容不符、委托要求不明确或不详尽、对样品的适用性持有怀疑时，应及时记录，并向委托方提出，取得进一步明确的说明，形成文件，并由委托方确认。当客户知道偏离了规定条件仍要求进行检测时，实验室应在报告中作出免责声明，并指出偏离可能影响的结果。\n\n7.4.5 样品流转过程中，有关人员应检查确认样品标识，接收者应遵守样品的使用说明，对样品加以保护，避免非正常损坏或丢失。\n\n7.4.6 样品的保管应具备适当的设施和环境条件及安全措施，应分类定位存放，以防止样品损坏、丢失和混淆的发生，保证其安全防护要求的实现，保证样品状态的完好；当样品需要存放在规定的环境条件下存放时，按其规定进行维 持、监控和记录这些条件。\n\n7.4.7 完成检测的样品由检测人员交还给样品管理员。如样品无需退还给客户时，由样品管理员清理出现场。\n\n7.4.8 按《保护客户机密信息程序》的规定和委托要求，对客户的样品和有关资料信息予以保密，必要时，制定相应的保密措施控制实施。\n\n7.4.9 实验室应有严格的保安措施，尽量缩短高价值样品的检验和保存时间。\n\n7.4.10 支持性文件\n\n《保护客户机密信息程序》 XZTC/CX-06-2018\n\n《样品处置和管理程序》 XZTC/CX-28-2018\n',740,'现用文件/质量手册（第四版）.docx#7.4','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('87a3bb9f-12fc-4a4a-ba01-0e4bae26836f','00000000-0000-0000-0000-000000000001','3f002465-cdef-4e44-a37c-7aeaf5bd508d','f77b4435-116f-4c21-b9c3-c82afea7732d',NULL,'procedure:xztc_cx_08_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《保护客户机密信息程序》 XZTC/CX-06-2022\n\n《记录控制程序》 XZTC/CX-19-2022\n\n《计算机文件及数据控制程序》 XZTC/CX-26-2022\n',160,'现用文件/程序文件/程序文件2022/08-2022文件控制程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('88066806-654b-4241-b0b9-fbf590b7cea8','00000000-0000-0000-0000-000000000001','c6a9947a-3e7f-4a66-b3d2-383348f9be03','534421f2-4307-4f6c-9df2-108bd6be4607',NULL,'procedure:xztc_cx_21_2022:source:purpose','','目的','purpose','### 目的\n\n通过对本公司管理体系和检测活动的现状进行评审，寻求改进的机会，以确保质量方针、目标、管理体系和检测活动的持续适用和有效，以满足社会和客户的期望，提高竞争和发展能力。\n',120,'现用文件/程序文件/程序文件2022/21-2022管理评审程序.docx#目的','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('894c7b18-362d-42ff-b9ee-3a876c1c1aa9','00000000-0000-0000-0000-000000000001','1e1e9194-f520-4a67-91ab-d313500615c8','e12e3730-cc7a-4ade-8704-2460e6762097',NULL,'procedure:xztc_cx_02_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司检测工作所涉及的设施和环境条件的控制，包括室外工作场所和样品存放场所的管理。\n',130,'现用文件/程序文件/程序文件2022/02-2022设施与环境条件控制和维护程序.docx#范围','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('89da342f-3ea0-45b5-b3c8-905a1c6b9a9c','00000000-0000-0000-0000-000000000001','9d510096-db76-494b-af6a-0346649008e6','85c08c02-e477-43d9-8b8a-185fa6d8912b',NULL,'procedure:xztc_cx_28_2022:source:scope','','范围','scope','### 范围\n\n适用于本公司开展各项检测业务中所涉及的样品管理工作。\n',130,'现用文件/程序文件/程序文件2022/28-2022样品处置和管理程序.docx#范围','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('8a308a55-7e60-43d7-958a-2a853d385527','00000000-0000-0000-0000-000000000001','25bc5721-9452-4aa9-a626-0262a1bb1ee4','36ac3d04-2b8c-435e-a334-26a97ebfa4ad',NULL,'procedure:xztc_cx_03_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 仪器设备的配置\n\n本公司根据检测项目所依据的检测配置相应的检测设备，以确保检测设备及\n\n其软件达到相应的准确要求，设备购置按《外部支持服务和供应品管理程序》。\n\n4.1.1 检测员提出仪器设备的配置要求，填写《仪器设备购置申请表》，报技术负责人审核。\n\n4.1.2 技术负责人对配置申请进行审核确认后，报实验室主任批准。实验室主任应根据技术负责人提出的要求和提供的供货厂商制定出购置计划。\n\n4.1.3 办公室负责组织采购、安装调试，技术负责人负责验收，填写《购入仪器设备验收记录》。\n\n4.1.4 设备管理员建立本公司所有《仪器设备台账》，其中须列明设备名称、管理编号、出厂编号、生产厂家、规格型号、技术指标(如测量范围、允许误差\n\n极限或不确定度或准确度等级、稳定性、分辨率)、责任人等，以便统一管理。\n\n4.1 仪器设备购置及验收\n\n4.1.1本公司根据检测标准的要求配置了合适的检测设备，设置的购置按《外部支持服务和供应品管理程序》执行。\n\n4.1.2检测部经理组织对仪器设备进行验收，验收包括以下内容：\n\na.包装是否完好；\n\nb.仪器的状态是否完好；\n\nc.主机、附件、随机清单与装箱单是否一致；\n\nd.使用说明书、合格证等技术资料是否齐全；\n\ne.是否满足采购合同规定的技术要求；\n\nf.根据检测标准、校准规化、使用说明书等文件对仪器的性能及技术指标进行验证。\n\n4.2 仪器设备的标识\n\n对于检测结果有影响的仪器设备应有唯一标识，仪器设备的状态标识分为“合格”、“准用”、“停用”三种，通常以“绿”、“黄”“红”三种颜色表示，其中应包括必要的信息，如检定/校准日期、有效期、设备管理编号、检定/校准单位等。\n\n4.2.1 合格证（绿色）\n\n经计量检定或校准、验收合格，确认其符合检测技术规范规定的使用要求的。\n\n4.2.2 准用证（黄色）\n\n仪器设备存在部分缺陷，但在限定范围内可以使用的（即受限使用的），包括：\n\n4.2.2.1 多功能检测设备，某些功能已丧失，但检测工作所用某项功能正常，且经检定/校准合格者；\n\n4.2.2.2 测试设备某一量程精度不合格,但检测某项工作所用量程合格者；\n\n4.2.2.3 降级后使用的仪器设备；\n\n4.2.2.4 设备不需检定，作为非计量工具使用。\n\n4.2.3 停用证（红色）\n\n停用须经技术负责人批准，停用设备包括：\n\n4.2.3.1 检测仪器设备经计量检定/校准不合格者；\n\n4.2.3.2 检测仪器设备损坏者；\n\n4.2.3.3 检测仪器设备性能无法确定者；\n\n4.2.3.4 检测仪器设备超过检定周期者；\n\n4.2.3.5 检测仪器设备不符合检测技术规范规定的使用要求者。\n\n4.2.2.4对贴有停用证（红色标志）的仪器设备禁止使用，对贴有准用证（黄色标志）的仪器设备只能使用其正常的功能部分。对没有使用（1个月以上）的仪器设备，技术性能、指标达到规定要求的设备，经技术负责人批准可进行封存，并填写《仪器设备封存记录》。\n\n4.2.3 唯一性标识\n\n设备员应对所有检测设备及软件进行唯一性标识，以区别其它仪器设备、软件。\n\n4.2.4 标识管理\n\n4.2.4.1设备员负责对每台设备进行标识及标识，并应定期检查标识是否完好；\n\n4.2.4.2 标识应粘贴于仪器设备明显位置处，如发现标识有脱落、损坏、墨迹不清时应立即重新标识。\n\n4.3 仪器设备的使用\n\n4.3.1 设备在投入使用前，应进行检定（校准），未经检定（校准）的设备不得投入使用。设备管理员负责及时更新所得的修正因子。设备的检定（校准）详见《实现测量可溯源性程序》。禁止对仪器设备的随意调整（包括硬件和软件的保护）致使检测结果的失效。\n\n4.3.2 设备应由经过授权的检测人员操作。操作者应经过培训，详细了解设备最新版本的使用说明书、技术资料内容，熟练掌握设备的性能和操作程序后，方可上机操作，并按规定要求填写《仪器设备使用记录表》，特殊设备的操作人员应持证上岗。禁止对仪器设备的随意调整（包括硬件和软件的保护）致使检测结果失效。\n\n4.3.3 对容易引起误操作及重要的操作过程，由技术负责人组织编制操作规程，经实验室主任批准实施。\n\n4.3.4 检测人员在使用设备前后，应对该设备进行核查和校准，包括对运行情况的记录和现行状态的检查，保证设备及其软件应达到要求的准确度，并符合规范标准的要求。\n\n4.3.5 操作过程中如发生过载、误用、故障或对设备性能有怀疑时，应立即停止使用，报设备管理员处置，防止误用。同时，检测组应核查这些缺陷或偏\n\n离对以前检测质量的影响，按《不符合检测工作管理程序》评价其性质及采取措施。\n\n4.3.6 对于使用频率高、漂移性较大的设备，应在两次检定（校准）期间内进行期间核查，确保其工作状态符合要求。检测是按计划实施，并记录其过程结果，详见《仪器设备和标准物质期间的核查程序》。\n\n4.3.7 设备的日常保养由指定操作人员负责进行，按使用说明书和管理要求，实施维护保养及功能性检查并填写《仪器设备保养、维护记录表》。\n\n4.4 仪器设备的租(借)入和租（借）出和现场检测设备的管理\n\n因检测需要向其他实验室租（借）进的设备或脱离了本公司直接控制的租（借）\n\n出的设备须满足本程序以下要求。\n\n4.4.1 租（借）入\n\n4.4.1.1 由需用部门提出申请，说明所需设备的技术指标性能要求；\n\n4.4.1.2 技术负责人负责联系租（借）设备单位，报实验室主任审批后办理有关借入手续；\n\n4.4.1.3 设备管理员负责对借入的设备的功能进行核查与确认，以确保其显示出满意的结果，如果设备的校准状态显示其已过期或没有检定/校准，设备管理员必须要按《量值溯源管理程序》组织对其进行检定/校准，并确认合格后方可投入使用。\n\n4.4.2 租（借）出\n\n4.4.2.2.1 设备的租（借）出需经实验室主任批准，由技术负责人与租（借）方商定协议（合同），明确双方的责任义务，报实验室主任审批；\n\n4.4.2.2.2 设备返还后，设备管理员组织有关人员对设备的功能进行核查，并填写《仪器设备调试验收记录表》，必要时应重新检定（校准）。\n\n4.5 仪器设备的修理、降级和报废\n\n4.5.1 修理\n\n4.5.1.1 需计划维修的设备，使用部门提出申请填写《仪器设备维修申报表》报设备管理员，经技术负责人审核后报实验室主任批准后进行。\n\n4.5.1.2 维修应由专业技术人员实施，外委应执行《外部支持服务和供应品管理程序》；\n\n4.5.1.3 由设备管理员组织有关人员对修复后的设备验收，检查其技术性能指标是否符合要求，设备管理员按时填写《仪器设备调试验收记录》。如需检定或校准按《实现测量可溯源程序》规定批行。\n\n4.5.2 降级\n\n4.5.2.1 设备的准确度、灵敏度、稳定性等达不到原来规定值，但可满足对精度要求较低检测项目的技术指标时，经计量检定确认后，该设备可降级使用；\n\n4.5.2.2 设备的降级使用需经技术负责人审核、技术负责人的确认，经实验室主任批准方可使用。\n\n4.5.2.3 由设备管理员将降级设备的具体情况记入《仪器设备降级使用评定表》中，存档备案。\n\n4.5.3 报废\n\n4.5.3.1 对于不能修复或已失去使用价值的设备，,由设备管理员提交《仪器设备报废申请表》，经技术负责人审核后，交实验室主任批准；\n\n4.5.3.2 设备管理员负责报废设备的处置。\n\n4.6 仪器设备记录及档案\n\n4.6.1 设备及其软件的各种记录、资料统一由设备管理员归档管理，其中仪器设备操作规程、使用、维护记录等应保存在使用现场，便于取用。\n\n4.6.2 设备管理员负责建立本公司《仪器设备台帐》，统一编号、标识进行管理。\n\n4.6.3 设备管理员负责建立主要仪器设备及其软件的档案，其内容应包括：\n\n4.6.3.1 设备情况登记表，如设备、软件及厂家的名称，管理编号，规格型号，出厂编号等其他唯一性标识的记录；\n\n4.6.3.2 仪器设备产品合格证；\n\n4.6.3.3 仪器设备使用说明书原件；\n\n4.6.3.4 安装、调试记录及验收过程的其他文件；\n\n4.6.3.5 操作规程、自校规程、期间核查规程、计划及记录；\n\n4.6.3.6 校准证书（或计量检定证书、测试证书、自校报告）；\n\n4.6.3.7仪器设备维护保养计划；\n\n4.6.3.7 仪器设备维护保养方面的记录；\n\n4.6.3.8 仪器设备的任何损坏、故障、维修记录；\n\n4.7设备使用和维护后，特别是设备脱离了实验室直接控制，技术负责人应确保仪器设备功能正常，防止其污染或性能退化并对其校准状态核查直至显示满意结果。\n\n4.8仪器设备的量值溯源\n\n4.8.1 国家依法管理的计量器具，由法定计量检定机构或授权机构检定或有校准\n\n资格的机构校准。\n\n4.8.2无法检定的仪器，公司编写校准方法自行校准或与其他实验室进行比对。\n\n4.8.3新购置的仪器设备在投入使用前应进行检定/校准。\n\n4.8.4必要时进行期间核查。\n\n4.8.5应使用国家有证标准物质。\n\n4.8.6 参考标准不得用于非检定/校准目的。\n\n4.8.7对仪器设备校准，要绘制能溯源到国家计量基准的量值溯源框图，并需评定测量不确定度。\n\n4.8.8 按检测方法的要求建立校准曲线。所用标样要覆盖被测样品的浓度范围，最低浓度的标样应在接近检测方法报告限的水平。对非线性校准函数，要有更多的校准标样。如适用，应使用插入法技术\n\n4.8.9 在分析过程中，定期使用中间点的校准标样检查校准曲线。\n\n4.8.10 仪器设备的检定/校准（验证）和确认的总体计划（总体要求）\n\n① 凡列入国家依法管理计量器具目录的工作计量器具均送法定计量技术机构或授权机构进行检定。参考标准、参考物质按计划依法实施强制检定。\n\n② 专用测量仪器送有资格的外部校准机构校准或本公司自行校准。\n\n③ 对无法溯源到国家计量基准的仪器通过实验室间比对试验或采用标准物质或标准样品证实其可信度。\n\n④ 对非计量器具但有量值控制要求的设备由本公司进行检查。\n\n总体计划要根据情况及时进行调整。\n\n4.8.11仪器设备的周期检定/校准\n\n4.8.11.1 仪器设备管理员根据总体计划 编制仪器设备的年度周期检定/校准计划,该计划包括仪器设备名称， 编号，检定/校准周期，上次检定/校准日期，下次检定/校准日期，检定/校准单位或部门，仪器设备保管人，送检人等信息。\n\n4.8.11.2 仪器设备管理员负责按计划将依法管理的计量器具、参考标准、标准物质送检定或校准,检定合格后更换标识,将证书/报告复印一份,原件存档,复印件放入仪器设备盒中。\n\n4.8.11.3校准结果需要经过确认，对是否符合标准、规范要求做出判定。对校准产生的修正值或修正因子,须将其标识在显著的地方,以引起使用人员的注意。原有修正值或修正因子需更新。\n\n4.8.11.4 检测人员负责按计划将专用计量器具、无法溯源的仪器分别进行自校准或开展比对，校准或比对的结果应形成记录，记录的管理方法与检定证书相同。\n\n4.8.11.5 检测人员不得使用未经检定/校准的，或已超过有效期的，或不合格的仪器设备。监督员负责监督仪器设备的正确使用，仪器设备管理员负责标识、\n\n收回或隔离、封闭不符合要求的仪器设备。\n\n4.8.11.6 开展自校准的条件包括：\n\n⑴有经过培训考核合格的校准人员；\n\n⑵有进行校准的参考标准或有证标准物质；\n\n⑶校准方法编制成文件并经批准发布；\n\n⑷有合适的校准环境条件\n\n⑸有参考标准的管理制度。\n\n4.8.12期间核查\n\n4.8.12.1期间核查的范围\n\n⑴量值易发生变化的仪器设备；\n\n⑵使用频次特别高或环境条件恶劣的仪器设备；\n\n⑶量值可疑的仪器设备；\n\n⑷标准物质。\n\n4.8.12.2 期间核查的目的\n\n检查仪器设备和标准物质的稳定性和可靠性。\n\n4.8.12.3期间核查的方法\n\n采用核查标准。核查标准可以是：\n\n⑴高一精度等级的仪器设备或标准物质；\n\n⑵同精度等级但稳定性好的仪器设备；\n\n⑶一个稳定可靠的被测样品；\n\n⑷一个理论值或已知的参数。\n\n4.8.12.4期间核查的时机和计划\n\n在仪器设备校准后即进行第一次核查，以后每隔一定时间进行后续核查。每种仪器设备、核查的时间间隔可能不同，须分别制定核查计划，确定核查标准和方法。\n\n4.8.12.5期间核查的结果判定\n\n用En值判定，若En值的绝对值小于等于1，则核查结果满意，否则为不满意，需要重新检定或校准。\n\n4.8.12.6参考标准和标准物质的期间核查\n\n标准物质在使用期间应按计划进行期间核查，核查可根据检测工作的实际，从标准物质的性状是否有异常变化、储存环境是否符合要求等方面着手。如果在期间核查中发现标准物质已分解、产生异构体、浓度降低等变化，应停止使用，并追溯对之前检测结果的影响，执行不符合检测工作的控制。追溯对之前检测结果的影响。\n',150,'现用文件/程序文件/程序文件2022/03-2022仪器设备管理程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('8b2276b5-9533-428a-921e-00fa7af48002','00000000-0000-0000-0000-000000000001','a01641c9-dbde-4e87-ba79-dd149c4349ba','b90e5408-7e6d-4451-bd0a-fdeccf040627',NULL,'procedure:xztc_cx_31_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《不符合检测工作管理程序》 XZTC/CX-15-2019\n\n《实施纠正措施程序》 XZTC/CX-16-2022\n\n《实施预防措施程序》 XZTC/CX-17-2022\n\n《人员培训程序》 XZTC/CX-01-2019\n\n《设施与环境条件控制和维护程序》 XZTC/CX-02-2019\n\n《检测方法的选择与确认程序》 XZTC/CX-22-2022\n\n《开展新项目评审程序》 XZTC/CX-24-2022\n\n《计算机文件及数据控制程序》 XZTC/CX-26-2022\n\n《仪器设备管理程序》 XZTC/CX-03-2019\n\n《实施测量可溯源程序》 XZTC/CX-05-2019\n\n《仪器设备和标准物质期间核查程序》 XZTC/CX-04-2022\n\n《样品处置和管理程序》 XZTC/CX-28-2022\n\n《结果报告管理程序》 XZTC/CX-29-2019\n',160,'现用文件/程序文件/程序文件2022/31-2022检测工作的监督程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('8b5e9a9d-349f-4cae-9312-7f0cda7f9080','00000000-0000-0000-0000-000000000001','9f907214-fdff-400d-bd65-a376c631c875','619a08d7-264c-4a61-82aa-35e13cfa6e5d',NULL,'procedure:xztc_cx_07_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 发布公正性声明，批准和领导本公司的全体员工贯彻执行保证公正性措施；\n\n3.1.2 对执行中出现的问题给予及时的纠正，为何其严肃性和持久性；\n\n3.1.3 维护本公司的减压能力，保证管理体系的有效运行。\n\n3.2 技术负责人应：\n\n3.2.1 协助实验室主任维护本公司检验资源有效配置；\n\n3.2.2 不断努力提高检验技术水平，监督检验技术活动和结果的有效性；\n\n3.2.3始终不渝贯彻本公司的质量方针。\n\n3.3 质量负责人应：\n\n3.3.1 协助实验室主任维护所有的管理体系文件并保持其现行有效；\n\n3.3.2 监督管理体系的日常运行，使馆理体系的运行能够更加有效；\n\n3.3.3 及时向实验室主任反映体系的运行情况，提出改进建议，使管理体系不断完善；\n\n3.3.4调查违背公正性、诚信度的行为，并向公司主任报告工作。\n\n3.4 各部主任应:\n\n3.4.1 调查违背公正性、诚信度的行为，并向质量负责人报告工作；\n\n3.5 其他人员应：\n\n3.5.1 严格按照国家现行技术法规进行各项检验和其他活动，自觉抵制来自内部、外部的不正当的商业、财务、权利和其他方面的影响，保证检验工作的正常运行。\n',140,'现用文件/程序文件/程序文件2022/07-2022确保公正性程序.docx#职责','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('8ecf3389-84ed-4fd4-ab19-96ffad514722','00000000-0000-0000-0000-000000000001','40055ae1-3a24-466a-b70a-78bb7c26362a','0cadf789-6c6b-4b36-a6fc-a797e4657a0f',NULL,'procedure:xztc_cx_19_2022:source:process','','工作程序','process_step','### 工作程序\n\n4.1 记录的分类\n\n4.1.1 质量记录，管理体系运行中形成的记录主要包括：\n\n4.1.1.1 内部审核和管理评审记录；\n\n4.1.1.2 不符合、纠正、预防措施的记录；\n\n4.1.1.3 合同评审记录；\n\n4.1.1.4 检测分包记录；\n\n4.1.1.5 服务和供应品采购记录；\n\n4.1.1.6 人员培训和考核记录；\n\n4.1.1.7 服务客户及处理客户投诉记录；\n\n4.1.1.8 文件控制记录。\n\n4.1.2 技术记录，数据和信息主要包括；\n\n4.1.2.1 原始记录；\n\n4.1.2.2 导出数据；\n\n4.1.2.3 校准记录；\n\n4.1.2.4 检测报告；\n\n4.1.2.5 实验室间比对或能力验证记录；\n\n4.1.2.6 仪器设备运行检查记录等。\n\n4.2 记录的形式\n\n4.2.1 记录可以以纸张、电子媒体等形式保存。\n\n4.3 记录的格式和要求\n\n4.3.1 质量记录的格式及变更，按《文件控制程序》要求执行。\n\n4.3.2 技术记录的格式及变更，按主管部门的规定和《文件控制程序》中的要求执行。\n\n4.3.3 资料管理员随时发布记录格式的记录表格，确保各场所均能及时了解记录格式的变化有关信息并使用有效格式记录表格，严禁私自变更表格的格式或使用无效表格，以满足有关要求。\n\n4.3.4 质量记录的要求\n\n4.3.4.1 根据工作内容，做好有关记录的填写工作，记录应真实、齐全、及时、清晰、明了，记录必须有记录人签名，必要时需要审核人、批准人签字，记录要求使用钢笔或签字笔填写。\n\n4.3.5 技术记录的要求\n\n4.3.5.1 原始记录是检测结果的真实记载，检测人员应按记录格式所要求的的内容逐项认真、如实填写，其信息足以保证能在接近原条件下复现检测，包括每项实验室活动以及审查数据结果的日期和责任人；检测工作中实时填写，不得追记、补记，记录的填写应客观、真实、规范、准确、清晰、易于识别。\n\n4.3.5.2 原始记录中数值的单位必须采用法定计量单位。\n\n4.3.5.3 原始记录要求使用钢笔或签字笔填写，数据不得描改、涂改，如需修订时，应在作废数据上划一条下斜线（＝），将正确的数值填在上方，并有更改人签字或加盖更改人名章、修改的日期，原始记录中要求的内容应逐项填写，不得有空项，无需填写的项目划“/”，\n\n4.3.5.4 复（审）核人员在复（审）核原始记录过程中，无权更改检测结果。\n\n4.3.5.5 由计算机直接输出的原始记录或图谱，应注明样品（或检测）编号、检测日期。\n\n4.3.5.6 以电子形式储存的记录，检测室要留有备份，其保护和保密问题，执行\n\n《计算机文件及数据控制程序》。\n\n4.3.5.7 已存档的记录需经技术负责人/质量负责人批准后才能更改。记录填写\n\n完毕后，应及时交资料员保存。\n\n4.4 记录的标识\n\n4.4.1 资料管理员以表格编号、顺序号、页码、检测人签字、结果校核人签字等形式对记录进行标识。\n\n4.4.2 质量记录和技术记录的编号（见《文件控制程序》）。\n\n4.5 记录保管\n\n4.5.1 记录的编目\n\n4.5.1.1 资料管理员对其保存的记录，应按要求分类、保存并编目，以便于检索；\n\n4.5.1.2 质量记录、技术记录归档应填写《记录归档登记表》。\n\n4.5.2 查阅与复制\n\n4.5.2.1 本公司员工因工作需要借阅记录需经技术负责人/质量负责人同意，资料管理员填写《记录借阅登记表》。记录需要复制时，需经技术负责人/质量负责人同意才能复制。\n\n4.5.2.2 外单位人员一般不得借阅和复制记录，确因需要经技术负责人/质量负责人批准，填写《记录借阅登记表》；借阅时，资料管理员提示借阅人不得泄密和转移借阅，不得在记录上涂改、划线、丢失、损坏等，阅后及时交还管理人员，并办理归还手续。\n\n4.5.3 贮存\n\n4.5.3.1 记录贮存应安排适宜的贮存场所，应具备空气流通、防潮、防火、防霉变、防虫蛀、防丢失等措施，必要时应有温度和湿度控制措施，外来人员未经许可不得进入。\n\n4.5.3.2 资料管理员负责收集、整理，进行适当贮存。经整理编目后及时归档，并履行交接手续。\n\n4.5.3.3 资料管理员负责编制《质量记录清单及保存期限表》和《技术记录清单及保存期限表》，按相关要求合理规定贮存期限并进行有效贮存。\n\n4.5.3.3资料员负责对本公司各类记录的保存期限做出规定,编制《质量记录清单及保存期限表》，按相关要求合理规定贮存期限并进行有效贮存,本公司的记录保存年限应至少保存6年。如果法律法规、专业领域认可要求文件或客户规定了更长的保存期要求，本公司应满足这些要求。人员或设备记录应随同人员工作期\n\n间或设备使用时限全程保留，在人员调离或设备停止使用后，人员或设备技术记录应再保存3年。\n\n4.6 记录的保密\n\n4.6.1 记录应存放在指定场所，采取保密措施。\n\n4.6.2 借阅人员未经许可不得复制、摘抄或将记录带离指定场所，不得查阅其他无关记录。\n\n4.6.3 工作人员不得将客户的信息透露给其他客户。\n\n4.7 记录的销毁\n\n4.7.1 对逾期的记录，由资料管理员办理销毁申请，质量负责人/技术负责人批准后进行销毁。\n',150,'现用文件/程序文件/程序文件2022/19-2022记录控制程序.docx#工作程序','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('90e2ff19-6a2e-479e-8c73-56b523ee1c7f','00000000-0000-0000-0000-000000000001','cda70d11-6fd2-45dc-88ec-6b6b88267f6a','8fd66b6b-cf04-4f03-b795-e5e7a61f9695',NULL,'procedure:xztc_cx_25_2022:source:purpose','','目的','purpose','### 目的\n\n为了规范本公司检测工作的实施过程，保证检测工作质量，特编制本程序。\n',120,'现用文件/程序文件/程序文件2022/25-2022检测工作控制程序.docx#目的','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('9175c3c7-06ac-4336-90a3-cea365f003a4','00000000-0000-0000-0000-000000000001','f0487552-998f-4890-94df-49779d41b185','48e77eb2-f569-435f-b92e-7a4a99351f71',NULL,'procedure:xztc_cx_20_2022:source:scope','','范围','scope','### 范围\n\n适用于管理体系涉及的所有部门和所有要素的内部审核。\n',130,'现用文件/程序文件/程序文件2022/20-2022内部管理体系审核程序.docx#范围','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('91999a0e-316a-43ba-85dc-532756d66491','00000000-0000-0000-0000-000000000001','1e1e9194-f520-4a67-91ab-d313500615c8','e12e3730-cc7a-4ade-8704-2460e6762097',NULL,'procedure:xztc_cx_02_2022:element:facilities_environment','','要素落实：设施和环境条件','control_requirement','### 要素落实：设施和环境条件\n\n- 程序文件：XZTC/CX-02-2022 设施与环境条件控制和维护程序\n- 结构化重点：从程序正文拆分目的、范围、职责、流程步骤、控制要求和记录要求。\n- 记录表格：按程序文件中的记录要求建立或关联 schema，并在运行模块中形成证据。\n',200,'','effective',1,0,'2026-07-19 15:50:06','2026-07-19 15:50:06',NULL,NULL),('92641c71-50cd-4735-a1db-80b00c8739c8','00000000-0000-0000-0000-000000000001','544b293a-5553-4bfe-baef-80b1c8d9e410','a343bfe0-5a01-4e73-8d80-9e2fe7ca3f22',NULL,'procedure:xztc_cx_24_2022:source:purpose','','目的','purpose','### 目的\n\n为了满足客户的要求，本公司将不断开展新的检测项目。为此必须保证检测能力与项目将适应，所以要对新开展的项目进行评审。\n',120,'现用文件/程序文件/程序文件2022/24-2022开展新项目评审程序.docx#目的','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('9265e8b4-afd1-47bd-9834-3dfa6b064d5f','00000000-0000-0000-0000-000000000001','dc7146d9-e84c-407e-8e35-2515e05d7642','3b870297-530f-4b96-a1fd-83e397708084',NULL,'procedure:xztc_cx_05_2022:source:related_documents','','相关文件','text','### 相关文件\n\n《仪器设备管理程序》 XZTC/CX-03-2018\n\n《仪器设备和标准物质期间核查程序》 XZTC/CX-04-2018\n\n6.记录《仪器设备周期检定计划表》 XZTC/BG-05-01\n',160,'现用文件/程序文件/程序文件2022/05-2022实现测量可溯源程序.docx#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('929d24ac-ec43-4e86-8aad-22baaacf1eb3','00000000-0000-0000-0000-000000000001','544b293a-5553-4bfe-baef-80b1c8d9e410','a343bfe0-5a01-4e73-8d80-9e2fe7ca3f22',NULL,'procedure:xztc_cx_24_2022:source:responsibility','','职责','responsibility','### 职责\n\n3.1 实验室主任应：\n\n3.1.1 负责新项目计划的批准实施；\n\n3.1.2 根据评审结果对开展新项目进行批准。\n\n3.2 技术负责人应：\n\n3.2.1 组织对方案及实施计划的可行性进行评审并对所需资源进行配置。\n\n3.3 检测部应：\n\n3.3.1 提出开展新项目检测的需求；\n\n3.3.2 负责开展新的检测项目计划的制定、负责分析方法的验证、验证报告的编制。\n',140,'现用文件/程序文件/程序文件2022/24-2022开展新项目评审程序.docx#职责','effective',1,0,'2026-07-19 15:50:08','2026-07-19 15:50:08',NULL,NULL),('93576d4b-f430-41b9-9b40-f648eb9db49a','00000000-0000-0000-0000-000000000001','f9f936aa-4e68-449e-a6bc-814098b9b434','f6b1b203-1e7a-48e5-953a-c9de0ae2969d',NULL,'procedure:xztc_cx_07_02_2022:source:related_documents','','相关文件','text','### 相关文件\n\n1.《确保公正性程序》 XZTC/CX-07-2022\n\n2.《保护客户机密信息程序》 XZTC/CX-06-2022\n\n3.《实施纠正措施程序》 XZTC/CX-16-2022\n\n4.《实施预防措施程序》 XZTC/CX-17-2022\n\n搀 昀 渀 瀀\n\n樀\n\n氀\n\n鐀\n\n阀\n\n批注框文本 Char\n\n二、保护客户机密信息和所有权程序\n\n、。〃々〉》」』】〕〗！＂＇），．：；？］｀｜｝～￠\n\n〈《「『【〔〖（．［｛￡￥\n\n吓渀嘃踀奌＀威騀娿谀搌\n',160,'现用文件/程序文件/程序文件2022/07-02-2022防止商业贿赂程序.doc#相关文件','effective',1,0,'2026-07-19 15:50:07','2026-07-19 15:50:07',NULL,NULL),('962dab5a-7408-4280-8235-708834587e68','00000000-0000-0000-0000-000000000001','bc8c7454-2b19-4837-aeb8-b3d9a1f13d25','30de644c-9b17-4536-86cf-18ad00d7b322',NULL,'procedure:xztc_cx_16_2022:source:related_documents','','相关